var e=JSON.parse(`[{"name":"Aarakocra","source":"DMG","edition":"classic","size":["M"],"speed":{"walk":20,"fly":50},"ability":[{"dex":2,"wis":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Dive Attack","entries":[{"type":"text","content":"If you are flying and dive at least 30 ft. straight toward a target and then hit it with a melee weapon attack, the attack deals an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> damage to the target."}]},{"type":"section","name":"Talons","entries":[{"type":"text","content":"You are proficient with your unarmed strikes, which deal <span class=\\"text-red-400 font-semibold\\">1d4</span> slashing damage on a hit."}]},{"type":"section","name":"Language","entries":[{"type":"text","content":"You can speak, read, and write Auran."}]}],"subraces":[],"traits":["Natural Weapon","NPC Race"],"languages":[{"auran":true}],"page":282},{"name":"Aarakocra","source":"EEPC","edition":"classic","size":["M"],"speed":{"walk":25,"fly":50},"ability":[{"dex":2,"wis":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Aarakocra reach maturity by age 3. Compared to humans, aarakocra don't usually live longer than 30 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most aarakocra are good and rarely choose sides when it comes to law and chaos. Tribal leaders and warriors might be lawful, while explorers and adventurers might tend toward chaotic."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aarakocra are about 5 feet tall. They have thin, lightweight bodies that weigh between 80 and 100 pounds. Your size is Medium."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"You have a flying speed of 50 feet. To use this speed, you can't be wearing medium or heavy armor."}]},{"type":"section","name":"Talons","entries":[{"type":"text","content":"Your talons are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Language","entries":[{"type":"text","content":"You can speak, read, and write Common, Aarakocra, and Auran."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true,"auran":true}],"page":5},{"name":"Aarakocra","source":"MPMM","edition":"classic","size":["M"],"speed":{"walk":30,"fly":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Flight","entries":[{"type":"text","content":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]},{"type":"section","name":"Talons","entries":[{"type":"text","content":"You have talons that you can use to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Wind Caller","entries":[{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> spell with this trait, without requiring a material component. Once you cast the spell with this trait, you can't do so again until you finish a long rest. You can also cast the spell using any spell slots you have of 2nd level or higher."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for when you cast <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> with this trait (choose when you select this race)."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"auran":true}],"page":5},{"name":"Aasimar","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"wis":1,"cha":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Aasimar mature at the same rate as humans but live a few years longer."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aasimar are built like well-proportioned humans. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your celestial heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of grey."}]},{"type":"section","name":"Celestial Resistance","entries":[{"type":"text","content":"You have resistance to necrotic and radiant damage."}]},{"type":"section","name":"Celestial Legacy","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=light\\" class=\\"text-dnd-gold hover:underline\\">light</a> cantrip. Once you reach 3rd level, you can cast the <a href=\\"/spells?search=lesser restoration\\" class=\\"text-dnd-gold hover:underline\\">lesser restoration</a> spell once with this trait, and you regain the ability to do so when you finish a long rest. Once you reach 5th level, you can cast the <a href=\\"/spells?search=daylight\\" class=\\"text-dnd-gold hover:underline\\">daylight</a> spell once with this trait, and you regain the ability to do so when you finish a long rest. Charisma is your spellcasting ability for these spells."}]},{"type":"section","name":"Language","entries":[{"type":"text","content":"You can speak, read, and write Common and Celestial."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"celestial":true}],"page":286},{"name":"Aasimar","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Celestial Resistance","entries":[{"type":"text","content":"You have resistance to necrotic damage and radiant damage."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Healing Hands","entries":[{"type":"text","content":"As an action, you can touch a creature and roll a number of d4s equal to your proficiency bonus. The creature regains a number of hit points equal to the total rolled. Once you use this trait, you can't use it again until you finish a long rest."}]},{"type":"section","name":"Light Bearer","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=light\\" class=\\"text-dnd-gold hover:underline\\">light</a> cantrip. Charisma is your spellcasting ability for it."}]},{"type":"section","name":"Celestial Revelation","entries":[{"type":"text","content":"When you reach 3rd level, choose one of the revelation options below. Thereafter, you can use a bonus action to unleash the celestial energy within yourself, gaining the benefits of that revelation. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation below, you can't use it again until you finish a long rest."},{"type":"list","items":[{"type":"item","name":"Necrotic Shroud","entry":"Your eyes briefly become pools of darkness, and ghostly, flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you that can see you must succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become <i class=\\"text-dnd-gold\\">frightened</i> of you until the end of your next turn. Until the transformation ends, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."},{"type":"item","name":"Radiant Consumption","entry":"Searing light temporarily radiates from your eyes and mouth. For the duration, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes radiant damage equal to your proficiency bonus. Until the transformation ends, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."},{"type":"item","name":"Radiant Soul","entry":"Two luminous, spectral wings sprout from your back temporarily. Until the transformation ends, you have a flying speed equal to your walking speed, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true,"celestial":true}],"page":7},{"name":"Aasimar","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Aasimar mature at the same rate as humans, but they can live up to 160 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aasimar have the same range of height and weight as humans."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Blessed with a radiant soul, your vision can easily cut through darkness. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Celestial Resistance","entries":[{"type":"text","content":"You have resistance to necrotic damage and radiant damage."}]},{"type":"section","name":"Healing Hands","entries":[{"type":"text","content":"As an action, you can touch a creature and cause it to regain a number of hit points equal to your level. Once you use this trait, you can't use it again until you finish a long rest."}]},{"type":"section","name":"Light Bearer","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=light\\" class=\\"text-dnd-gold hover:underline\\">light</a> cantrip. Charisma is your spellcasting ability for it."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Celestial."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"celestial":true}],"page":104},{"name":"Aasimar","source":"XPHB","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Celestial Resistance","entries":[{"type":"text","content":"You have <i>Resistance</i> to Necrotic damage and Radiant damage."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Healing Hands","entries":[{"type":"text","content":"As a <b>Magic</b> action, you touch a creature and roll a number of d4s equal to your <i>Proficiency</i>. The creature regains a number of <i>Hit Points</i> equal to the total rolled. Once you use this trait, you can't use it again until you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Light Bearer","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=Light\\" class=\\"text-dnd-gold hover:underline\\">Light</a> cantrip. Charisma is your spellcasting ability for it."}]},{"type":"section","name":"Celestial Revelation","entries":[{"type":"text","content":"When you reach character level 3, you can transform as a <i>Bonus Action</i> using one of the options below (choose the option each time you transform). The transformation lasts for 1 minute or until you end it (no action required). Once you transform, you can't do so again until you finish a <i>Long Rest</i>."},{"type":"text","content":"Once on each of your turns before the transformation ends, you can deal extra damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your <i>Proficiency</i>, and the extra damage's type is either Necrotic for Necrotic Shroud or Radiant for Heavenly Wings and Inner Radiance."},{"type":"text","content":"Here are the transformation options:"},{"type":"list","items":[{"type":"item","name":"Heavenly Wings","entry":"Two spectral wings sprout from your back temporarily. Until the transformation ends, you have a <i>Fly Speed</i> equal to your <i>Speed</i>."},{"type":"item","name":"Inner Radiance","entry":"Searing light temporarily radiates from your eyes and mouth. For the duration, you shed <i>Bright Light</i> in a 10-foot radius and <i>Dim Light</i> for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes Radiant damage equal to your <i>Proficiency</i>."},{"type":"item","name":"Necrotic Shroud","entry":"Your eyes briefly become pools of darkness, and flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you must succeed on a Charisma saving throw (DC 8 plus your Charisma modifier and <i>Proficiency</i>) or have the <i class=\\"text-dnd-gold\\">Frightened</i> condition until the end of your next turn."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true,"celestial":true}],"page":186},{"name":"Aetherborn","source":"PSK","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2,"choose":{"from":["str","dex","con","int","wis"],"count":2}}],"skillProficiencies":[{"intimidation":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Aetherborn come into being as adults and live no more than a few years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"As a rule, aetherborn are driven by hedonism and self-interest, making them neutral at best and thoroughly evil at worst. Neutral aetherborn might devote much of their time (and wealth) to parties and social activity, while evil aetherborn are usually involved in the criminal underworld."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aetherborn are about the same size as humans, ranging from 5 to 6 feet tall. They are quite light—only about 100 pounds—and their weight diminishes as they age and more and more of their substance returns to the aethersphere. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Born of Aether","entries":[{"type":"text","content":"You have resistance to necrotic damage."}]},{"type":"section","name":"Menacing","entries":[{"type":"text","content":"You have proficiency in the <i>Intimidation</i> skill."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and two other languages of your choice."}]},{"type":"text","content":"{\\"type\\":\\"inset\\",\\"name\\":\\"Gift of the Aetherborn\\",\\"entries\\":[\\"An unknown aetherborn, desperately seeking a means to extend their short life, discovered a process of transformation that prolonged their existence—by giving them the ability to feed on the life essence of other beings. Since then, other aetherborn have learned and carried out this monstrous transformation, and aetherborn with this \\\\\\"gift\\\\\\" have become a small minority among an already small population.\\",\\"A gifted aetherborn has the ability to drain the life essence of other beings. Similar to the way heat is transferred from a warm object to a cold one, a gifted aetherborn need only touch another living being with a clawed hand to draw life essence out, fueling their own continued existence while draining strength and vitality from their victim.\\",\\"For many aetherborn, living as they do for indulgence and instant gratification, the concepts of \\\\\\"want\\\\\\" and \\\\\\"need\\\\\\" are virtually synonymous. But Aetherborn with this gift understand what it is to truly need, for they develop a hunger for life essence that far exceeds any desires they might have felt before their transformation. A gifted aetherborn who abstains from this feeding deteriorates even more rapidly than other aetherborn, while enduring unspeakable agony caused by the deprivation of life energy.\\",\\"At the DM's option, an aetherborn character can research methods of achieving this dark \\\\\\"gift.\\\\\\" The process is similar to inventing and manufacturing a rare magic item (see \\\\\\"<i>Inventing and Manufacturing Devices</i>\\\\\\" earlier in this document). But rather than aether, the process requires a variety of rare unguents and unusual ingredients that make up the cost of researching and undergoing the transformation.\\",\\"An aetherborn with this gift gains the Drain Life ability: a natural attack that deals <span class=\\"text-red-400 font-semibold\\">1d6</span> necrotic damage and restores the same number of hit points to the aetherborn. However, if the aetherborn goes for 7 days without dealing this damage, their hit point maximum is reduced by <span class=\\"text-green-400 font-mono\\">1d6</span> per week. This reduction can't be removed until the aetherborn has used their Drain Life ability and completed a long rest.\\"]}"}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":2}],"page":17},{"name":"Astral Elf","source":"AAG","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."}]},{"type":"section","name":"Astral Fire","entries":[{"type":"text","content":"You know one of the following cantrips of your choice: <a href=\\"/spells?search=dancing lights\\" class=\\"text-dnd-gold hover:underline\\">dancing lights</a>, <a href=\\"/spells?search=light\\" class=\\"text-dnd-gold hover:underline\\">light</a>, or <a href=\\"/spells?search=sacred flame\\" class=\\"text-dnd-gold hover:underline\\">sacred flame</a>. Intelligence, Wisdom, or Charisma is your spellcasting ability for it (choose when you select this race)."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Starlight Step","entries":[{"type":"text","content":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Astral Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you remain conscious."},{"type":"text","content":"Whenever you finish this trance, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the <i>Player's Handbook</i>. You mystically acquire these proficiencies by drawing them from shared elven memory and the experiences of entities on the Astral Plane, and you retain them until you finish your next long rest."}]}],"subraces":[],"traits":["Improved Resting","Tool Proficiency","Weapon Proficiency"],"page":10},{"name":"Autognome","source":"AAG","edition":"classic","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Construct."}]},{"type":"section","name":"Armored Casing","entries":[{"type":"text","content":"You are encased in thin metal or some other durable material. While you aren't wearing armor, your base Armor Class is 13 + your Dexterity modifier."}]},{"type":"section","name":"Built for Success","entries":[{"type":"text","content":"You can add a <span class=\\"text-green-400 font-mono\\">d4</span> to one attack roll, ability check, or saving throw you make, and you can do so after seeing the <span class=\\"text-green-400 font-mono\\">d20</span> roll but before the effects of the roll are resolved. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Healing Machine","entries":[{"type":"text","content":"If the <a href=\\"/spells?search=mending\\" class=\\"text-dnd-gold hover:underline\\">mending</a> spell is cast on you, you can spend a Hit Die, roll it, and regain a number of hit points equal to the roll plus your Constitution modifier (minimum of 1 hit point)."},{"type":"text","content":"In addition, your creator designed you to benefit from several spells that preserve life but that normally don't affect Constructs: <a href=\\"/spells?search=cure wounds\\" class=\\"text-dnd-gold hover:underline\\">cure wounds</a>, <a href=\\"/spells?search=healing word\\" class=\\"text-dnd-gold hover:underline\\">healing word</a>, <a href=\\"/spells?search=mass cure wounds\\" class=\\"text-dnd-gold hover:underline\\">mass cure wounds</a>, <a href=\\"/spells?search=mass healing word\\" class=\\"text-dnd-gold hover:underline\\">mass healing word</a>, and <a href=\\"/spells?search=spare the dying\\" class=\\"text-dnd-gold hover:underline\\">spare the dying</a>."}]},{"type":"section","name":"Mechanical Nature","entries":[{"type":"text","content":"You have resistance to poison damage and immunity to disease, and you have advantage on saving throws against being <i class=\\"text-dnd-gold\\">paralyzed</i> or <i class=\\"text-dnd-gold\\">poisoned</i>. You don't need to eat, drink, or breathe."}]},{"type":"section","name":"Sentry's Rest","entries":[{"type":"text","content":"When you take a long rest, you spend at least 6 hours in an inactive, motionless state, instead of sleeping. In this state, you appear inert, but you remain conscious."}]},{"type":"section","name":"Specialized Design","entries":[{"type":"text","content":"You gain two tool proficiencies of your choice, selected from the <i>Player's Handbook</i>."}]}],"subraces":[],"traits":["Improved Resting","Natural Armor"],"page":11},{"name":"Aven","source":"PSA","edition":"classic","size":["M"],"speed":{"walk":25,"fly":30},"ability":[{"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Like humans, aven reach adulthood in their late teens and can theoretically live into their 80s. Of course, most find a glorious (or inglorious) death long before that point."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most aven lean toward some form of neutrality. Ibis-headed aven, focused more on knowledge than any other virtue, are usually neutral. Hawk-headed aven are inclined toward lawful neutral."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aven stand from 5 to 6 feet tall, but their bodies are slender and their bones are partially hollow to facilitate their flight. Your size is Medium."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your flying speed if you are encumbered.) "}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Aven."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":15},{"name":"Aven","source":"PSD","edition":"classic","size":["M"],"speed":{"walk":25,"fly":30},"ability":[{"dex":2,"wis":2}],"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Like humans, aven reach adulthood in their late teens and can live into their 80s."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Aven are inclined toward the lawful good alignment of the Church of Serra"}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Aven stand from 5 to 6 feet tall, but their bodies are slender and their bones are partially hollow to facilitate their flight. Your size is Medium."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for <i>encumbrance</i>, you can't use your flying speed if you are encumbered.) "}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Aven."}]},{"type":"section","name":"Hawkeyed","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill. In addition, attacking at long range doesn't impose disadvantage on your ranged weapon attack rolls."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":6},{"name":"Boggart","source":"LFL","edition":"classic","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus."},{"type":"text","content":"You can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]}],"subraces":[],"traits":[],"page":20},{"name":"Bugbear","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"dex":1}],"skillProficiencies":[{"stealth":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Bugbears reach adulthood at age 16 and live up to 80 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Bugbears live on the fringes of society even in Darguun, where they value self-sufficiency and violence. They are generally chaotic, organizing in loose tribes under charismatic and powerful leaders."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Long-Limbed","entries":[{"type":"text","content":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Sneaky","entries":[{"type":"text","content":"You are proficient in the <i>Stealth</i> skill."}]},{"type":"section","name":"Surprise Attack","entries":[{"type":"text","content":"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> damage to it. You can use this trait only once per combat."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race","Powerful Build"],"languages":[{"common":true,"goblin":true}],"page":25},{"name":"Bugbear","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"stealth":true}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Long-Limbed","entries":[{"type":"text","content":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Sneaky","entries":[{"type":"text","content":"You are proficient in the <i>Stealth</i> skill. In addition, without squeezing, you can move through and stop in a space large enough for a Small creature."}]},{"type":"section","name":"Surprise Attack","entries":[{"type":"text","content":"If you hit a creature with an attack roll, the creature takes an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> damage if it hasn't taken a turn yet in the current combat."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"goblin":true}],"page":8},{"name":"Bugbear","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"dex":1}],"skillProficiencies":[{"stealth":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Bugbears reach adulthood at age 16 and live up to 80 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Bugbears are between 6 and 8 feet tall and weigh between 250 and 350 pounds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Long-Limbed","entries":[{"type":"text","content":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Sneaky","entries":[{"type":"text","content":"You are proficient in the <i>Stealth</i> skill."}]},{"type":"section","name":"Surprise Attack","entries":[{"type":"text","content":"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> damage to it. You can use this trait only once per combat."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race","Powerful Build"],"languages":[{"common":true,"goblin":true}],"page":119},{"name":"Bullywug","source":"DMG","edition":"classic","size":["M"],"speed":{"walk":20,"swim":40},"ability":[{"int":-2,"cha":-2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Speak with Frogs and Toads","entries":[{"type":"text","content":"You can communicate simple concepts to frogs and toads when you speak in Bullywug."}]},{"type":"section","name":"Swamp Camouflage","entries":[{"type":"text","content":"You have advantage on Dexterity (<i>Stealth</i>) checks made to hide in swampy terrain."}]},{"type":"section","name":"Standing Leap","entries":[{"type":"text","content":"Your long jump is up to 20 feet and your high jump is up to 10 feet, with or without a running start."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Bullywug."}]}],"subraces":[],"traits":["Amphibious","NPC Race"],"languages":[{"other":true}],"page":282},{"name":"Centaur","source":"GGR","edition":"classic","size":["M"],"speed":40,"ability":[{"str":2,"wis":1}],"skillProficiencies":[{"choose":{"from":["animal handling","medicine","nature","survival"]}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Centaurs mature and age at about the same rate as humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Centaurs are inclined toward neutrality. Those who join the Selesnya are more often neutral good, while those who join the Gruul are typically chaotic neutral."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Centaurs stand between 6 and 7 feet tall, with their equine bodies reaching about 4 feet at the withers. Your size is Medium."}]},{"type":"section","name":"Fey","entries":[{"type":"text","content":"Your creature type is fey, rather than humanoid."}]},{"type":"section","name":"Charge","entries":[{"type":"text","content":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."}]},{"type":"section","name":"Hooves","entries":[{"type":"text","content":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Equine Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push or drag."},{"type":"text","content":"In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."}]},{"type":"section","name":"Survivor","entries":[{"type":"text","content":"You have proficiency in one of the following skills of your choice: <i>Animal Handling</i>, <i>Medicine</i>, <i>Nature</i>, or <i>Survival</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Sylvan. Sylvan is widely spoken in the Selesnya Conclave, for it is rich in vocabulary to describe natural phenomena and spiritual forces."}]}],"subraces":[],"traits":["Natural Weapon","Powerful Build"],"languages":[{"common":true,"sylvan":true}],"page":15},{"name":"Centaur","source":"MOT","edition":"classic","size":["M"],"speed":40,"ability":[{"str":2,"wis":1}],"skillProficiencies":[{"choose":{"from":["animal handling","medicine","nature","survival"]}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Centaurs mature and age at about the same rate as humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Centaurs are inclined toward neutrality. Those who join the Selesnya are more often neutral good, while those who join the Gruul are typically chaotic neutral."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Centaurs stand between 6 and 7 feet tall, with their equine bodies reaching about 4 feet at the withers. Your size is Medium."}]},{"type":"section","name":"Fey","entries":[{"type":"text","content":"Your creature type is fey, rather than humanoid."}]},{"type":"section","name":"Charge","entries":[{"type":"text","content":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."}]},{"type":"section","name":"Hooves","entries":[{"type":"text","content":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Equine Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push or drag."},{"type":"text","content":"In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."}]},{"type":"section","name":"Survivor","entries":[{"type":"text","content":"You have proficiency in one of the following skills of your choice: <i>Animal Handling</i>, <i>Medicine</i>, <i>Nature</i>, or <i>Survival</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Sylvan. Sylvan is widely spoken in the Selesnya Conclave, for it is rich in vocabulary to describe natural phenomena and spiritual forces."}]}],"subraces":[],"traits":["Natural Weapon","Powerful Build"],"languages":[{"common":true,"sylvan":true}],"page":18},{"name":"Centaur","source":"MPMM","edition":"classic","size":["M"],"speed":40,"skillProficiencies":[{"choose":{"from":["animal handling","medicine","nature","survival"]}}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Charge","entries":[{"type":"text","content":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."}]},{"type":"section","name":"Equine Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push or drag."},{"type":"text","content":"In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet instead of the normal 1 extra foot."}]},{"type":"section","name":"Hooves","entries":[{"type":"text","content":"You have hooves that you can use to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Natural Affinity","entries":[{"type":"text","content":"Your fey connection to nature gives you an intuitive connection to the natural world and the animals within it. You therefore have proficiency in one of the following skills of your choice: <i>Animal Handling</i>, <i>Medicine</i>, <i>Nature</i>, or <i>Survival</i>."}]}],"subraces":[],"traits":["Natural Weapon","Powerful Build"],"languages":[{"common":true,"sylvan":true}],"page":9},{"name":"Changeling","source":"EFA","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["deception","insight","intimidation","persuasion"],"count":2}}],"entries":[{"type":"section","name":"Changeling Instincts","entries":[{"type":"text","content":"Thanks to your connection to the fey realm, you gain proficiency in two of the following skills of your choice: <i>Deception</i>, <i>Insight</i>, <i>Intimidation</i>, <i>Performance</i>, or <i>Persuasion</i>."}]},{"type":"section","name":"Shape-Shifter","entries":[{"type":"text","content":"As an action, you can shape-shift to change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight and can change your size between Medium and Small. You can make yourself appear as a member of another playable species, though none of your game statistics change. You can't duplicate the appearance of an individual you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. This trait doesn't change your clothing and equipment."},{"type":"text","content":"While shape-shifted with this trait, you have <i>Advantage</i> on Charisma checks."},{"type":"text","content":"You stay in the new form until you take an action to revert to your true form."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":2}],"page":34},{"name":"Changeling","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2,"choose":{"from":["str","dex","con","int","wis"],"count":1}}],"skillProficiencies":[{"choose":{"from":["deception","insight","intimidation","persuasion"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Changelings mature slightly faster than humans but share a similar lifespan—typically a century or less. While a changeling can transform to conceal their age, the effects of aging affect them similarly to humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Changelings tend toward pragmatic neutrality, and few changelings embrace evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Shapechanger","entries":[{"type":"text","content":"As an action, you can change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight, but not so much that your size changes. You can make yourself appear as a member of another race, though none of your game statistics change. You can't duplicate the appearance of a creature you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren't changed by this trait."},{"type":"text","content":"You stay in the new form until you use an action to revert to your true form or until you die."}]},{"type":"section","name":"Changeling Instincts","entries":[{"type":"text","content":"You gain proficiency with two of the following skills of your choice: <i>Deception</i>, <i>Insight</i>, <i>Intimidation</i>, and <i>Persuasion</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and two other languages of your choice."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":2}],"page":17},{"name":"Changeling","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["deception","insight","intimidation","performance","persuasion"],"count":2}}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Changeling Instincts","entries":[{"type":"text","content":"Thanks to your connection to the fey realm, you gain proficiency with two of the following skills of your choice: <i>Deception</i>, <i>Insight</i>, <i>Intimidation</i>, <i>Performance</i>, or <i>Persuasion</i>."}]},{"type":"section","name":"Shapechanger","entries":[{"type":"text","content":"As an action, you change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height between Medium and Small. You can make yourself appear as a member of another race, though none of your game statistics change. You can't duplicate the appearance of an individual you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren't changed by this trait."},{"type":"text","content":"You stay in the new form until you use an action to revert to your true form or until you die."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":2}],"page":10},{"name":"Custom Lineage","source":"TCE","edition":"classic","size":["S","M"],"speed":30,"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"amount":2}}],"skillProficiencies":[{"any":1}],"entries":[{"type":"text","content":"Instead of choosing one of the game's races for your character at 1st level, you can use the following traits to represent your character's lineage, giving you full control over how your character's origin shaped them:"},{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a humanoid. You determine your appearance and whether you resemble any of your kin."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Small or Medium (your choice)."}]},{"type":"section","name":"Feat","entries":[{"type":"text","content":"You gain one <i>feat</i> of your choice for which you qualify."}]},{"type":"section","name":"Variable Trait","entries":[{"type":"text","content":"You gain one of the following options of your choice: (a) <i>darkvision</i> with a range of 60 feet or (b) proficiency in one skill of your choice."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for your character."}]},{"type":"text","content":"Your race is considered to be a Custom Lineage for any game feature that requires a certain race, such as elf or dwarf."}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":8},{"name":"Deep Gnome","source":"MPMM","edition":"classic","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a gnome for any prerequisite or effect that requires you to be a gnome."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Gift of the Svirfneblin","entries":[{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=nondetection\\" class=\\"text-dnd-gold hover:underline\\">nondetection</a> spell with it, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these using spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Gnomish Magic Resistance","entries":[{"type":"text","content":"You have advantage on Intelligence, Wisdom, and Charisma saving throws against spells."}]},{"type":"section","name":"Svirfneblin Camouflage","entries":[{"type":"text","content":"When you make a Dexterity (<i>Stealth</i>) check, you can make the check with advantage. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":["Magic Resistance"],"page":11},{"name":"Dhampir","source":"RHW","edition":"classic","size":["S","M"],"speed":{"walk":35,"climb":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Spider Climb","entries":[{"type":"text","content":"You have a <i>Climb Speed</i> equal to your <i>Speed</i>. When you reach character level 3, you can move up, down, and across vertical surfaces and along ceilings while leaving your hands free."}]},{"type":"section","name":"Trace of Undeath","entries":[{"type":"text","content":"You have <i>Resistance</i> to Necrotic damage."}]},{"type":"section","name":"Vampiric Bite","entries":[{"type":"text","content":"When you use your <i>Unarmed Strike</i> and deal damage, you can choose to bite with your fangs. You deal Piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> plus your Constitution modifier instead of the normal damage of an <i>Unarmed Strike</i>."},{"type":"text","content":"In addition, when you deal this damage to a creature that isn't a Construct or an Undead, you can empower yourself in one of the following ways:"},{"type":"list","items":[{"type":"item","name":"Drain","entry":"You regain <i>Hit Points</i> equal to the Piercing damage dealt."},{"type":"item","name":"Strengthen","entry":"You gain a bonus to the next ability check or attack roll you make within the next minute; the bonus is equal to the Piercing damage dealt."}]},{"type":"text","content":"You can empower yourself with this trait a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."}]}],"subraces":[],"traits":["Natural Weapon"],"page":28},{"name":"Dhampir","source":"VRGR","edition":"classic","size":["S","M"],"speed":{"walk":35,"climb":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you gain this lineage."}]},{"type":"section","name":"Ancestral Legacy","entries":[{"type":"text","content":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it."},{"type":"text","content":"If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."}]},{"type":"section","name":"Deathless Nature","entries":[{"type":"text","content":"You don't need to breathe."}]},{"type":"section","name":"Spider Climb","entries":[{"type":"text","content":"You have a climbing speed equal to your walking speed. In addition, at 3rd level, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free."}]},{"type":"section","name":"Vampiric Bite","entries":[{"type":"text","content":"Your fanged bite is a natural weapon, which counts as a simple melee weapon with which you are proficient. You add your Constitution modifier, instead of your Strength modifier, to the attack and damage rolls when you attack with this bite. It deals <span class=\\"text-red-400 font-semibold\\">1d4</span> piercing damage on a hit. While you are missing half or more of your hit points, you have advantage on attack rolls you make with this bite."},{"type":"text","content":"When you attack with this bite and hit a creature that isn't a Construct or an Undead, you can empower yourself in one of the following ways of your choice:"},{"type":"list","items":["You regain hit points equal to the piercing damage dealt by the bite.","You gain a bonus to the next ability check or attack roll you make; the bonus equals the piercing damage dealt by the bite"]},{"type":"text","content":"You can empower yourself with this bite a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":["Natural Weapon"],"page":16},{"name":"Dragonborn","source":"PHB","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Young dragonborn grow quickly. They walk hours after hatching, attain the size and development of a 10-year-old human child by the age of 3, and reach adulthood by 15. They live to be around 80."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Dragonborn are taller and heavier than humans, standing well over 6 feet tall and averaging almost 250 pounds. Your size is Medium."}]},{"type":"section","name":"Draconic Ancestry","entries":[{"type":"text","content":"You have draconic ancestry. Choose one type of dragon from the Draconic Ancestry table. Your breath weapon and damage resistance are determined by the dragon type, as shown in the table."},{"type":"table","caption":"Draconic Ancestry","colLabels":["Dragon","Damage Type","Breath Weapon"],"rows":[["Black","Acid","5 by 30 ft. line (Dex. save)"],["Blue","Lightning","5 by 30 ft. line (Dex. save)"],["Brass","Fire","5 by 30 ft. line (Dex. save)"],["Bronze","Lightning","5 by 30 ft. line (Dex. save)"],["Copper","Acid","5 by 30 ft. line (Dex. save)"],["Gold","Fire","15 ft. cone (Dex. save)"],["Green","Poison","15 ft. cone (Con. save)"],["Red","Fire","15 ft. cone (Dex. save)"],["Silver","Cold","15 ft. cone (Con. save)"],["White","Cold","15 ft. cone (Con. save)"]]}]},{"type":"section","name":"Breath Weapon","entries":[{"type":"text","content":"You can use your action to exhale destructive energy. Your draconic ancestry determines the size, shape, and damage type of the exhalation."},{"type":"text","content":"When you use your breath weapon, each creature in the area of the exhalation must make a saving throw, the type of which is determined by your draconic ancestry. The DC for this saving throw equals 8 + your Constitution modifier + your proficiency bonus. A creature takes <span class=\\"text-red-400 font-semibold\\">2d6</span> damage on a failed save, and half as much damage on a successful one. The damage increases to <span class=\\"text-red-400 font-semibold\\">3d6</span> at 6th level, <span class=\\"text-red-400 font-semibold\\">4d6</span> at 11th level, and <span class=\\"text-red-400 font-semibold\\">5d6</span> at 16th level."},{"type":"text","content":"After you use your breath weapon, you can't use it again until you complete a short or long rest."}]},{"type":"section","name":"Damage Resistance","entries":[{"type":"text","content":"You have resistance to the damage type associated with your draconic ancestry."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Draconic. Draconic is thought to be one of the oldest languages and is often used in the study of magic. The language sounds harsh to most other creatures and includes numerous hard consonants and sibilants."}]}],"subraces":[],"traits":["Uncommon Race"],"languages":[{"common":true,"draconic":true}],"page":32},{"name":"Dragonborn","source":"XPHB","edition":"one","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Draconic Ancestry","entries":[{"type":"text","content":"Your lineage stems from a dragon progenitor. Choose the kind of dragon from the Draconic Ancestors table. Your choice affects your Breath Weapon and <i>Damage</i> <i>Resistance</i> traits as well as your appearance."},{"type":"table","caption":"Draconic Ancestors","colLabels":["Dragon","Damage Type"],"rows":[["Black","Acid"],["Blue","Lightning"],["Brass","Fire"],["Bronze","Lightning"],["Copper","Acid"],["Gold","Fire"],["Green","Poison"],["Red","Fire"],["Silver","Cold"],["White","Cold"]]}]},{"type":"section","name":"Breath Weapon","entries":[{"type":"text","content":"When you take the <b>Attack</b> action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot <i>Cone [Area of Effect]</i> or a 30-foot <i>Line [Area of Effect]</i> that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and <i>Proficiency</i>). On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">1d10</span> damage of the type determined by your Draconic Ancestry trait. On a successful save, a creature takes half as much damage. This damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach character levels 5 (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."},{"type":"text","content":"You can use this Breath Weapon a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Damage Resistance","entries":[{"type":"text","content":"You have <i>Resistance</i> to the damage type determined by your Draconic Ancestry trait."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Draconic Flight","entries":[{"type":"text","content":"When you reach character level 5, you can channel draconic magic to give yourself temporary flight. As a <i>Bonus Action</i>, you sprout spectral wings on your back that last for 10 minutes or until you retract the wings (no action required) or have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition. During that time, you have a <i>Fly Speed</i> equal to your <i>Speed</i>. Your wings appear to be made of the same energy as your Breath Weapon. Once you use this trait, you can't use it again until you finish a <i>Long Rest</i>."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"draconic":true}],"page":187},{"name":"Dragonborn (Chromatic)","source":"FTD","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Chromatic Ancestry","entries":[{"type":"text","content":"You have a chromatic dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Chromatic Ancestry table. This determines the damage type for your other traits, as shown in the table."},{"type":"table","caption":"Chromatic Ancestry","colLabels":["Dragon","Damage Type"],"rows":[["Black","Acid"],["Blue","Lightning"],["Green","Poison"],["Red","Fire"],["White","Cold"]]}]},{"type":"section","name":"Breath Weapon","entries":[{"type":"text","content":"When you take the <b>Attack</b> action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">1d10</span> damage of the type associated with your Chromatic Ancestry. On a successful save, it takes half as much damage. This damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."},{"type":"text","content":"You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Draconic Resistance","entries":[{"type":"text","content":"You have resistance to the damage type associated with your Chromatic Ancestry."}]},{"type":"section","name":"Chromatic Warding","entries":[{"type":"text","content":"Starting at 5th level, as an action, you can channel your draconic energy to protect yourself. For 1 minute, you become immune to the damage type associated with your Chromatic Ancestry. Once you use this trait, you can't do so again until you finish a long rest."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"draconic":true}],"page":10},{"name":"Dragonborn (Gem)","source":"FTD","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Gem Ancestry","entries":[{"type":"text","content":"You have a gem dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Gem Ancestry table. This determines the damage type for your other traits, as shown in the table."},{"type":"table","caption":"Gem Ancestry","colLabels":["Dragon","Damage Type"],"rows":[["Amethyst","Force"],["Crystal","Radiant"],["Emerald","Psychic"],["Sapphire","Thunder"],["Topaz","Necrotic"]]}]},{"type":"section","name":"Breath Weapon","entries":[{"type":"text","content":"When you take the <b>Attack</b> action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">1d10</span> damage of the type associated with your Gem Ancestry. On a successful save, it takes half as much damage. This damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."},{"type":"text","content":"You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Draconic Resistance","entries":[{"type":"text","content":"You have resistance to the damage type associated with your Gem Ancestry."}]},{"type":"section","name":"Psionic Mind","entries":[{"type":"text","content":"You can send telepathic messages to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand these messages, but it must be able to understand at least one language to comprehend them."}]},{"type":"section","name":"Gem Flight","entries":[{"type":"text","content":"Starting at 5th level, you can use a bonus action to manifest spectral wings on your body. These wings last for 1 minute. For the duration, you gain a flying speed equal to your walking speed and can hover. Once you use this trait, you can't do so again until you finish a long rest."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"draconic":true}],"page":11},{"name":"Dragonborn (Metallic)","source":"FTD","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Metallic Ancestry","entries":[{"type":"text","content":"You have a metallic dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Metallic Ancestry table. This determines the damage type for your other traits, as shown in the table."},{"type":"table","caption":"Metallic Ancestry","colLabels":["Dragon","Damage Type"],"rows":[["Brass","Fire"],["Bronze","Lightning"],["Copper","Acid"],["Gold","Fire"],["Silver","Cold"]]}]},{"type":"section","name":"Breath Weapon","entries":[{"type":"text","content":"When you take the <b>Attack</b> action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">1d10</span> damage of the type associated with your Metallic Ancestry. On a successful save, it takes half as much damage. This damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."},{"type":"text","content":"You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Draconic Resistance","entries":[{"type":"text","content":"You have resistance to the damage type associated with your Metallic Ancestry."}]},{"type":"section","name":"Metallic Breath Weapon","entries":[{"type":"text","content":"At 5th level, you gain a second breath weapon. When you take the <b>Attack</b> action on your turn, you can replace one of your attacks with an exhalation in a 15-foot cone. The save DC for this breath is 8 + your Constitution modifier + your proficiency bonus. Whenever you use this trait, choose one:"},{"type":"list","items":[{"type":"item","name":"Enervating Breath","entry":"Each creature in the cone must succeed on a Constitution saving throw or become <i class=\\"text-dnd-gold\\">incapacitated</i> until the start of your next turn."},{"type":"item","name":"Repulsion Breath","entry":"Each creature in the cone must succeed on a Strength saving throw or be pushed 20 feet away from you and be knocked <i class=\\"text-dnd-gold\\">prone</i>."}]},{"type":"text","content":"Once you use your Metallic Breath Weapon, you can't do so again until you finish a long rest."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"draconic":true}],"page":12},{"name":"Duergar","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a dwarf for any prerequisite or effect that requires you to be a dwarf."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Duergar Magic","entries":[{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> spell on yourself with this trait, without requiring a material component. Starting at 5th level, you can also cast the <a href=\\"/spells?search=invisibility\\" class=\\"text-dnd-gold hover:underline\\">invisibility</a> spell on yourself with this trait, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Dwarven Resilience","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">poisoned</i> condition on yourself. You also have resistance to poison damage."}]},{"type":"section","name":"Psionic Fortitude","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> or <i class=\\"text-dnd-gold\\">stunned</i> condition on yourself."}]}],"subraces":[],"traits":[],"page":12},{"name":"Dwarf","source":"PHB","edition":"classic","size":["M"],"speed":25,"ability":[{"con":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Dwarves mature at the same rate as humans, but they're considered young until they reach the age of 50. On average, they live about 350 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Dwarves stand between 4 and 5 feet tall and average about 150 pounds. Your size is Medium."}]},{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your speed is not reduced by wearing heavy armor."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Dwarven Resilience","entries":[{"type":"text","content":"You have advantage on saving throws against poison, and you have resistance against poison damage."}]},{"type":"section","name":"Dwarven Combat Training","entries":[{"type":"text","content":"You have proficiency with the <b>battleaxe</b>, <b>handaxe</b>, <b>light hammer</b>, and <b>warhammer</b>."}]},{"type":"section","name":"Tool Proficiency","entries":[{"type":"text","content":"You gain proficiency with the <b>artisan's tools</b> of your choice: <b>Smith's tools</b>, <b>brewer's supplies</b>, or <b>mason's tools</b>."}]},{"type":"section","name":"Stonecunning","entries":[{"type":"text","content":"Whenever you make an Intelligence (<i>History</i>) check related to the origin of stonework, you are considered proficient in the <i>History</i> skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Dwarvish. Dwarvish is full of hard consonants and guttural sounds, and those characteristics spill over into whatever other language a dwarf might speak."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"dwarvish":true}],"page":18},{"name":"Dwarf","source":"XPHB","edition":"one","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 120 feet."}]},{"type":"section","name":"Dwarven Resilience","entries":[{"type":"text","content":"You have <i>Resistance</i> to Poison damage. You also have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Poisoned</i> condition."}]},{"type":"section","name":"Dwarven Toughness","entries":[{"type":"text","content":"Your <i>Hit Points</i> maximum increases by 1, and it increases by 1 again whenever you gain a level."}]},{"type":"section","name":"Stonecunning","entries":[{"type":"text","content":"As a <i>Bonus Action</i>, you gain <i>Tremorsense</i> with a range of 60 feet for 10 minutes. You must be on a stone surface or touching a stone surface to use this <i>Tremorsense</i>. The stone can be natural or worked."},{"type":"text","content":"You can use this <i>Bonus Action</i> a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"dwarvish":true}],"page":188},{"name":"Dwarf (Kaladesh)","source":"PSK","edition":"classic","size":["M"],"speed":25,"ability":[{"con":2,"wis":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Dwarves mature at the same rate as humans, but they're considered young until they reach the age of 50. On average, they live about 350 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most dwarves are lawful, believing firmly in the benefits of a well-ordered society. They tend toward good as well, with a strong sense of fair play and a belief that everyone deserves to share in the benefits of a just order."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Dwarves stand around 5 feet tall and average about 150 pounds. Your size is Medium."}]},{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your base walking speed is 25 feet. Your speed is not reduced by wearing heavy armor."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground in your race's ancient past, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Dwarven Resilience","entries":[{"type":"text","content":"You have advantage on saving throws against poison, and you have resistance against poison damage."}]},{"type":"section","name":"Dwarven Toughness","entries":[{"type":"text","content":"Your hit point maximum increases by 1, and it increases by 1 every time you gain a level."}]},{"type":"section","name":"Artisan's Expertise","entries":[{"type":"text","content":"You gain proficiency with two kinds of <i>artisan's tools</i> of your choice. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. In addition, whenever you make an Intelligence (<i>History</i>) check related to the origin of any architectural construction (including buildings, public works such as canals and aqueducts, and the massive cogwork that underlies much of the construction of Ghirapur), you are considered proficient in the <i>History</i> skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Dwarvish. Dwarvish is full of hard consonants and guttural sounds, and those characteristics spill over into whatever other language a dwarf might speak."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"dwarvish":true}],"page":19},{"name":"Eladrin","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"perception":true}],"entries":[{"type":"text","content":"<i>Choose your eladrin's season: autumn, winter, spring, or summer. When finishing a long rest, you can change your season. See the \\"Info\\" tab for more information.</i>"},{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Fey Step","entries":[{"type":"text","content":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"text","content":"When you reach 3rd level, your Fey Step gain an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race):"},{"type":"list","items":[{"type":"item","name":"Autumn","entry":"Immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be <i class=\\"text-dnd-gold\\">charmed</i> by you for 1 minute, or until you or your companions deal any damage to the creatures."},{"type":"item","name":"Winter","entry":"When you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be <i class=\\"text-dnd-gold\\">frightened</i> of you until the end of your next turn."},{"type":"item","name":"Spring","entry":"When you use your Fey Step, you can touch one willing creature within 5 feet of you. That creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you."},{"type":"item","name":"Summer","entry":"Immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your proficiency bonus."}]}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."},{"type":"text","content":"Whenever you finish this trance, you can change your season, and you can gain two proficiencies that you don't have, each one with a <i>weapon</i> or a <i>tool</i> of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}]}],"subraces":[],"traits":["Improved Resting","Tool Proficiency","Weapon Proficiency"],"page":13},{"name":"Elf","source":"LFL","edition":"one","size":["M"],"speed":30,"skillProficiencies":[{"choose":{"from":["insight","perception","survival"]}}],"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Elven Lineage","entries":[{"type":"text","content":"You are part of a lineage that grants you supernatural abilities. Choose a lineage from the Elven Lineages table. You gain the level 1 benefit of that lineage."},{"type":"text","content":"When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a <i>Long Rest</i>. You can also cast the spell using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."},{"type":"table","caption":"Elven Lineages","colLabels":["Lineage","Level 1","Level 3","Level 5"],"rows":[["Lorwyn","You know the <a href=\\"/spells?search=Thorn Whip\\" class=\\"text-dnd-gold hover:underline\\">Thorn Whip</a> cantrip. Whenever you finish a <i>Long Rest</i>, you can replace that cantrip with a different cantrip from the <i>Druid spell list</i>.","<a href=\\"/spells?search=Command\\" class=\\"text-dnd-gold hover:underline\\">Command</a>","<a href=\\"/spells?search=Silence\\" class=\\"text-dnd-gold hover:underline\\">Silence</a>"],["Shadowmoor","The range of your <i>Darkvision</i> increases to 120 feet. You also know the <a href=\\"/spells?search=Starry Wisp\\" class=\\"text-dnd-gold hover:underline\\">Starry Wisp</a> cantrip.","<a href=\\"/spells?search=Heroism\\" class=\\"text-dnd-gold hover:underline\\">Heroism</a>","<a href=\\"/spells?search=Gentle Repose\\" class=\\"text-dnd-gold hover:underline\\">Gentle Repose</a>"]]}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Charmed</i> condition."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Insight</i>, <i>Perception</i>, or <i>Survival</i> skill."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a <i>Long Rest</i> in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."}]}],"subraces":[],"traits":["Improved Resting"],"languages":[{"common":true,"elvish":true}],"page":189},{"name":"Elf","source":"PHB","edition":"classic","size":["M"],"speed":30,"ability":[{"dex":2}],"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i>, and magic can't put you to sleep."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"Elves don't need to sleep. Instead, they meditate deeply, remaining semiconscious, for 4 hours a day. (The Common word for such meditation is \\"trance.\\") While meditating, you can dream after a fashion; such dreams are actually mental exercises that have become reflexive through years of practice. After resting in this way, you gain the same benefit that a human does from 8 hours of sleep."},{"type":"text","content":"If you meditate during a long rest, you finish the rest after only 4 hours. You otherwise obey all the rules for a long rest; only the duration is changed."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Elvish. Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires."}]}],"subraces":[],"traits":["Improved Resting"],"languages":[{"common":true,"elvish":true}],"page":21},{"name":"Elf","source":"XPHB","edition":"one","size":["M"],"speed":30,"skillProficiencies":[{"choose":{"from":["insight","perception","survival"]}}],"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Elven Lineage","entries":[{"type":"text","content":"You are part of a lineage that grants you supernatural abilities. Choose a lineage from the Elven Lineages table. You gain the level 1 benefit of that lineage."},{"type":"text","content":"When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a <i>Long Rest</i>. You can also cast the spell using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."},{"type":"table","caption":"Elven Lineages","colLabels":["Lineage","Level 1","Level 3","Level 5"],"rows":[["Drow","The range of your <i>Darkvision</i> increases to 120 feet. You also know the <a href=\\"/spells?search=Dancing Lights\\" class=\\"text-dnd-gold hover:underline\\">Dancing Lights</a> cantrip.","<a href=\\"/spells?search=Faerie Fire\\" class=\\"text-dnd-gold hover:underline\\">Faerie Fire</a>","<a href=\\"/spells?search=Darkness\\" class=\\"text-dnd-gold hover:underline\\">Darkness</a>"],["High Elf","You know the <a href=\\"/spells?search=Prestidigitation\\" class=\\"text-dnd-gold hover:underline\\">Prestidigitation</a> cantrip. Whenever you finish a <i>Long Rest</i>, you can replace that cantrip with a different <i>cantrip from the Wizard spell list</i>.","<a href=\\"/spells?search=Detect Magic\\" class=\\"text-dnd-gold hover:underline\\">Detect Magic</a>","<a href=\\"/spells?search=Misty Step\\" class=\\"text-dnd-gold hover:underline\\">Misty Step</a>"],["Wood Elf","Your <i>Speed</i> increases to 35 feet. You also know the <a href=\\"/spells?search=Druidcraft\\" class=\\"text-dnd-gold hover:underline\\">Druidcraft</a> cantrip.","<a href=\\"/spells?search=Longstrider\\" class=\\"text-dnd-gold hover:underline\\">Longstrider</a>","<a href=\\"/spells?search=Pass without Trace\\" class=\\"text-dnd-gold hover:underline\\">Pass without Trace</a>"]]}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Charmed</i> condition."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Insight</i>, <i>Perception</i>, or <i>Survival</i> skill."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a <i>Long Rest</i> in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."}]}],"subraces":[],"traits":["Improved Resting"],"languages":[{"common":true,"elvish":true}],"page":189},{"name":"Elf (Kaladesh)","source":"PSK","edition":"classic","size":["M"],"speed":30,"ability":[{"dex":2,"wis":1}],"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Elves love freedom, variety, and self-expression, so they lean strongly toward the gentler aspects of chaos. They value and protect others' freedom as well as their own, and they are more often good than not."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Elf Weapon Training","entries":[{"type":"text","content":"You have proficiency with the <b>longsword</b>, <b>shortsword</b>, <b>shortbow</b>, and <b>longbow</b>."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i>, and magic can't put you to sleep."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"Elves don't need to sleep. Instead, they meditate deeply, remaining semiconscious, for 4 hours a day. (The Common word for such meditation is \\"trance.\\") While meditating, you can dream after a fashion; such dreams are actually mental exercises that have become reflexive through years of practice. After resting in this way, you gain the same benefit that a human does from 8 hours of sleep."},{"type":"text","content":"If you meditate during a long rest, you finish the rest after only 4 hours. You otherwise obey all the rules for a long rest; only the duration is changed."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Elvish. Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires."}]},{"type":"section","name":"Elf Culture","entries":[{"type":"text","content":"The elves of Kaladesh don't organize themselves into nations or tribes. Still, they recognize three distinct cultural groups among their kind—though in truth these groupings are more like attitudes or alignments with regard to the rest of society and the use of technology. Choose one of these cultures."}]}],"subraces":[],"traits":["Improved Resting"],"languages":[{"common":true,"elvish":true}],"page":20},{"name":"Elf (Zendikar)","source":"PSZ","edition":"classic","size":["M"],"speed":30,"ability":[{"wis":2}],"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Elves love freedom, variety, and self-expression, so they lean strongly toward the gentler aspects of chaos. They value and protect others' freedom as well as their own, and they are more often good than not."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i>, and magic can't put you to sleep."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Elvish. Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"elvish":true}],"page":18},{"name":"Faerie","source":"LFL","edition":"classic","size":["S"],"speed":{"walk":30,"fly":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Fairy Magic","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=druidcraft\\" class=\\"text-dnd-gold hover:underline\\">druidcraft</a> cantrip. Starting at 3rd level, you can cast the <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> spell with this trait. Once you cast <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> or <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]},{"type":"section","name":"Faerie Lineage","entries":[{"type":"text","content":"As a native of either Lorwyn and Shadowmoor, you may gain additional traits."},{"type":"list","items":[{"type":"item","name":"Lorwyn","entry":"You do not gain any additional traits."},{"type":"item","name":"Shadowmoor","entry":"You have <i>Darkvision</i> with a range of 120 feet."}]}]}],"subraces":[],"traits":[],"page":14},{"name":"Fairy","source":"MPMM","edition":"classic","size":["S"],"speed":{"walk":30,"fly":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Fairy Magic","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=druidcraft\\" class=\\"text-dnd-gold hover:underline\\">druidcraft</a> cantrip. Starting at 3rd level, you can cast the <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> spell with this trait. Once you cast <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> or <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]}],"subraces":[],"traits":[],"page":14},{"name":"Fairy","source":"WBtW","edition":"classic","size":["S"],"speed":{"walk":30,"fly":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]},{"type":"section","name":"Fairy Magic","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=druidcraft\\" class=\\"text-dnd-gold hover:underline\\">druidcraft</a> cantrip."},{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> spell with this trait. Once you cast <a href=\\"/spells?search=faerie fire\\" class=\\"text-dnd-gold hover:underline\\">faerie fire</a> or <a href=\\"/spells?search=enlarge/reduce\\" class=\\"text-dnd-gold hover:underline\\">enlarge/reduce</a> with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]}],"subraces":[],"traits":[],"page":12},{"name":"Firbolg","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Firbolg Magic","entries":[{"type":"text","content":"You can cast <a href=\\"/spells?search=detect magic\\" class=\\"text-dnd-gold hover:underline\\">detect magic</a> and <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a> spells with this trait. When you use this version of <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a>, you can seem up to 3 feet shorter or taller. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Hidden Step","entries":[{"type":"text","content":"As a bonus action, you can magically turn <i class=\\"text-dnd-gold\\">invisible</i> until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Speech of Beast and Leaf","entries":[{"type":"text","content":"You have the ability to communicate in a limited manner with Beasts, Plants, and vegetation. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"elvish":true,"giant":true}],"page":15},{"name":"Firbolg","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"wis":2,"str":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"As humanoids related to the fey, firbolg have long lifespans. A firbolg reaches adulthood around 30, and the oldest of them can live for 500 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Firbolg are between 7 and 8 feet tall and weigh between 240 and 300 pounds. Your size is Medium."}]},{"type":"section","name":"Firbolg Magic","entries":[{"type":"text","content":"You can cast <a href=\\"/spells?search=detect magic\\" class=\\"text-dnd-gold hover:underline\\">detect magic</a> and <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a> with this trait, using Wisdom as your spellcasting ability for them. Once you cast either spell, you can't cast it again with this trait until you finish a short or long rest. When you use this version of <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a>, you can seem up to 3 feet shorter than normal, allowing you to more easily blend in with humans and elves."}]},{"type":"section","name":"Hidden Step","entries":[{"type":"text","content":"As a bonus action, you can magically turn <i class=\\"text-dnd-gold\\">invisible</i> until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Speech of Beast and Leaf","entries":[{"type":"text","content":"You have the ability to communicate in a limited manner with beasts and plants. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Elvish, and Giant."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"elvish":true,"giant":true}],"page":107},{"name":"Flamekin","source":"LFL","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fire Resistance","entries":[{"type":"text","content":"You have resistance to fire damage."}]},{"type":"section","name":"Reach to the Blaze","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=produce flame\\" class=\\"text-dnd-gold hover:underline\\">produce flame</a> cantrip. Starting at 3rd level, you can cast the <a href=\\"/spells?search=burning hands\\" class=\\"text-dnd-gold hover:underline\\">burning hands</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=flame blade\\" class=\\"text-dnd-gold hover:underline\\">flame blade</a> spell with this trait, without a material component. Once you cast <a href=\\"/spells?search=burning hands\\" class=\\"text-dnd-gold hover:underline\\">burning hands</a> or <a href=\\"/spells?search=flame blade\\" class=\\"text-dnd-gold hover:underline\\">flame blade</a> with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]}],"subraces":[],"traits":[],"page":16},{"name":"Genasi","source":"EEPC","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Independent and self-reliant, genasi tend toward a neutral alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"primordial":true}],"page":9},{"name":"Genasi","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"primordial":true}],"page":16},{"name":"Giff","source":"AAG","edition":"classic","size":["M"],"speed":{"walk":30,"swim":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Astral Spark","entries":[{"type":"text","content":"Your psychic connection to the Astral Plane enables you to mystically access a spark of divine power, which you can channel through your weapons. When you hit a target with a <i>simple or martial weapon</i>, you can cause the target to take extra force damage equal to your proficiency bonus."},{"type":"text","content":"You can use this trait a number of times equal to your proficiency bonus, but you can use it no more than once per turn. You regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Firearms Mastery","entries":[{"type":"text","content":"You have a mystical connection to firearms that traces back to the gods of the giff, who delighted in such weapons. You have proficiency with all firearms and ignore the <i>LD</i> property of any firearm. In addition, attacking at long range with a firearm doesn't impose disadvantage on your attack roll."}]},{"type":"section","name":"Hippo Build","entries":[{"type":"text","content":"You have advantage on Strength-based ability checks and Strength saving throws. In addition, you count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]}],"subraces":[],"traits":["Powerful Build"],"page":12},{"name":"Gith","source":"MTF","edition":"classic","size":["M"],"speed":30,"ability":[{"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Gith reach adulthood in their late teens and live for about a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Gith are taller and leaner than humans, with most a slender 6 feet in height."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Gith."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":96},{"name":"Githyanki","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"any":1}],"entries":[{"type":"section","name":"Astral Knowledge","entries":[{"type":"text","content":"You can mystically access a reservoir of experiences of entities connected to the Astral Plane. Whenever you finish a long rest, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the Player's Handbook, as you momentarily project your consciousness into the Astral Plane. These proficiencies last until the end of your next long rest."}]},{"type":"section","name":"Githyanki Psionics","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=mage hand\\" class=\\"text-dnd-gold hover:underline\\">mage hand</a> cantrip, and the hand is <i class=\\"text-dnd-gold\\">invisible</i> when you cast the cantrip with this trait."},{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=jump\\" class=\\"text-dnd-gold hover:underline\\">jump</a> spell with this trait. Starting at 5th level, you can also cast <a href=\\"/spells?search=misty step\\" class=\\"text-dnd-gold hover:underline\\">misty step</a> with it. Once you cast <a href=\\"/spells?search=jump\\" class=\\"text-dnd-gold hover:underline\\">jump</a> or <a href=\\"/spells?search=misty step\\" class=\\"text-dnd-gold hover:underline\\">misty step</a> with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."}]},{"type":"section","name":"Psychic Resilience","entries":[{"type":"text","content":"You have resistance to psychic damage."}]}],"subraces":[],"traits":["Weapon Proficiency"],"page":18},{"name":"Githzerai","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Githzerai Psionics","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=mage hand\\" class=\\"text-dnd-gold hover:underline\\">mage hand</a> cantrip, and the hand is <i class=\\"text-dnd-gold\\">invisible</i> when you cast the cantrip with this trait."},{"type":"text","content":"Starting at 3rd level, you can cast the <a href=\\"/spells?search=shield\\" class=\\"text-dnd-gold hover:underline\\">shield</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=detect thoughts\\" class=\\"text-dnd-gold hover:underline\\">detect thoughts</a> spell with it. Once you cast <a href=\\"/spells?search=shield\\" class=\\"text-dnd-gold hover:underline\\">shield</a> or <a href=\\"/spells?search=detect thoughts\\" class=\\"text-dnd-gold hover:underline\\">detect thoughts</a> spell with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."}]},{"type":"section","name":"Mental Discipline","entries":[{"type":"text","content":"Your innate psychic defenses grant you advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> and <i class=\\"text-dnd-gold\\">frightened</i> conditions on yourself."}]},{"type":"section","name":"Psychic Resilience","entries":[{"type":"text","content":"You have resistance to psychic damage."}]}],"subraces":[],"traits":[],"page":19},{"name":"Gnoll","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"int":-2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Bite","entries":[{"type":"text","content":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Rampage","entries":[{"type":"text","content":"When you reduce a creature to 0 hit points with a melee attack on your turn, you can take a bonus action to move up to half your speed and make a bite attack."}]}],"subraces":[],"traits":["Natural Weapon","NPC Race"],"page":282},{"name":"Gnome","source":"PHB","edition":"classic","size":["S"],"speed":25,"ability":[{"int":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Gnomes mature at the same rate humans do, and most are expected to settle down into an adult life by around age 40. They can live 350 to almost 500 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Gnomes are between 3 and 4 feet tall and average about 40 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Gnome Cunning","entries":[{"type":"text","content":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Gnomish. The Gnomish language, which uses the Dwarvish script, is renowned for its technical treatises and its catalogs of knowledge about the natural world."}]}],"subraces":[],"traits":["Uncommon Race"],"languages":[{"common":true,"gnomish":true}],"page":35},{"name":"Gnome","source":"XPHB","edition":"one","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Gnomish Cunning","entries":[{"type":"text","content":"You have <i>Advantage</i> on Intelligence, Wisdom, and Charisma saving throws."}]},{"type":"section","name":"Gnomish Lineage","entries":[{"type":"text","content":"You are part of a lineage that grants you supernatural abilities. Choose one of the following options; whichever one you choose, Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage):"},{"type":"list","items":[{"type":"item","name":"Forest Gnome","entry":"You know the <a href=\\"/spells?search=Minor Illusion\\" class=\\"text-dnd-gold hover:underline\\">Minor Illusion</a> cantrip. You also always have the <a href=\\"/spells?search=Speak with Animals\\" class=\\"text-dnd-gold hover:underline\\">Speak with Animals</a> spell prepared. You can cast it without a spell slot a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>. You can also use any spell slots you have to cast the spell."},{"type":"item","name":"Rock Gnome","entry":"You know the <a href=\\"/spells?search=Mending\\" class=\\"text-dnd-gold hover:underline\\">Mending</a> and <a href=\\"/spells?search=Prestidigitation\\" class=\\"text-dnd-gold hover:underline\\">Prestidigitation</a> cantrips. In addition, you can spend 10 minutes casting <a href=\\"/spells?search=Prestidigitation\\" class=\\"text-dnd-gold hover:underline\\">Prestidigitation</a> to create a Tiny clockwork device (AC 5, 1 HP), such as a toy, fire starter, or music box. When you create the device, you determine its function by choosing one effect from <a href=\\"/spells?search=Prestidigitation\\" class=\\"text-dnd-gold hover:underline\\">Prestidigitation</a>; the device produces that effect whenever you or another creature takes a <i>Bonus Action</i> to activate it with a touch. If the chosen effect has options within it, you choose one of those options for the device when you create it. For example, if you choose the spell's ignite-extinguish effect, you determine whether the device ignites or extinguishes fire; the device doesn't do both. You can have three such devices in existence at a time, and each falls apart 8 hours after its creation or when you dismantle it with a touch as a <b>Utilize</b> action."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true,"gnomish":true}],"page":191},{"name":"Gnome (Deep)","source":"DMG","edition":"classic","size":["S"],"speed":20,"ability":[{"str":1,"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Innate Spellcasting","entries":[{"type":"text","content":"You have an innate ability to cast the following spells, requiring no material components:"},{"type":"list","items":["At will:","1/day each:"]},{"type":"text","content":"Intelligence is your spellcasting ability for these spells."}]},{"type":"section","name":"Stone Camouflage","entries":[{"type":"text","content":"You have advantage on Dexterity (<i>Stealth</i>) checks to hide in rocky terrain."}]},{"type":"section","name":"Gnome Cunning","entries":[{"type":"text","content":"You have advantage on Intelligence, Wisdom, and Charisma saving throws against magic."}]},{"type":"section","name":"Superior Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Gnomish, Terran, and Undercommon."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"gnomish":true,"terran":true,"undercommon":true}],"page":282},{"name":"Goblin","source":"DMG","edition":"classic","size":["S"],"speed":30,"ability":[{"str":-2,"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"common":true,"goblin":true}],"page":282},{"name":"Goblin","source":"ERLW","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2,"con":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goblins reach adulthood at age 8 and live up to 60 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"goblin":true}],"page":26},{"name":"Goblin","source":"GGR","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2,"con":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goblins reach adulthood at age 8 and live up to 60 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"goblin":true}],"page":16},{"name":"Goblin","source":"MPMM","edition":"classic","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus."},{"type":"text","content":"You can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"goblin":true}],"page":20},{"name":"Goblin","source":"PSZ","edition":"classic","size":["S"],"speed":25,"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goblins mature faster than humans, reaching adulthood at around age 12. They also age noticeably faster than humans, and even the most cautious goblins rarely live longer than 50 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most goblins are wildly chaotic, though they have no particular inclination toward good or evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goblins average about 3 feet tall and weigh about 40 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]},{"type":"section","name":"Grit","entries":[{"type":"text","content":"You have resistance to fire damage and psychic damage. In addition, when you are wearing no armor, your AC is equal to 11 + your Dexterity modifier."}]}],"subraces":[],"traits":["Natural Armor"],"languages":[{"common":true,"goblin":true}],"page":16},{"name":"Goblin","source":"VGM","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2,"con":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goblins reach adulthood at age 8 and live up to 60 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race"],"languages":[{"common":true,"goblin":true}],"page":119},{"name":"Goblin (Dankwood)","source":"AWM","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2,"wis":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goblins reach adulthood at age 8 and live up to 60 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Fury of the Small","entries":[{"type":"text","content":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Nimble Escape","entries":[{"type":"text","content":"You can take the <b>Disengage</b> or <b>Hide</b> action as a bonus action on each of your turns."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race"],"languages":[{"common":true,"goblin":true}],"page":35},{"name":"Goliath","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"athletics":true}],"entries":[{"type":"section","name":"Little Giant","entries":[{"type":"text","content":"You have proficiency in the <i>Athletics</i> skill, and you count as one size larger when determining your carrying weight and the weight you can push, drag, or lift."}]},{"type":"section","name":"Mountain Born","entries":[{"type":"text","content":"You have resistance to cold damage. You also naturally acclimate to high altitudes, even if you've never been to one. This includes elevations above 20,000 feet."}]},{"type":"section","name":"Stone's Endurance","entries":[{"type":"text","content":"You can supernaturally draw on unyielding stone to shrug off harm. When you take damage, you can use your reaction to roll a <span class=\\"text-green-400 font-mono\\">d12</span>. Add your Constitution modifier to the number rolled and reduce the damage by that total."},{"type":"text","content":"You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"giant":true}],"page":21},{"name":"Goliath","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"athletics":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Goliaths have lifespans comparable to humans. They enter adulthood in their late teens and usually live less than a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Goliaths are between 7 and 8 feet tall and weigh between 280 and 340 pounds. Your size is Medium."}]},{"type":"section","name":"Natural Athlete","entries":[{"type":"text","content":"You have proficiency in the <i>Athletics</i> skill."}]},{"type":"section","name":"Stone's Endurance","entries":[{"type":"text","content":"You can focus yourself to occasionally shrug off injury. When you take damage, you can use your reaction to roll a <span class=\\"text-green-400 font-mono\\">d12</span>. Add your Constitution modifier to the number rolled, and reduce the damage by that total. After you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Mountain Born","entries":[{"type":"text","content":"You have resistance to cold damage. You're also acclimated to high altitude, including elevations above 20,000 feet."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Giant."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"giant":true}],"page":108},{"name":"Goliath","source":"XPHB","edition":"one","size":["M"],"speed":35,"skillProficiencies":null,"entries":[{"type":"section","name":"Giant Ancestry","entries":[{"type":"text","content":"You are descended from Giants. Choose one of the following benefits—a supernatural boon from your ancestry; you can use the chosen benefit a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>:"},{"type":"list","items":[{"type":"item","name":"Cloud's Jaunt (Cloud Giant)","entry":"As a <i>Bonus Action</i>, you magically teleport up to 30 feet to an unoccupied space you can see."},{"type":"item","name":"Fire's Burn (Fire Giant)","entry":"When you hit a target with an attack roll and deal damage to it, you can also deal <span class=\\"text-red-400 font-semibold\\">1d10</span> Fire damage to that target."},{"type":"item","name":"Frost's Chill (Frost Giant)","entry":"When you hit a target with an attack roll and deal damage to it, you can also deal <span class=\\"text-red-400 font-semibold\\">1d6</span> Cold damage to that target and reduce its <i>Speed</i> by 10 feet until the start of your next turn."},{"type":"item","name":"Hill's Tumble (Hill Giant)","entry":"When you hit a Large or smaller creature with an attack roll and deal damage to it, you can give that target the <i class=\\"text-dnd-gold\\">Prone</i> condition."},{"type":"item","name":"Stone's Endurance (Stone Giant)","entry":"When you take damage, you can take a <i>Reaction</i> to roll <span class=\\"text-green-400 font-mono\\">1d12</span>. Add your Constitution modifier to the number rolled and reduce the damage by that total."},{"type":"item","name":"Storm's Thunder (Storm Giant)","entry":"When you take damage from a creature within 60 feet of you, you can take a <i>Reaction</i> to deal <span class=\\"text-red-400 font-semibold\\">1d8</span> Thunder damage to that creature."}]}]},{"type":"section","name":"Large Form","entries":[{"type":"text","content":"Starting at character level 5, you can change your size to Large as a <i>Bonus Action</i> if you're in a big enough space. This transformation lasts for 10 minutes or until you end it (no action required). For that duration, you have <i>Advantage</i> on Strength checks, and your <i>Speed</i> increases by 10 feet. Once you use this trait, you can't use it again until you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You have <i>Advantage</i> on any ability check you make to end the <i class=\\"text-dnd-gold\\">Grappled</i> condition. You also count as one size larger when determining your carrying capacity."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"giant":true}],"page":192},{"name":"Grimlock","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"cha":-2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Blindsight","entries":[{"type":"text","content":"You have no eyes, and cannot be <i class=\\"text-dnd-gold\\">blinded</i>. You can perceive your surroundings within 30 ft., or 10 ft. while <i class=\\"text-dnd-gold\\">deafened</i>. You are considered blind beyond this radius."}]},{"type":"section","name":"Keen Hearing and Smell","entries":[{"type":"text","content":"You have advantage on Wisdom (<i>Perception</i>) checks that rely on hearing or smell."}]},{"type":"section","name":"Stone Camouflage","entries":[{"type":"text","content":"You have advantage on Dexterity (<i>Stealth</i>) checks made to hide in rocky terrain."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Undercommon."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"undercommon":true}],"page":282},{"name":"Grung","source":"OGA","edition":"classic","size":["S"],"speed":{"walk":25,"climb":25},"ability":[{"dex":2,"con":1}],"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Grungs mature to adulthood in a single year, but have been known to live up to 50 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most grungs are lawful, having been raised in a strict caste system. They tend toward evil as well, coming from a culture where social advancement occurs rarely, and most often because another member of your army has died and there is no one else of that caste to fill the vacancy."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Grungs stand between 2½ and 3½ feet tall and average about 30 pounds. Your size is Small."}]},{"type":"section","name":"Arboreal Alertness","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Poison Immunity","entries":[{"type":"text","content":"You're immune to poison damage and the <i class=\\"text-dnd-gold\\">poisoned</i> condition."}]},{"type":"section","name":"Poisonous Skin","entries":[{"type":"text","content":"Any creature that grapples you or otherwise comes into direct contact with your skin must succeed on a DC 12 Constitution saving throw or become <i class=\\"text-dnd-gold\\">poisoned</i> for 1 minute. A <i class=\\"text-dnd-gold\\">poisoned</i> creature no longer in direct contact with you can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."},{"type":"text","content":"You can also apply this poison to any piercing weapon as part of an attack with that weapon, though when you hit the poison reacts differently. The target must succeed on a DC 12 Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">2d4</span> poison damage."}]},{"type":"section","name":"Standing Leap","entries":[{"type":"text","content":"Your long jump is up to 25 feet and your high jump is up to 15 feet, with or without a running start."}]},{"type":"section","name":"Water Dependency","entries":[{"type":"text","content":"If you fail to immerse yourself in water for at least 1 hour during a day, you suffer one level of <i class=\\"text-dnd-gold\\">exhaustion</i> at the end of that day. You can only recover from this <i class=\\"text-dnd-gold\\">exhaustion</i> through magic or by immersing yourself in water for at least 1 hour."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Grung."}]}],"subraces":[],"traits":["Amphibious"],"languages":[{"other":true}],"page":4},{"name":"Hadozee","source":"AAG","edition":"classic","size":["S","M"],"speed":{"walk":30,"climb":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Dexterous Feet","entries":[{"type":"text","content":"As a bonus action, you can use your feet to manipulate an object, open or close a door or container, or pick up or set down a Tiny object."}]},{"type":"section","name":"Glide","entries":[{"type":"text","content":"When you fall at least 10 feet above the ground, you can use your reaction to extend your skin membranes to glide horizontally a number of feet equal to your walking speed, and you take 0 damage from the fall. You determine the direction of the glide."}]},{"type":"section","name":"Hadozee Dodge","entries":[{"type":"text","content":"The magic that runs in your veins heightens your natural defenses. When you take damage, you can use your reaction to roll a <span class=\\"text-green-400 font-mono\\">d6</span>. Add your proficiency bonus to the number rolled, and reduce the damage you take by an amount equal to that total (minimum of 0 damage)."},{"type":"text","content":"You can use this trait a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":[],"page":13},{"name":"Half-Elf","source":"PHB","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2,"choose":{"from":["str","dex","con","int","wis"],"count":2}}],"skillProficiencies":[{"any":2}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Half-elves mature at the same rate humans do and reach adulthood around the age of 20. They live much longer than humans, however, often exceeding 180 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Half-elves are about the same size as humans, ranging from 5 to 6 feet tall. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your elf blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i>, and magic can't put you to sleep."}]},{"type":"section","name":"Skill Versatility","entries":[{"type":"text","content":"You gain proficiency in two skills of your choice."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Elvish, and one extra language of your choice."}]}],"subraces":[],"traits":["Uncommon Race"],"languages":[{"common":true,"elvish":true,"anyStandard":1}],"page":38},{"name":"Half-Orc","source":"PHB","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"intimidation":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Half-orcs mature a little faster than humans, reaching adulthood around age 14. They age noticeably faster and rarely live longer than 75 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Half-orcs are somewhat larger and bulkier than humans, and they range from 5 to well over 6 feet tall. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your orc blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Menacing","entries":[{"type":"text","content":"You gain proficiency in the <i>Intimidation</i> skill."}]},{"type":"section","name":"Relentless Endurance","entries":[{"type":"text","content":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."}]},{"type":"section","name":"Savage Attacks","entries":[{"type":"text","content":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Orc. Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script."}]}],"subraces":[],"traits":["Uncommon Race"],"languages":[{"common":true,"orc":true}],"page":40},{"name":"Halfling","source":"PHB","edition":"classic","size":["S"],"speed":25,"ability":[{"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"A halfling reaches adulthood at the age of 20 and generally lives into the middle of his or her second century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Halflings average about 3 feet tall and weigh about 40 pounds. Your size is Small."}]},{"type":"section","name":"Lucky","entries":[{"type":"text","content":"When you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll."}]},{"type":"section","name":"Brave","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">frightened</i>."}]},{"type":"section","name":"Halfling Nimbleness","entries":[{"type":"text","content":"You can move through the space of any creature that is of a size larger than yours."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Halfling. The Halfling language isn't secret, but halflings are loath to share it with others. They write very little, so they don't have a rich body of literature. Their oral tradition, however, is very strong. Almost all halflings speak Common to converse with the people in whose lands they dwell or through which they are traveling."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"halfling":true}],"page":26},{"name":"Halfling","source":"XPHB","edition":"one","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Brave","entries":[{"type":"text","content":"You have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Frightened</i> condition."}]},{"type":"section","name":"Halfling Nimbleness","entries":[{"type":"text","content":"You can move through the space of any creature that is a size larger than you, but you can't stop in the same space."}]},{"type":"section","name":"Luck","entries":[{"type":"text","content":"When you roll a 1 on the <span class=\\"text-green-400 font-mono\\">d20</span> of a <i>D20 Test</i>, you can reroll the die, and you must use the new roll."}]},{"type":"section","name":"Naturally Stealthy","entries":[{"type":"text","content":"You can take the <b>Hide</b> action even when you are obscured only by a creature that is at least one size larger than you."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"halfling":true}],"page":193},{"name":"Harengon","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Hare-Trigger","entries":[{"type":"text","content":"You can add your proficiency bonus to your initiative rolls."}]},{"type":"section","name":"Leporine Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Lucky Footwork","entries":[{"type":"text","content":"When you fail a Dexterity saving throw, you can use your reaction to roll a <span class=\\"text-green-400 font-mono\\">d4</span> and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're <i class=\\"text-dnd-gold\\">prone</i> or your speed is 0."}]},{"type":"section","name":"Rabbit Hop","entries":[{"type":"text","content":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":[],"page":22},{"name":"Harengon","source":"WBtW","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Hare-Trigger","entries":[{"type":"text","content":"You can add your proficiency bonus to your initiative rolls."}]},{"type":"section","name":"Leporine Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Lucky Footwork","entries":[{"type":"text","content":"When you fail a Dexterity saving throw, you can use your reaction to roll a <span class=\\"text-green-400 font-mono\\">d4</span> and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're <i class=\\"text-dnd-gold\\">prone</i> or your speed is 0."}]},{"type":"section","name":"Rabbit Hop","entries":[{"type":"text","content":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":[],"page":13},{"name":"Hexblood","source":"RHW","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Eerie Token","entries":[{"type":"text","content":"As a <i>Bonus Action</i>, you can create a magical token by harmlessly removing a lock of hair, detaching a nail, or using some other method. While the token exists, you gain the following benefits:"},{"type":"list","items":[{"type":"item","name":"Distant Message","entry":"As a <b>Magic</b> action, you can send a telepathic message of 25 words or fewer to a creature holding or carrying the token, as long as you are within 10 miles of it."},{"type":"item","name":"Remote Viewing","entry":"If you are within 10 miles of the token, you can take a <b>Magic</b> action to extend your senses through the token for 1 minute, until you have the Incapacitated condition, or until you end this state (no action required). During this state, you can see and hear from the token as if you were located where it is. When this state ends, the token is harmlessly destroyed.\\nUnless the token is destroyed early, it lasts until you finish a <i>Long Rest</i>. Once you create a token using this feature, you can't do so again until you finish a <i>Long Rest</i>."},{"type":"item","name":"Hex Magic","entry":"You always have the <a href=\\"/spells?search=Disguise Self\\" class=\\"text-dnd-gold hover:underline\\">Disguise Self</a> and <a href=\\"/spells?search=Hex\\" class=\\"text-dnd-gold hover:underline\\">Hex</a> spells prepared. You can cast each spell once without a spell slot, and you regain the ability to cast it in that way when you finish a <i>Long Rest</i>. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select this species)."}]}]}],"subraces":[],"traits":[],"page":29},{"name":"Hexblood","source":"VRGR","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"any":2}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you gain this lineage."}]},{"type":"section","name":"Ancestral Legacy","entries":[{"type":"text","content":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it."},{"type":"text","content":"If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."}]},{"type":"section","name":"Eerie Token","entries":[{"type":"text","content":"As a bonus action, you can harmlessly remove a lock of your hair, one of your nails, or one of your teeth. This token is imbued with magic until you finish a long rest. While the token is imbued in this way, you can take these actions:"},{"type":"list","items":[{"type":"item","name":"Telepathic Message","entry":"As an action, you can send a telepathic message to the creature holding or carrying the token, as long as you are within 10 miles of it. The message can contain up to twenty-five words."},{"type":"item","name":"Remote Viewing","entry":"If you are within 10 miles of the token, you can enter a trance as an action. The trance lasts for 1 minute, but it ends early if you dismiss it (no action required) or are <i class=\\"text-dnd-gold\\">incapacitated</i>. During this trance, you can see and hear from the token as if you were located where it is. While you are using your senses at the token's location, you are <i class=\\"text-dnd-gold\\">blinded</i> and <i class=\\"text-dnd-gold\\">deafened</i> in regard to your own surroundings. When the trance ends, the token is harmlessly destroyed."}]},{"type":"text","content":"Once you create a token using this feature, you can't do so again until you finish a long rest, at which point your missing part regrows."}]},{"type":"section","name":"Hex Magic","entries":[{"type":"text","content":"You can cast the <a href=\\"/spells?search=disguise self\\" class=\\"text-dnd-gold hover:underline\\">disguise self</a> and <a href=\\"/spells?search=hex\\" class=\\"text-dnd-gold hover:underline\\">hex</a> spells with this trait. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose the ability when you gain this lineage)."},{"type":"text","content":"{\\"type\\":\\"inset\\",\\"name\\":\\"Becoming a Hag\\",\\"entries\\":[\\"Hags can undertake a ritual to irreversibly transform a hexblood they created into a new hag, either one of their own kind or that embodies the hexblood's nature. This requires that both the hag and hexblood be in the same place and consent to the lengthy ritual—circumstances most hexbloods shun but might come to accept over the course of centuries. Once a hexblood undergoes this irreversible ritual, they emerge as a hag NPC no longer under the control of the hexblood's player, unless the DM rules otherwise.\\"]}"}]}],"subraces":[],"traits":[],"page":18},{"name":"Hobgoblin","source":"DMG","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Martial Advantage","entries":[{"type":"text","content":"Once per turn, you can deal an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> damage to a creature you hit with a weapon attack if that creature is within 5 ft. of an ally of yours that isn't <i class=\\"text-dnd-gold\\">incapacitated</i>."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"common":true,"goblin":true}],"page":282},{"name":"Hobgoblin","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2,"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Hobgoblins mature at the same rate as humans and have lifespans similar in length to theirs."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Hobgoblins are between 5 and 6 feet tall and weigh between 150 and 200 pounds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Martial Training","entries":[{"type":"text","content":"You are proficient with two <i>martial weapons</i> of your choice and with light armor."}]},{"type":"section","name":"Saving Face","entries":[{"type":"text","content":"Hobgoblins are careful not to show weakness in front of their allies, for fear of losing status. If you miss with an attack roll or fail an ability check or a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race"],"languages":[{"common":true,"goblin":true}],"page":26},{"name":"Hobgoblin","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Fey Gift","entries":[{"type":"text","content":"You can use this trait to take the <b>Help</b> action as a bonus action, and you can do so a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest."},{"type":"text","content":"Starting at 3rd level, choose one of the options below each time you take the <b>Help</b> action with this trait:"},{"type":"list","items":[{"type":"item","name":"Hospitality","entry":"You and the creature you help each gain a number of temporary hit points equal to <span class=\\"text-green-400 font-mono\\">1d6</span> plus your proficiency bonus."},{"type":"item","name":"Passage","entry":"You and the creature you help each increase your walking speeds by 10 feet until the start of your next turn."},{"type":"item","name":"Spite","entry":"Until the start of your next turn, the first time the creature you help hits a target with an attack roll, that target has disadvantage on the next attack roll it makes within the next minute."}]}]},{"type":"section","name":"Fortune from the Many","entries":[{"type":"text","content":"If you miss with an attack roll or fail an ability check or a saving throw, you can draw on your bonds of reciprocity to gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +3). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"goblin":true}],"page":23},{"name":"Hobgoblin","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2,"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Hobgoblins mature at the same rate as humans and have lifespans similar in length to theirs."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Hobgoblins are between 5 and 6 feet tall and weigh between 150 and 200 pounds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Martial Training","entries":[{"type":"text","content":"You are proficient with two <i>martial weapons</i> of your choice and with light armor."}]},{"type":"section","name":"Saving Face","entries":[{"type":"text","content":"Hobgoblins are careful not to show weakness in front of their allies, for fear of losing status. If you miss with an attack roll or fail an ability check or a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Goblin."}]}],"subraces":[],"traits":["Monstrous Race"],"languages":[{"common":true,"goblin":true}],"page":119},{"name":"Human","source":"PHB","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Humans reach adulthood in their late teens and live less than a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: Orc curses, Elvish musical expressions, Dwarvish military phrases, and so on."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":29},{"name":"Human","source":"XPHB","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"any":1}],"entries":[{"type":"section","name":"Resourceful","entries":[{"type":"text","content":"You gain <i>Heroic Inspiration</i> whenever you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Skillful","entries":[{"type":"text","content":"You gain proficiency in one skill of your choice."}]},{"type":"section","name":"Versatile","entries":[{"type":"text","content":"You gain an <i>Origin feat</i> of your choice."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":194},{"name":"Human (Innistrad)","source":"PSI","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Humans reach adulthood in their late teens and live less than a century."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Humans tend toward no particular alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one extra language of your choice."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":8},{"name":"Human (Ixalan)","source":"PSX","edition":"classic","size":["M"],"speed":30,"ability":[{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Humans reach adulthood in their late teens and live less than a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: Orc curses, Elvish musical expressions, Dwarvish military phrases, and so on."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1},{"common":true,"other":true,"anyStandard":1}],"page":11},{"name":"Human (Kaladesh)","source":"PSK","edition":"classic","size":["M"],"speed":30,"ability":[{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Humans reach adulthood in their late teens and live less than a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: Orc curses, Elvish musical expressions, Dwarvish military phrases, and so on."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":22},{"name":"Human (Zendikar)","source":"PSZ","edition":"classic","size":["M"],"speed":30,"ability":[{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Humans reach adulthood in their late teens and live less than a century."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: vampire curses, Elvish musical expressions, merfolk scholarly jargon, and so on."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"anyStandard":1}],"page":9},{"name":"Kalashtar","source":"EFA","edition":"one","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Dual Mind","entries":[{"type":"text","content":"You have <i>Advantage</i> on Wisdom and Charisma saving throws."}]},{"type":"section","name":"Mental Discipline","entries":[{"type":"text","content":"You have <i>Resistance</i> to Psychic damage."}]},{"type":"section","name":"Mind Link","entries":[{"type":"text","content":"You have telepathy with a range in feet equal to 10 times your level. When you're using this trait to speak telepathically to a creature, you can take a <b>Magic</b> action to give that creature the ability to speak telepathically with you for 1 hour or until you take another <b>Magic</b> action to end this effect."}]},{"type":"section","name":"Severed from Dreams","entries":[{"type":"text","content":"You can't be the target of the <a href=\\"/spells?search=Dream\\" class=\\"text-dnd-gold hover:underline\\">Dream</a> spell. In addition, when you finish a <i>Long Rest</i>, you gain proficiency in one skill of your choice. This proficiency lasts until you finish another <i>Long Rest</i>."}]}],"subraces":[],"traits":["Skill Proficiency"],"languages":[{"common":true,"other":true,"anyStandard":1}],"page":35},{"name":"Kalashtar","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"wis":2,"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Kalashtar mature and age at the same rate as humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"The noble spirit tied to a kalashtar drives it toward lawful and good behavior. Most kalashtar combine strong self-discipline with compassion for all beings, but some kalashtar resist the virtuous influence of their spirit."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Dual Mind","entries":[{"type":"text","content":"You have advantage on all Wisdom saving throws."}]},{"type":"section","name":"Mental Discipline","entries":[{"type":"text","content":"You have resistance to psychic damage."}]},{"type":"section","name":"Mind Link","entries":[{"type":"text","content":"You can speak telepathically to any creature you can see, provided the creature is within a number of feet of you equal to 10 times your level. You don't need to share a language with the creature for it to understand your telepathic utterances, but the creature must be able to understand at least one language."},{"type":"text","content":"When you're using this trait to speak telepathically to a creature, you can use your action to give that creature the ability to speak telepathically with you for 1 hour or until you end this effect as an action. To use this ability, the creature must be able to see you and must be within this trait's range. You can give this ability to only one creature at a time; giving it to a creature takes it away from another creature who has it."}]},{"type":"section","name":"Severed from Dreams","entries":[{"type":"text","content":"Kalashtar sleep, but they don't connect to the plane of dreams as other creatures do. Instead, their minds draw from the memories of their otherworldly spirit while they sleep. As such, you are immune to spells and other magical effects that require you to dream, like <a href=\\"/spells?search=dream\\" class=\\"text-dnd-gold hover:underline\\">dream</a>, but not to spells and other magical effects that put you to sleep, like <a href=\\"/spells?search=sleep\\" class=\\"text-dnd-gold hover:underline\\">sleep</a>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Quori, and one other language of your choice."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true,"anyStandard":1}],"page":29},{"name":"Kender","source":"DSotDQ","edition":"classic","size":["S"],"speed":30,"skillProficiencies":[{"choose":{"from":["insight","investigation","sleight of hand","stealth","survival"]}}],"entries":[{"type":"section","name":"Fearless","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">frightened</i> condition on yourself. When you fail a saving throw to avoid or end the <i class=\\"text-dnd-gold\\">frightened</i> condition on yourself, you can choose to succeed instead. Once you succeed on a saving throw in this way, you can't do so again until you finish a long rest."}]},{"type":"section","name":"Kender Curiosity","entries":[{"type":"text","content":"Thanks to the mystical origin of your people, you gain proficiency with one of the following skills of your choice: <i>Insight</i>, <i>Investigation</i>, <i>Sleight of Hand</i>, <i>Stealth</i>, or <i>Survival</i>."}]},{"type":"section","name":"Taunt","entries":[{"type":"text","content":"You have an extraordinary ability to fluster creatures. As a bonus action, you can unleash a string of provoking words at a creature within 60 feet of yourself that can hear and understand you. The target must succeed on a Wisdom saving throw, or it has disadvantage on attack rolls against targets other than you until the start of your next turn. The DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race)."},{"type":"text","content":"You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":[],"page":27},{"name":"Kenku","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Ambusher","entries":[{"type":"text","content":"In the first round of a combat, you have advantage on attack rolls against any creature who is <i>surprised</i>."}]},{"type":"section","name":"Mimicry","entries":[{"type":"text","content":"You can mimic any sounds you have heard, including voices. A creature that hears the sounds can tell they are imitations with a successful DC 14 Wisdom (<i>Insight</i>) check."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can read and write Common and Auran, but you can only speak using your Mimicry trait."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"common":true,"auran":true}],"page":282},{"name":"Kenku","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"any":2}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Expert Duplication","entries":[{"type":"text","content":"When you copy writing or craftwork produced by yourself or someone else, you have advantage on any ability checks you make to produce an exact duplicate."}]},{"type":"section","name":"Kenku Recall","entries":[{"type":"text","content":"Thanks to your supernaturally good memory, you have proficiency in two skills of your choice."},{"type":"text","content":"Moreover, when you make an ability check using any skill in which you have proficiency, you can give yourself advantage on the check before rolling the <span class=\\"text-green-400 font-mono\\">d20</span>. You can give yourself advantage in this way a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Mimicry","entries":[{"type":"text","content":"You can accurately mimic sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations only with a successful Wisdom (<i>Insight</i>) check against a DC of 8 + your proficiency bonus + your Charisma modifier."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"auran":true}],"page":24},{"name":"Kenku","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"dex":2,"wis":1}],"skillProficiencies":[{"choose":{"from":["acrobatics","deception","sleight of hand","stealth"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Kenku have shorter lifespans than humans. They reach maturity at about 12 years old and can live to 60."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Kenku are around 5 feet tall and weigh between 90 and 120 pounds. Your size is Medium."}]},{"type":"section","name":"Expert Forgery","entries":[{"type":"text","content":"You can duplicate other creatures' handwriting and craftwork. You have advantage on all checks made to produce forgeries or duplicates of existing objects."}]},{"type":"section","name":"Kenku Training","entries":[{"type":"text","content":"You are proficient in your choice of two of the following skills: <i>Acrobatics</i>, <i>Deception</i>, <i>Stealth</i>, and <i>Sleight of Hand</i>."}]},{"type":"section","name":"Mimicry","entries":[{"type":"text","content":"You can mimic sounds you have heard, including voices. A creature that hears the sounds can tell they are imitations with a successful Wisdom (<i>Insight</i>) check opposed by your Charisma (<i>Deception</i>) check."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can read and write Common and Auran, but you can only speak using your Mimicry trait."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"auran":true}],"page":109},{"name":"Khenra","source":"PSA","edition":"classic","size":["M"],"speed":35,"ability":[{"dex":2,"str":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Khenra mature quickly, reaching adulthood in their early teens. Khenra initiates are usually the youngest in a crop, completing the trials by their late teens. Even without a violent death, they rarely live past 60."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most khenra lean toward chaotic alignments. They have no particular inclination toward good or evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Khenra have similar builds to humans. Your size is Medium."}]},{"type":"section","name":"Khenra Weapon Training","entries":[{"type":"text","content":"You have proficiency with the khopesh (<b>longsword</b>), <b>spear</b>, and <b>javelin</b>."}]},{"type":"section","name":"Khenra Twins","entries":[{"type":"text","content":"If your twin is alive and you can see your twin, whenever you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll. If your twin is dead (or if you were born without a twin), you can't be <i class=\\"text-dnd-gold\\">frightened</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Khenra."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":17},{"name":"Khoravar","source":"EFA","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Charmed</i> condition."}]},{"type":"section","name":"Fey Gift","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=Friends\\" class=\\"text-dnd-gold hover:underline\\">Friends</a> cantrip. Whenever you finish a <i>Long Rest</i>, you can replace that cantrip with a different cantrip from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for it (choose the ability when you select this species)."}]},{"type":"section","name":"Lethargy Resilience","entries":[{"type":"text","content":"When you fail a saving throw to avoid or end the <i class=\\"text-dnd-gold\\">Unconscious</i> condition, you can succeed instead. Once you use this trait, you can't do so again until you finish <span class=\\"text-green-400 font-mono\\">1d4</span> <i>Long Rest</i>."}]},{"type":"section","name":"Skill Versatility","entries":[{"type":"text","content":"You gain proficiency in one skill or with one tool of your choice. Whenever you finish a <i>Long Rest</i>, you can replace it with another skill or tool proficiency."}]}],"subraces":[],"traits":["Skill Proficiency","Tool Proficiency"],"page":36},{"name":"Kithkin","source":"LFL","edition":"one","size":["S"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Brave","entries":[{"type":"text","content":"You have <i>Advantage</i> on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">Frightened</i> condition."}]},{"type":"section","name":"Halfling Nimbleness","entries":[{"type":"text","content":"You can move through the space of any creature that is a size larger than you, but you can't stop in the same space."}]},{"type":"section","name":"Luck","entries":[{"type":"text","content":"When you roll a 1 on the <span class=\\"text-green-400 font-mono\\">d20</span> of a <i>D20 Test</i>, you can reroll the die, and you must use the new roll."}]},{"type":"section","name":"Naturally Stealthy","entries":[{"type":"text","content":"You can take the <b>Hide</b> action even when you are obscured only by a creature that is at least one size larger than you."}]},{"type":"section","name":"Kithkin Lineage","entries":[{"type":"text","content":"As a native of either Lorwyn and Shadowmoor, you may gain additional traits."},{"type":"list","items":[{"type":"item","name":"Lorwyn","entry":"You do not gain any additional traits."},{"type":"item","name":"Shadowmoor","entry":"You have <i>Darkvision</i> with a range of 120 feet."}]}]}],"subraces":[],"traits":[],"page":193},{"name":"Kobold","source":"DMG","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2,"str":-4}],"skillProficiencies":null,"entries":[{"type":"section","name":"Pack Tactics","entries":[{"type":"text","content":"You have advantage on an attack roll against a creature if at least one of your allies is within 5 feet of the creature and the ally isn't <i class=\\"text-dnd-gold\\">incapacitated</i>."}]},{"type":"section","name":"Sunlight Sensitivity","entries":[{"type":"text","content":"You have disadvantage on attack rolls and on Wisdom (<i>Perception</i>) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Draconic."}]}],"subraces":[],"traits":["NPC Race","Sunlight Sensitivity"],"languages":[{"common":true,"draconic":true}],"page":282},{"name":"Kobold","source":"MPMM","edition":"classic","size":["S"],"speed":30,"skillProficiencies":[{"choose":{"from":["arcana","investigation","medicine","sleight of hand","survival"]}}],"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Draconic Cry","entries":[{"type":"text","content":"As a bonus action, you let out a cry at your enemies within 10 feet of you. Until the start of your next turn, you and your allies have advantage on attack rolls against any of those enemies who could hear you. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Kobold Legacy","entries":[{"type":"text","content":"Kobold's connections to dragons can manifest in unpredictable ways in an individual kobold. Choose one of the following legacy options for your kobold."},{"type":"list","items":[{"type":"item","name":"Craftiness","entry":"You have proficiency in one of the following skills of your choice: <i>Arcana</i>, <i>Investigation</i>, <i>Medicine</i>, <i>Sleight of Hand</i>, or <i>Survival</i>."},{"type":"item","name":"Defiance","entry":"You have advantage on saving throws to avoid or end the <i class=\\"text-dnd-gold\\">frightened</i> condition on yourself."},{"type":"item","name":"Draconic Sorcery","entry":"You know one <i>cantrip of your choice from the sorcerer spell list</i>. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race)."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true,"draconic":true}],"page":25},{"name":"Kobold","source":"VGM","edition":"classic","size":["S"],"speed":30,"ability":[{"dex":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Kobolds reach adulthood at age 6 and can live up to 120 years but rarely do so."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Kobolds are between 2 and 3 feet tall and weigh between 25 and 35 pounds. Your size is Small."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Grovel, Cower, and Beg","entries":[{"type":"text","content":"As an action on your turn, you can cower pathetically to distract nearby foes. Until the end of your next turn, your allies gain advantage on attack rolls against enemies within 10 feet of you that you can see. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Pack Tactics","entries":[{"type":"text","content":"You have advantage on an attack roll against a creature if at least one of your allies is within 5 feet of the creature and the ally isn't <i class=\\"text-dnd-gold\\">incapacitated</i>."}]},{"type":"section","name":"Sunlight Sensitivity","entries":[{"type":"text","content":"You have disadvantage on attack rolls and on Wisdom (<i>Perception</i>) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Draconic."}]}],"subraces":[],"traits":["Monstrous Race","Sunlight Sensitivity"],"languages":[{"common":true,"draconic":true}],"page":119},{"name":"Kor","source":"PSZ","edition":"classic","size":["M"],"speed":{"walk":30,"climb":30},"ability":[{"dex":2,"wis":1}],"skillProficiencies":[{"athletics":true,"acrobatics":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Kor mature at the same rate as humans and live about as long."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most kor are lawful good, with a strong dedication to community and the traditions of their ancestors."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Kor average nearly 6 feet tall, but are much lighter and more slender than humans. Your size is Medium."}]},{"type":"section","name":"Brave","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">frightened</i>."}]},{"type":"section","name":"Climbing","entries":[{"type":"text","content":"You also have a climbing speed of 30 feet as long as you are not encumbered or wearing heavy armor."}]},{"type":"section","name":"Kor Climbing","entries":[{"type":"text","content":"You have proficiency in the <i>Athletics</i> and <i>Acrobatics</i> skills."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, and communicate in the silent speech of the Kor."}]},{"type":"section","name":"Lucky","entries":[{"type":"text","content":"When you roll a 1 on the <span class=\\"text-green-400 font-mono\\">d20</span> for an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":10},{"name":"Kuo-Toa","source":"DMG","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"skillProficiencies":null,"entries":[{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Otherworldly Perception","entries":[{"type":"text","content":"You can sense the presence of any creature within 30 feet of you that is <i class=\\"text-dnd-gold\\">invisible</i> or on the Ethereal Plane. You can pinpoint such a creature that is moving."}]},{"type":"section","name":"Slippery","entries":[{"type":"text","content":"You have advantage on ability checks and saving throws made to escape a grapple."}]},{"type":"section","name":"Sunlight Sensitivity","entries":[{"type":"text","content":"While in sunlight, you have disadvantage on attack rolls, as well as on Wisdom (<i>Perception</i>) checks that rely on sight."}]},{"type":"section","name":"Superior Darkvision","entries":[{"type":"text","content":"You have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Undercommon."}]}],"subraces":[],"traits":["Amphibious","NPC Race","Sunlight Sensitivity"],"languages":[{"undercommon":true}],"page":282},{"name":"Leonin","source":"MOT","edition":"classic","size":["M"],"speed":35,"ability":[{"str":1,"con":2}],"skillProficiencies":[{"choose":{"from":["athletics","intimidation","perception","survival"]}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Leonin mature and age at about the same rate as humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Leonin tend toward good alignments. Leonin who are focused on the pride lean toward lawful good."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Leonin are typically over 6 feet tall, with some standing over 7 feet. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Claws","entries":[{"type":"text","content":"Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you can deal slashing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Hunter's Instincts","entries":[{"type":"text","content":"You have proficiency in one of the following skills of your choice: <i>Athletics</i>, <i>Intimidation</i>, <i>Perception</i>, or <i>Survival</i>."}]},{"type":"section","name":"Daunting Roar","entries":[{"type":"text","content":"As a bonus action, you can let out an especially menacing roar. Creatures of your choice within 10 feet of you that can hear you must succeed on a Wisdom saving throw or become <i class=\\"text-dnd-gold\\">frightened</i> of you until the end of your next turn. The DC of the save equals 8 + your proficiency bonus + your Constitution modifier. Once you use this trait, you can't use it again until you finish a short or long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Leonin."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":20},{"name":"Lizardfolk","source":"DMG","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"str":2,"int":-2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for up to 15 minutes at a time."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"Your scales function as natural armor, granting you a +3 bonus to Armor Class."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Draconic."}]}],"subraces":[],"traits":["Natural Armor","NPC Race"],"languages":[{"draconic":true}],"page":282},{"name":"Lizardfolk","source":"MPMM","edition":"classic","size":["M"],"speed":{"walk":30,"swim":true},"skillProficiencies":[{"choose":{"from":["animal handling","medicine","nature","perception","stealth","survival"],"count":2}}],"entries":[{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."}]},{"type":"section","name":"Bite","entries":[{"type":"text","content":"You have a fanged maw that you can use to make unarmed strikes. When you hit with it, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for up to 15 minutes at a time."}]},{"type":"section","name":"Hungry Jaws","entries":[{"type":"text","content":"You can throw yourself into a feeding frenzy. As a bonus action, you can make a special attack with your Bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"You have tough, scaly skin. When you aren't wearing armor, your base AC is 13 + Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."}]},{"type":"section","name":"Nature's Intuition","entries":[{"type":"text","content":"Thanks to your mystical connection to nature, you gain proficiency with two of the following skills of your choice: <i>Animal Handling</i>, <i>Medicine</i>, <i>Nature</i>, <i>Perception</i>, <i>Stealth</i>, or <i>Survival</i>."}]}],"subraces":[],"traits":["Natural Armor","Natural Weapon"],"languages":[{"draconic":true}],"page":26},{"name":"Lizardfolk","source":"VGM","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"con":2,"wis":1}],"skillProficiencies":[{"choose":{"from":["animal handling","nature","perception","stealth","survival"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Lizardfolk reach maturity around age 14 and rarely live longer than 60 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Lizardfolk are a little bulkier and taller than humans, and their colorful frills make them appear even larger. Your size is Medium."}]},{"type":"section","name":"Swim Speed","entries":[{"type":"text","content":"You have a swimming speed of 30 feet."}]},{"type":"section","name":"Bite","entries":[{"type":"text","content":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Cunning Artisan","entries":[{"type":"text","content":"As part of a short rest, you can harvest bone and hide from a slain beast, construct, dragon, monstrosity, or plant creature of size small or larger to create one of the following items: a <b>shield</b>, a <b>club</b>, a <b>javelin</b>, or <span class=\\"text-green-400 font-mono\\">1d4</span> <b>dart</b> or <b>blowgun needle</b>. To use this trait, you need a blade, such as a <b>dagger</b>, or appropriate <i>artisan's tools</i>, such as <b>leatherworker's tools</b>."}]},{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for up to 15 minutes at a time."}]},{"type":"section","name":"Hunter's Lore","entries":[{"type":"text","content":"You gain proficiency with two of the following skills of your choice: <i>Animal Handling</i>, <i>Nature</i>, <i>Perception</i>, <i>Stealth</i>, and <i>Survival</i>."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"You have tough, scaly skin. When you aren't wearing armor, your AC is 13 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."}]},{"type":"section","name":"Hungry Jaws","entries":[{"type":"text","content":"In battle, you can throw yourself into a vicious feeding frenzy. As a bonus action, you can make a special attack with your bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your Constitution modifier (minimum of 1), and you can't use this trait again until you finish a short or long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Draconic."}]}],"subraces":[],"traits":["Natural Armor","Natural Weapon"],"languages":[{"common":true,"draconic":true}],"page":111},{"name":"Locathah","source":"LR","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"str":2,"dex":1}],"skillProficiencies":[{"athletics":true,"perception":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Locathah mature to adulthood by the age of 10 but have been known to live up to 80 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most locathah are true neutral or have some aspect of neutrality in their alignment. They tend toward good, coming from a culture where compassion for the downtrodden is a commonality."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"You have tough, scaly skin. When you aren't wearing armor, your AC is 12 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."}]},{"type":"section","name":"Observant & Athletic","entries":[{"type":"text","content":"You have proficiency in the <i>Athletics</i> and <i>Perception</i> skills."}]},{"type":"section","name":"Leviathan Will","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i>, <i class=\\"text-dnd-gold\\">frightened</i>, <i class=\\"text-dnd-gold\\">paralyzed</i>, <i class=\\"text-dnd-gold\\">poisoned</i>, <i class=\\"text-dnd-gold\\">stunned</i>, or put to sleep."}]},{"type":"section","name":"Limited Amphibiousness","entries":[{"type":"text","content":"You can breathe air and water, but you need to be submerged at least once every 4 hours to avoid suffocating."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Locathah stand between 5 and 6 feet tall and average about 150 pounds. Your size is Medium."}]},{"type":"section","name":"Language","entries":[{"type":"text","content":"You can speak, read, and write Aquan and Common."}]}],"subraces":[],"traits":["Amphibious","Natural Armor"],"languages":[{"aquan":true,"common":true}],"page":24},{"name":"Lorwyn Changeling","source":"LFL","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["deception","performance"]}}],"entries":[{"type":"section","name":"Shape Self","entries":[{"type":"text","content":"As an action, you can reshape your body to a two-legged Humanoid shape or to a four-legged Beast shape. While you have a Humanoid shape, you can wear clothing and armor made for a Humanoid of your size."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 120 feet."}]},{"type":"section","name":"Delightful Imitator","entries":[{"type":"text","content":"You have proficiency in the <i>Deception</i> or <i>Performance</i> skill."}]},{"type":"section","name":"Unpredictable Movement","entries":[{"type":"text","content":"When you roll <i>Initiative</i>, you can immediately move up to half your <i>Speed</i>, provided you don't have <i>Disadvantage</i> on the <i>Initiative</i> roll."}]}],"subraces":[],"traits":[]},{"name":"Loxodon","source":"GGR","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2,"wis":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Loxodons physically mature at the same rate as humans, but they live about 450 years. They highly value the weight of wisdom and experience and are considered young until they reach the age of 60."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most loxodons are lawful, believing in the value of a peaceful, ordered life. They also tend toward good."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Loxodons stand between 7 and 8 feet tall. Their massive bodies weigh between 300 and 400 pounds. Your size is Medium."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Loxodon Serenity","entries":[{"type":"text","content":"You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">charmed</i> or <i class=\\"text-dnd-gold\\">frightened</i>."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"You have thick, leathery skin. When you aren't wearing armor, your AC is 12 + your Constitution modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."},{"type":"text","content":"{\\"type\\":\\"inset\\",\\"name\\":\\"Tip: AC Calculations Don't Stack\\",\\"entries\\":[\\"When the game gives you more than one way to calculate your Armor Class, you can use only one of them. You choose the one to use. For example, if you have the loxodon's Natural Armor trait and the monk's Unarmored Defense feature, you don't mix them together. Instead, you choose which one determines your AC.\\"]}"}]},{"type":"section","name":"Trunk","entries":[{"type":"text","content":"You can grasp things with your trunk, and you can use it as a snorkel. It has a reach of 5 feet, and it can lift a number of pounds equal to five times your Strength score. You can use it to do the following simple tasks: lift, drop, hold, push, or pull an object or a creature; open or close a door or a container; grapple someone; or make an unarmed strike. Your DM might allow other simple tasks to be added to that list of options."},{"type":"text","content":"Your trunk can't wield weapons or shields or do anything that requires manual precision, such as using tools or magic items or performing the somatic components of a spell."}]},{"type":"section","name":"Keen Smell","entries":[{"type":"text","content":"Thanks to your sensitive trunk, you have advantage on Wisdom (<i>Perception</i>), Wisdom (<i>Survival</i>), and Intelligence (<i>Investigation</i>) checks that involve smell."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Loxodon."}]}],"subraces":[],"traits":["Natural Armor","Powerful Build"],"languages":[{"common":true,"other":true}],"page":17},{"name":"Lupin","source":"RHW","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["perception","stealth","survival"]}}],"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Feral Pounce","entries":[{"type":"text","content":"Your <i>Unarmed Strike</i> deal Slashing damage instead of Bludgeoning damage. In addition, when you hit a creature with an <i>Unarmed Strike</i> as part of the <b>Attack</b> action on your turn, you can use both the <i>Damage</i> and the Shove options. You can use this benefit only once per turn."}]},{"type":"section","name":"Howl","entries":[{"type":"text","content":"As a <i>Bonus Action</i>, you let out an unearthly howl. Each creature of your choice within 15 feet of you must succeed on a Wisdom saving throw (DC 8 plus your Constitution modifier and <i>Proficiency</i>) or have <i>Disadvantage</i> on attack rolls and saving throws until the start of your next turn."},{"type":"text","content":"You can use this trait a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Werewolf Instincts","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i>, <i>Stealth</i>, or <i>Survival</i> skill."}]}],"subraces":[],"traits":["Natural Weapon"],"page":30},{"name":"Merfolk","source":"DMG","edition":"classic","size":["M"],"speed":{"walk":10,"swim":40},"skillProficiencies":null,"entries":[{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Aquan."}]}],"subraces":[],"traits":["Amphibious","NPC Race"],"languages":[{"common":true,"aquan":true}],"page":282},{"name":"Merfolk","source":"PSZ","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"cha":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Merfolk mature at the same rate humans do and reach adulthood around the age of 20. They live considerably longer than humans, though, often reaching well over 100 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most merfolk are neutral, though merfolk of the Emeria and Cosi creeds have chaotic leanings."}]},{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Merfolk are about the same size and build as humans. Your size is Medium."}]},{"type":"section","name":"Swimming","entries":[{"type":"text","content":"You have a swimming speed of 30 feet."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Merfolk, and one extra language of your choice."}]}],"subraces":[],"traits":["Amphibious"],"languages":[{"common":true,"other":true,"anyStandard":1}],"page":13},{"name":"Minotaur","source":"GGR","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"choose":{"from":["intimidation","persuasion"]}}],"entries":[{"type":"section","name":"","entries":[{"type":"text","content":"These traits are also suitable for minotaurs in other D&D worlds where these people have avoided the demonic influence of Baphomet."}]},{"type":"section","name":"Age","entries":[{"type":"text","content":"Minotaurs enter adulthood at around the age of 17 and can live up to 150 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most minotaurs who join the Boros Legion lean toward lawful alignments, while those associated with the Cult of Rakdos or the Gruul Clans tend toward chaotic alignments."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Minotaurs average over 6 feet in height, and they have stocky builds. Your size is Medium."}]},{"type":"section","name":"Horns","entries":[{"type":"text","content":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Goring Rush","entries":[{"type":"text","content":"Immediately after you use the <b>Dash</b> action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."}]},{"type":"section","name":"Hammering Horns","entries":[{"type":"text","content":"Immediately after you hit a creature with a melee attack as part of the <b>Attack</b> action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be no more than one size larger than you and within 5 feet of you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."}]},{"type":"section","name":"Imposing Presence","entries":[{"type":"text","content":"You have proficiency in one of the following skills of your choice: <i>Intimidation</i> or <i>Persuasion</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Minotaur."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":18},{"name":"Minotaur","source":"MOT","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"choose":{"from":["intimidation","persuasion"]}}],"entries":[{"type":"section","name":"","entries":[{"type":"text","content":"These traits are also suitable for minotaurs in other D&D worlds where these people have avoided the demonic influence of Baphomet."}]},{"type":"section","name":"Age","entries":[{"type":"text","content":"Minotaurs enter adulthood at around the age of 17 and can live up to 150 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most minotaurs who join the Boros Legion lean toward lawful alignments, while those associated with the Cult of Rakdos or the Gruul Clans tend toward chaotic alignments."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Minotaurs average over 6 feet in height, and they have stocky builds. Your size is Medium."}]},{"type":"section","name":"Horns","entries":[{"type":"text","content":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Goring Rush","entries":[{"type":"text","content":"Immediately after you use the <b>Dash</b> action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."}]},{"type":"section","name":"Hammering Horns","entries":[{"type":"text","content":"Immediately after you hit a creature with a melee attack as part of the <b>Attack</b> action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be no more than one size larger than you and within 5 feet of you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."}]},{"type":"section","name":"Imposing Presence","entries":[{"type":"text","content":"You have proficiency in one of the following skills of your choice: <i>Intimidation</i> or <i>Persuasion</i>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Minotaur."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":22},{"name":"Minotaur","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Horns","entries":[{"type":"text","content":"You have horns that you can use to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier piercing damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Goring Rush","entries":[{"type":"text","content":"Immediately after you take the <b>Dash</b> action on your turn and move at least 20 feet, you can make one melee attack with your Horns as a bonus action."}]},{"type":"section","name":"Hammering Horns","entries":[{"type":"text","content":"Immediately after you hit a creature with a melee attack as part of the <b>Attack</b> action on your turn, you can use a bonus action to attempt to push that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you can push it up to 10 feet away from you."}]},{"type":"section","name":"Labyrinthine Recall","entries":[{"type":"text","content":"You always know which direction is north, and you have advantage on any Wisdom (<i>Survival</i>) check you make to navigate or track."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":27},{"name":"Minotaur (Amonkhet)","source":"PSA","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"intimidation":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Minotaurs develop more slowly than humans, reaching full maturity around the age of 20. They typically become acolytes at around 8 or 9 years old, making them among the older members of their crops. Once they reach maturity, though, minotaurs age quickly, rushing headlong through the trials (as they do all aspects of life) to complete them before they pass their peak. A minotaur allowed to die of old age would rarely live beyond 40."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most minotaurs lean toward chaotic alignments, and they have a slight inclination toward evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Minotaurs average over 6 feet in height, and they have strong, stocky builds. Your size is Medium."}]},{"type":"section","name":"Natural Weapon","entries":[{"type":"text","content":"You can use your horns as a natural weapon to make unarmed strikes. If you hit with your horns, you deal bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier."}]},{"type":"section","name":"Menacing","entries":[{"type":"text","content":"You gain proficiency in the <i>Intimidation</i> skill."}]},{"type":"section","name":"Relentless Endurance","entries":[{"type":"text","content":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."}]},{"type":"section","name":"Savage Attacks","entries":[{"type":"text","content":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Minotaur."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":19},{"name":"Naga","source":"PSA","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2,"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Like humans, naga reach adulthood in their late teens. They show no signs of aging beyond that point except for growing larger, so in theory, a naga could live well over a century."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most naga are either neutral or neutral evil in alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Naga stand about 5 feet tall when upright, but the total length of their bodies, head to tail, ranges from 10 to as much as 20 feet. Your size is Medium."}]},{"type":"section","name":"Speed Burst","entries":[{"type":"text","content":"By lowering your body to the ground and propelling yourself with your arms, you can move more quickly for a time. As a bonus action on your turn, if you have both hands free, you can increase your walking speed by 5 feet until the end of your turn."}]},{"type":"section","name":"Natural Weapons","entries":[{"type":"text","content":"Your fanged maw and constricting serpentine body are natural weapons, which you can use to make unarmed strikes."},{"type":"text","content":"If you hit with your bite, you deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, and your target must make a Constitution saving throw (DC 8 + your proficiency bonus + your Constitution modifier). On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">1d4</span> poison damage."},{"type":"text","content":"If you hit with your constrict attack, you deal bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, and the target is <i class=\\"text-dnd-gold\\">grappled</i> (escape DC 8 + your proficiency bonus + your Strength modifier). Until this grapple ends, the target is <i class=\\"text-dnd-gold\\">restrained</i>, and you can't constrict another target."}]},{"type":"section","name":"Poison Immunity","entries":[{"type":"text","content":"You are immune to poison damage and can't be <i class=\\"text-dnd-gold\\">poisoned</i>."}]},{"type":"section","name":"Poison Affinity","entries":[{"type":"text","content":"You gain proficiency with the <b>poisoner's kit</b>."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Naga."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"other":true}],"page":21},{"name":"Orc","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"int":-2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Aggressive","entries":[{"type":"text","content":"As a bonus action, you can move up to your speed toward a hostile creature that you can see."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Orc."}]}],"subraces":[],"traits":["NPC Race"],"languages":[{"common":true,"orc":true}],"page":282},{"name":"Orc","source":"EGW","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"choose":{"from":["animal handling","insight","intimidation","medicine","perception","survival"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Orcs reach adulthood at age 12 and live up to 50 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"The orcs of Eberron are a passionate people, given to powerful emotion and deep faith. They are generally chaotic, but can be any alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Aggressive","entries":[{"type":"text","content":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."}]},{"type":"section","name":"Primal Intuition","entries":[{"type":"text","content":"You have proficiency in two of the following skills of your choice: <i>Animal Handling</i>, <i>Insight</i>, <i>Intimidation</i>, <i>Medicine</i>, <i>Nature</i>, <i>Perception</i>, and <i>Survival</i>."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Orc."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"orc":true}],"page":178},{"name":"Orc","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"choose":{"from":["animal handling","insight","intimidation","medicine","nature","perception","survival"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Orcs reach adulthood at age 12 and live up to 50 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"The orcs of Eberron are a passionate people, given to powerful emotion and deep faith. They are generally chaotic, but can be any alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Aggressive","entries":[{"type":"text","content":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."}]},{"type":"section","name":"Primal Intuition","entries":[{"type":"text","content":"You have proficiency in two of the following skills of your choice: <i>Animal Handling</i>, <i>Insight</i>, <i>Intimidation</i>, <i>Medicine</i>, <i>Nature</i>, <i>Perception</i>, and <i>Survival</i>."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Orc."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"orc":true}],"page":31},{"name":"Orc","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Adrenaline Rush","entries":[{"type":"text","content":"You can take the <b>Dash</b> action as a bonus action. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"text","content":"Whenever you use this trait, you gain a number of temporary hit points equal to your proficiency bonus."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Relentless Endurance","entries":[{"type":"text","content":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. Once you use this trait, you can't do so again until you finish a long rest."}]}],"subraces":[],"traits":["Powerful Build"],"languages":[{"common":true,"orc":true}],"page":28},{"name":"Orc","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"choose":{"from":["animal handling","insight","intimidation","medicine","nature","perception","survival"],"count":2}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Orcs reach adulthood at age 12 and live up to 50 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Orcs are usually over 6 feet tall and weigh between 230 and 280 pounds. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Aggressive","entries":[{"type":"text","content":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."}]},{"type":"section","name":"Primal Intuition","entries":[{"type":"text","content":"You have proficiency in two of the following skills of your choice: <i>Animal Handling</i>, <i>Insight</i>, <i>Intimidation</i>, <i>Medicine</i>, <i>Nature</i>, <i>Perception</i>, and <i>Survival</i>."}]},{"type":"section","name":"Powerful Build","entries":[{"type":"text","content":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Orc."}]}],"subraces":[],"traits":["Monstrous Race","Powerful Build"],"languages":[{"common":true,"orc":true}],"page":120},{"name":"Orc","source":"XPHB","edition":"one","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Adrenaline Rush","entries":[{"type":"text","content":"You can take the <b>Dash</b> action as a <i>Bonus Action</i>. When you do so, you gain a number of <i>Temporary Hit Points</i> equal to your <i>Proficiency</i>."},{"type":"text","content":"You can use this trait a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Short Rest</i> or <i>Long Rest</i>."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 120 feet."}]},{"type":"section","name":"Relentless Endurance","entries":[{"type":"text","content":"When you are reduced to 0 <i>Hit Points</i> but not killed outright, you can drop to 1 <i>Hit Points</i> instead. Once you use this trait, you can't do so again until you finish a <i>Long Rest</i>."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"orc":true}],"page":195},{"name":"Orc (Ixalan)","source":"PSX","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":1}],"skillProficiencies":[{"intimidation":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Orcs mature a little faster than humans, reaching adulthood around age 14. They age noticeably faster and rarely live longer than 75 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most orcs lean toward chaotic alignments, and many serve on pirate ships that encourage an inclination toward evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Orcs average over 6 feet in height, and they have strong, stocky builds. Your size is Medium."}]},{"type":"section","name":"Menacing","entries":[{"type":"text","content":"You gain proficiency in the <i>Intimidation</i> skill."}]},{"type":"section","name":"Relentless Endurance","entries":[{"type":"text","content":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."}]},{"type":"section","name":"Savage Attacks","entries":[{"type":"text","content":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common Trade Pidgin (if it exists in your campaign) and Orc."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"orc":true}],"page":15},{"name":"Owlin","source":"SCC","edition":"classic","size":["S","M"],"speed":{"walk":30,"fly":true},"skillProficiencies":[{"stealth":true}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 120 feet of yourself as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"Thanks to your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]},{"type":"section","name":"Silent Feathers","entries":[{"type":"text","content":"You have proficiency in the <i>Stealth</i> skill."}]}],"subraces":[],"traits":[],"page":29},{"name":"Plasmoid","source":"AAG","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are an Ooze."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Amorphous","entries":[{"type":"text","content":"You can squeeze through a space as narrow as 1 inch wide, provided you are wearing and carrying nothing. You have advantage on ability checks you make to initiate or escape a grapple."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for 1 hour."}]},{"type":"section","name":"Natural Resilience","entries":[{"type":"text","content":"You have resistance to acid and poison damage, and you have advantage on saving throws against being <i class=\\"text-dnd-gold\\">poisoned</i>."}]},{"type":"section","name":"Shape Self","entries":[{"type":"text","content":"As an action, you can reshape your body to give yourself a head, one or two arms, one or two legs, and makeshift hands and feet, or you can revert to a limbless blob. While you have a humanlike shape, you can wear clothing and armor made for a Humanoid of your size."},{"type":"text","content":"As a bonus action, you can extrude a pseudopod that is up to 6 inches wide and 10 feet long or reabsorb it into your body. As part of the same bonus action, you can use this pseudopod to manipulate an object, open or close a door or container, or pick up or set down a Tiny object. The pseudopod contains no sensory organs and can't attack, activate magic items, or lift more than 10 pounds."}]}],"subraces":[],"traits":[],"page":14},{"name":"Reborn","source":"RHW","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"any":1}],"entries":[{"type":"section","name":"Escaped Death","entries":[{"type":"text","content":"You have <i>Advantage</i> on <i>Death Saving Throw</i>."}]},{"type":"section","name":"Everlasting","entries":[{"type":"text","content":"You don't gain <i class=\\"text-dnd-gold\\">Exhaustion</i> levels from dehydration, malnutrition, or suffocation. You don't need to sleep, and magic can't put you to sleep. You can finish a <i>Long Rest</i> in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."}]},{"type":"section","name":"Knowledge from a Past Life","entries":[{"type":"text","content":"You gain proficiency in one skill of your choice."},{"type":"text","content":"In addition, you can temporarily peer into the past to aid you in the present. When you fail an ability check, you can roll <span class=\\"text-green-400 font-mono\\">1d6</span> and add the number rolled to the <span class=\\"text-green-400 font-mono\\">d20</span>, potentially turning the failure into a success. You can do this a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."}]},{"type":"section","name":"Strange Endurance","entries":[{"type":"text","content":"You have <i>Resistance</i> to one of the following damage types of your choice: Cold, Necrotic, or Poison."}]}],"subraces":[],"traits":[],"page":31},{"name":"Reborn","source":"VRGR","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you gain this lineage."}]},{"type":"section","name":"Ancestral Legacy","entries":[{"type":"text","content":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it."},{"type":"text","content":"If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."}]},{"type":"section","name":"Deathless Nature","entries":[{"type":"text","content":"You have escaped death, a fact represented by the following benefits:"},{"type":"list","items":["You have advantage on saving throws against disease and being <i class=\\"text-dnd-gold\\">poisoned</i>, and you have resistance to poison damage.","You have advantage on death saving throws.","You don't need to eat, drink, or breathe.","You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."]}]},{"type":"section","name":"Knowledge from a Past Life","entries":[{"type":"text","content":"You temporarily remember glimpses of the past, perhaps faded memories from ages ago or a previous life. When you make an ability check that uses a skill, you can roll a <span class=\\"text-green-400 font-mono\\">d6</span> immediately after seeing the number on the <span class=\\"text-green-400 font-mono\\">d20</span> and add the number on the <span class=\\"text-green-400 font-mono\\">d6</span> to the check. You can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"subraces":[],"traits":["Improved Resting"],"page":20},{"name":"Rimekin","source":"LFL","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Cold Fire Magic","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=Ray of Frost\\" class=\\"text-dnd-gold hover:underline\\">Ray of Frost</a> cantrip. When you reach character levels 3 and 5, you learn the <a href=\\"/spells?search=Ice Knife\\" class=\\"text-dnd-gold hover:underline\\">Ice Knife</a> spell and the <a href=\\"/spells?search=Flame Blade\\" class=\\"text-dnd-gold hover:underline\\">Flame Blade</a> spell, respectively. You always have those spells prepared. You can cast each once without a spell slot, and you regain the ability to cast these spells in this way when you finish a <i>Long Rest</i>. You can also cast the spells using any spell slots you have of the appropriate level. When you cast <a href=\\"/spells?search=Flame Blade\\" class=\\"text-dnd-gold hover:underline\\">Flame Blade</a> using this trait, the spell deals Cold damage instead of Fire damage."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose the ability when you select this species)."}]},{"type":"section","name":"Cold Resistance","entries":[{"type":"text","content":"You have <i>Resistance</i> to Cold damage."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]}],"subraces":[],"traits":[]},{"name":"Satyr","source":"MOT","edition":"classic","size":["M"],"speed":35,"ability":[{"cha":2,"dex":1}],"skillProficiencies":[{"performance":true,"persuasion":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Satyrs mature and age at about the same rate as humans."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Satyrs delight in living a life free of the mantle of law. They gravitate toward being good, but some have devious streaks and enjoy causing dismay."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Satyrs range from just under 5 feet to about 6 feet in height, with generally slender builds. Your size is Medium."}]},{"type":"section","name":"Fey","entries":[{"type":"text","content":"Your creature type is fey, rather than humanoid."}]},{"type":"section","name":"Ram","entries":[{"type":"text","content":"You can use your head and horns to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier."}]},{"type":"section","name":"Magic Resistance","entries":[{"type":"text","content":"You have advantage on saving throws against spells and other magical effects."}]},{"type":"section","name":"Mirthful Leaps","entries":[{"type":"text","content":"Whenever you make a long or high jump, you can roll a <span class=\\"text-green-400 font-mono\\">d8</span> and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as normal."}]},{"type":"section","name":"Reveler","entries":[{"type":"text","content":"You have proficiency in the <i>Performance</i> and <i>Persuasion</i> skills, and you have proficiency with one <b>musical instrument</b> of your choice."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Sylvan."}]}],"subraces":[],"traits":["Magic Resistance","Natural Weapon"],"languages":[{"common":true,"sylvan":true}],"page":24},{"name":"Satyr","source":"MPMM","edition":"classic","size":["M"],"speed":35,"skillProficiencies":[{"performance":true,"persuasion":true}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Fey."}]},{"type":"section","name":"Ram","entries":[{"type":"text","content":"You can use your head and horns to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Magic Resistance","entries":[{"type":"text","content":"You have advantage on saving throws against spells."}]},{"type":"section","name":"Mirthful Leaps","entries":[{"type":"text","content":"Whenever you make a long jump or a high jump, you can roll a <span class=\\"text-green-400 font-mono\\">d8</span> and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as usual."}]},{"type":"section","name":"Reveler","entries":[{"type":"text","content":"As an embodiment of revelry, you have proficiency in the <i>Performance</i> and <i>Persuasion</i> skills, and you have proficiency with one <b>musical instrument</b> of your choice."}]}],"subraces":[],"traits":["Magic Resistance","Natural Weapon"],"languages":[{"common":true,"sylvan":true}],"page":29},{"name":"Sea Elf","source":"MPMM","edition":"classic","size":["M"],"speed":{"walk":30,"swim":true},"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."}]},{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."}]},{"type":"section","name":"Child of the Sea","entries":[{"type":"text","content":"You can breathe air and water, and you have resistance to cold damage."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Friend of the Sea","entries":[{"type":"text","content":"Aquatic animals have an extraordinary affinity with your people. You can communicate simple ideas to any Beast that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."},{"type":"text","content":"Whenever you finish this trance, you can gain two proficiencies that you don't have, each one with a <i>weapon</i> or a <i>tool</i> of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}]}],"subraces":[],"traits":["Amphibious","Improved Resting","Tool Proficiency","Weapon Proficiency"],"page":30},{"name":"Shadar-Kai","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"perception":true}],"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."}]},{"type":"section","name":"Blessing of the Raven Queen","entries":[{"type":"text","content":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"text","content":"Starting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Fey Ancestry","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">charmed</i> condition on yourself."}]},{"type":"section","name":"Keen Senses","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> skill."}]},{"type":"section","name":"Necrotic Resistance","entries":[{"type":"text","content":"You have resistance to necrotic damage."}]},{"type":"section","name":"Trance","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."},{"type":"text","content":"Whenever you finish this trance, you can gain two proficiencies that you don't have, each one with a <i>weapon</i> or a <i>tool</i> of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}]}],"subraces":[],"traits":["Improved Resting","Tool Proficiency","Weapon Proficiency"],"page":31},{"name":"Shifter","source":"EFA","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["acrobatics","athletics","intimidation","survival"]}}],"entries":[{"type":"section","name":"Bestial Instincts","entries":[{"type":"text","content":"Channeling the beast within, you gain proficiency in one of the following skills of your choice: <i>Acrobatics</i>, <i>Athletics</i>, <i>Intimidation</i>, or <i>Survival</i>."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Shifting","entries":[{"type":"text","content":"As a <i>Bonus Action</i>, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a <i>Bonus Action</i>. When you shift, you gain <i>Temporary Hit Points</i> equal to 2 times your <i>Proficiency</i>. You can shift a number of times equal to your <i>Proficiency</i>, and you regain all expended uses when you finish a <i>Long Rest</i>."},{"type":"text","content":"Whenever you shift, you gain the benefit of one of the following options (choose when you select this species)"},{"type":"list","items":[{"type":"item","name":"Beasthide","entry":"You gain <span class=\\"text-green-400 font-mono\\">1d6</span> additional <i>Temporary Hit Points</i>. While shifted, you have a +1 bonus to your <i>Armor Class</i>."},{"type":"item","name":"Longtooth","entry":"When you shift and as a <i>Bonus Action</i> on your other turns while shifted, you can use your elongated fangs to make an <i>Unarmed Strike</i>. If you hit with this <i>Unarmed Strike</i> and deal damage, you can deal Piercing damage equal to <span class=\\"text-green-400 font-mono\\">1d6</span> plus your Strength modifier, instead of the normal damage of an <i>Unarmed Strike</i>."},{"type":"item","name":"Swiftstride","entry":"While you are shifted, your <i>Speed</i> increases by 10 feet. Additionally, you can move up to 10 feet as a <i>Reaction</i> when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke <b>Opportunity Attack</b>."},{"type":"item","name":"Wildhunt","entry":"While shifted, you have <i>Advantage</i> on Wisdom checks. Additionally, no creature within 30 feet of you can have <i>Advantage</i> on an attack roll against you unless you have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true}],"page":37},{"name":"Shifter","source":"ERLW","edition":"classic","size":["M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Shifters are quick to mature both physically and emotionally, reaching young adulthood at age 10. They rarely live to be more than 70 years old."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Shifters tend toward neutrality, being more focused on survival than concepts of good and evil. A love of personal freedom can drive shifters toward chaotic alignments."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your base walking speed is 30 feet."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Shifting","entries":[{"type":"text","content":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to your level + your Constitution modifier (minimum of 1 temporary hit point). You also gain additional benefits that depend on your shifter subrace, described below."},{"type":"text","content":"Once you shift, you can't do so again until you finish a short or long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common."}]}],"subraces":[],"traits":[],"languages":[{"common":true}],"page":33},{"name":"Shifter","source":"MPMM","edition":"classic","size":["M"],"speed":30,"skillProficiencies":[{"choose":{"from":["acrobatics","athletics","intimidation","survival"]}}],"entries":[{"type":"section","name":"Bestial Instincts","entries":[{"type":"text","content":"Channeling the beast within, you have proficiency in one of the following skills of your choice: <i>Acrobatics</i>, <i>Athletics</i>, <i>Intimidation</i>, or <i>Survival</i>."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Shifting","entries":[{"type":"text","content":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus. You can shift a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"text","content":"Whenever you shift, you gain an additional benefit based on one of the following options (choose when you select this race):"},{"type":"list","items":[{"type":"item","name":"Beasthide","entry":"You gain <span class=\\"text-green-400 font-mono\\">1d6</span> additional temporary hit points. While shifted, you have a +1 bonus to your Armor Class."},{"type":"item","name":"Longtooth","entry":"When you shift and as a bonus action on your other turns while shifted, you can use your elongated fangs to make an unarmed strike. If you hit with your fangs, you can deal piercing damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Swiftstride","entry":"While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke opportunity attacks."},{"type":"item","name":"Wildhunt","entry":"While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you unless you're <i class=\\"text-dnd-gold\\">incapacitated</i>."}]}]}],"subraces":[],"traits":[],"languages":[{"common":true}],"page":32},{"name":"Simic Hybrid","source":"GGR","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"con":2,"choose":{"from":["str","dex","int","wis","cha"],"count":1}}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Hybrids begin their lives as adult humans, elves, or vedalken. They age at a slightly accelerated rate, so their maximum life spans are probably reduced somewhat. The Guardian Project has not been operating long enough to observe the full effect of this phenomenon."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most hybrids share the generally neutral outlook of the Simic Combine. They are more interested in scientific research and the standing of their guild than in moral or ethical questions. Those who leave the Combine, however, often do so because their philosophical outlook and alignment are more in line with a different guild's."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium, within the normal range of your humanoid base race."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and your choice of Elvish or Vedalken."}]},{"type":"section","name":"Animal Enhancement","entries":[{"type":"text","content":"Your body has been altered to incorporate certain animal characteristics. You choose one animal enhancement now and a second enhancement at 5th level."},{"type":"text","content":"At 1st level, choose one of the following options:"},{"type":"list","items":[{"type":"item","name":"Manta Glide","entry":"You have ray-like fins that you can use as wings to slow your fall or allow you to glide. When you fall and aren't <i class=\\"text-dnd-gold\\">incapacitated</i>, you can subtract up to 100 feet from the fall when calculating falling damage, and you can move up to 2 feet horizontally for every 1 foot you descend."},{"type":"item","name":"Nimble Climber","entry":"You have a climbing speed equal to your walking speed."},{"type":"item","name":"Underwater Adaptation","entry":"You can breathe air and water, and you have a swimming speed equal to your walking speed."}]},{"type":"text","content":"At 5th level, your body evolves further, developing new characteristics. Choose one of the options you didn't take at 1st level, or one of the following options:"},{"type":"list","items":[{"type":"item","name":"Grappling Appendage","entry":"You have two special appendages growing alongside your arms. Choose whether they're both claws or tentacles. As an action, you can use one of them to try to grapple a creature. Each one is also a natural weapon, which you can use to make an unarmed strike. If you hit with it, the target takes bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike. Immediately after hitting, you can try to grapple the target as a bonus action. These appendages can't precisely manipulate anything and can't wield weapons, magic items, or other specialized equipment."},{"type":"item","name":"Carapace","entry":"Your skin in places is covered by a thick shell. You gain a +1 bonus to AC when you're not wearing heavy armor."},{"type":"item","name":"Acid Spit","entry":"As an action, you can spray acid from glands in your mouth, targeting one creature or object you can see within 30 feet of you. The target takes <span class=\\"text-red-400 font-semibold\\">2d10</span> acid damage unless it succeeds on a Dexterity saving throw against a DC equal to 8 + your Constitution modifier + your proficiency bonus. This damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach 11th level (<span class=\\"text-red-400 font-semibold\\">3d10</span>) and 17th level (<span class=\\"text-red-400 font-semibold\\">4d10</span>). You can use this trait a number of times equal to your Constitution modifier (minimum of once), and you regain all expended uses of it when you finish a long rest."}]}]}],"subraces":[],"traits":["Amphibious","Natural Armor","Natural Weapon"],"languages":[{"common":true,"choose":{"from":["elvish","other"],"count":1}}],"page":20},{"name":"Siren","source":"PSX","edition":"classic","size":["M"],"speed":{"walk":25,"fly":30},"ability":[{"cha":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most sirens lean toward chaotic alignment, cherishing the freedom and independence that comes from joining a pirate crew."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Sirens stand about 5 to 6 feet tall, but their bodies are slender and their bones partially hollow to facilitate their flight. Your size is Medium."}]},{"type":"section","name":"Siren's Song","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=friends\\" class=\\"text-dnd-gold hover:underline\\">friends</a> cantrip and can cast it without material components."}]},{"type":"section","name":"Flight","entries":[{"type":"text","content":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for <i>encumbrance</i>, you can't use your flying speed if you are encumbered.)"}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common Trade Pidgin (if it exists in your campaign) and Siren."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":17},{"name":"Skeleton","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"dex":2,"int":-4,"cha":-4}],"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are Undead."}]},{"type":"section","name":"Brittle Bones","entries":[{"type":"text","content":"You are vulnerable to bludgeoning damage."}]},{"type":"section","name":"Undead Nature","entries":[{"type":"text","content":"You are immune to poison damage and <i class=\\"text-dnd-gold\\">exhaustion</i>, and you can't be <i class=\\"text-dnd-gold\\">poisoned</i>. You don't require air, food, drink, or sleep."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can't speak, but you can understand the languages you knew in life."}]}],"subraces":[],"traits":["Improved Resting","NPC Race"],"page":282},{"name":"Tabaxi","source":"MPMM","edition":"classic","size":["S","M"],"speed":{"walk":30,"climb":true},"skillProficiencies":[{"perception":true,"stealth":true}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your walking speed is 30 feet, and you have a climbing speed equal to your walking speed."}]},{"type":"section","name":"Cat's Claws","entries":[{"type":"text","content":"You can use your claws to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Cat's Talent","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> and <i>Stealth</i> skills."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Feline Agility","entries":[{"type":"text","content":"Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"anyStandard":1}],"page":33},{"name":"Tabaxi","source":"VGM","edition":"classic","size":["M"],"speed":{"walk":30,"climb":20},"ability":[{"dex":2,"cha":1}],"skillProficiencies":[{"perception":true,"stealth":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Tabaxi have lifespans equivalent to humans."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tabaxi are taller on average than humans and relatively slender. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have a cat's keen senses, especially in the dark. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Feline Agility","entries":[{"type":"text","content":"Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."}]},{"type":"section","name":"Cat's Claws","entries":[{"type":"text","content":"Because of your claws, you have a climbing speed of 20 feet. In addition, your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Cat's Talents","entries":[{"type":"text","content":"You have proficiency in the <i>Perception</i> and <i>Stealth</i> skills."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one other language of your choice."}]}],"subraces":[],"traits":["Natural Weapon"],"languages":[{"common":true,"anyStandard":1}],"page":113},{"name":"Thri-kreen","source":"AAG","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are a Monstrosity."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Chameleon Carapace","entries":[{"type":"text","content":"While you aren't wearing armor, your carapace gives you a base Armor Class of 13 + your Dexterity modifier."},{"type":"text","content":"As an action, you can change the color of your carapace to match the color and texture of your surroundings, giving you advantage on Dexterity (<i>Stealth</i>) checks made to <b>hide</b> in those surroundings."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Secondary Arms","entries":[{"type":"text","content":"You have two slightly smaller secondary arms below your primary pair of arms. The secondary arms can manipulate an object, open or close a door or container, pick up or set down a Tiny object, or wield a weapon that has the <i>L</i> property."}]},{"type":"section","name":"Sleepless","entries":[{"type":"text","content":"You do not require sleep and can remain conscious during a long rest, though you must still refrain from strenuous activity to gain the benefit of the rest."}]},{"type":"section","name":"Thri-kreen Telepathy","entries":[{"type":"text","content":"Without the assistance of magic, you can't speak the non-thri-kreen languages you know. Instead you use telepathy to convey your thoughts. You have the magical ability to transmit your thoughts mentally to willing creatures within 120 feet of yourself. A contacted creature doesn't need to share a language with you to understand your thoughts, but it must be able to understand at least one language. Your telepathic link to a creature is broken if you and the creature move more than 120 feet apart, if either of you is <i class=\\"text-dnd-gold\\">incapacitated</i>, or if either of you mentally breaks the contact (no action required)."}]}],"subraces":[],"traits":["Improved Resting","Natural Armor"],"page":15},{"name":"Tiefling","source":"PHB","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2,"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Tieflings mature at the same rate as humans but live a few years longer."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tieflings are about the same size and build as humans. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your infernal heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Hellish Resistance","entries":[{"type":"text","content":"You have resistance to fire damage."}]},{"type":"section","name":"Infernal Legacy","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=thaumaturgy\\" class=\\"text-dnd-gold hover:underline\\">thaumaturgy</a> cantrip. Once you reach 3rd level, you can cast the <a href=\\"/spells?search=hellish rebuke\\" class=\\"text-dnd-gold hover:underline\\">hellish rebuke</a> spell as a 2nd-level spell with this trait; you regain the ability to cast it when you finish a long rest. Once you reach 5th level, you can also cast the <a href=\\"/spells?search=darkness\\" class=\\"text-dnd-gold hover:underline\\">darkness</a> spell once per day with this trait; you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Infernal."}]}],"subraces":[],"traits":["Uncommon Race"],"languages":[{"common":true,"infernal":true}],"page":42},{"name":"Tiefling","source":"XPHB","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You have <i>Darkvision</i> with a range of 60 feet."}]},{"type":"section","name":"Fiendish Legacy","entries":[{"type":"text","content":"You are the recipient of a legacy that grants you supernatural abilities. Choose a legacy from the Fiendish Legacies table. You gain the level 1 benefit of the chosen legacy."},{"type":"text","content":"When you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a <i>Long Rest</i>. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy)."},{"type":"table","caption":"Fiendish Legacies","colLabels":["Legacy","Level 1","Level 3","Level 5"],"rows":[["Abyssal","You have <i>Resistance</i> to Poison damage. You also know the <a href=\\"/spells?search=Poison Spray\\" class=\\"text-dnd-gold hover:underline\\">Poison Spray</a> cantrip.","<a href=\\"/spells?search=Ray of Sickness\\" class=\\"text-dnd-gold hover:underline\\">Ray of Sickness</a>","<a href=\\"/spells?search=Hold Person\\" class=\\"text-dnd-gold hover:underline\\">Hold Person</a>"],["Chthonic","You have <i>Resistance</i> to Necrotic damage. You also know the <a href=\\"/spells?search=Chill Touch\\" class=\\"text-dnd-gold hover:underline\\">Chill Touch</a> cantrip.","<a href=\\"/spells?search=False Life\\" class=\\"text-dnd-gold hover:underline\\">False Life</a>","<a href=\\"/spells?search=Ray of Enfeeblement\\" class=\\"text-dnd-gold hover:underline\\">Ray of Enfeeblement</a>"],["Infernal","You have <i>Resistance</i> to Fire damage. You also know the <a href=\\"/spells?search=Fire Bolt\\" class=\\"text-dnd-gold hover:underline\\">Fire Bolt</a> cantrip.","<a href=\\"/spells?search=Hellish Rebuke\\" class=\\"text-dnd-gold hover:underline\\">Hellish Rebuke</a>","<a href=\\"/spells?search=Darkness\\" class=\\"text-dnd-gold hover:underline\\">Darkness</a>"]]}]},{"type":"section","name":"Otherworldly Presence","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=Thaumaturgy\\" class=\\"text-dnd-gold hover:underline\\">Thaumaturgy</a> cantrip. When you cast it with this trait, the spell uses the same spellcasting ability you use for your Fiendish Legacy Trait."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"infernal":true}],"page":197},{"name":"Tortle","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":[{"choose":{"from":["animal handling","medicine","nature","perception","stealth","survival"]}}],"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Claws","entries":[{"type":"text","content":"You have claws that you can use to make unarmed strikes. When you hit with them, the strike deals <span class=\\"text-red-400 font-semibold\\">1d6</span> + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for up to 1 hour."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"Your shell provides you a base AC of 17 (your Dexterity modifier doesn't affect this number). You can't wear light, medium, or heavy armor, but if you are using a shield, you can apply the shield's bonus as normal."}]},{"type":"section","name":"Nature's Intuition","entries":[{"type":"text","content":"Thanks to your mystical connection to nature, you gain proficiency with one of the following skills of your choice: <i>Animal Handling</i>, <i>Medicine</i>, <i>Nature</i>, <i>Perception</i>, <i>Stealth</i>, or <i>Survival</i>."}]},{"type":"section","name":"Shell Defense","entries":[{"type":"text","content":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to your AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are <i class=\\"text-dnd-gold\\">prone</i>, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge from your shell."}]}],"subraces":[],"traits":["Natural Armor","Natural Weapon"],"languages":[{"aquan":true,"common":true}],"page":34},{"name":"Tortle","source":"TTP","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"wis":1}],"skillProficiencies":[{"survival":true}],"entries":[{"type":"section","name":"","entries":[{"type":"text","content":"The Tortle Package is considered part of Xanathar's Guide to Everything for Adventurers League character creation."}]},{"type":"section","name":"Age","entries":[{"type":"text","content":"Young tortles crawl for a few weeks after birth before learning to walk on two legs. They reach adulthood by the age of 15 and live an average of 50 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Tortles tend to lead orderly, ritualistic lives. They develop customs and routines, becoming more set in their ways as they age. Most are lawful good. A few can be selfish and greedy, tending more toward evil, but it's unusual for a tortle to shuck off order in favor of chaos."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tortle adults stand 5 to 6 feet tall and average 450 pounds. Their shells account for roughly one-third of their weight. Your size is Medium."}]},{"type":"section","name":"Claws","entries":[{"type":"text","content":"Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to <span class=\\"text-red-400 font-semibold\\">1d4</span> + your Strength modifier, instead of bludgeoning damage normal for an unarmed strike."}]},{"type":"section","name":"Hold Breath","entries":[{"type":"text","content":"You can hold your breath for up to 1 hour at a time. Tortles aren't natural swimmers, but they can remain underwater for some time before needing to come up for air."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"Due to your shell and the shape of your body, you are ill-suited to wearing armor. Your shell provides ample protection, however; it gives you a base AC of 17 (your Dexterity modifier doesn't affect this number). You gain no benefit from wearing armor, but if you are using a shield, you can apply the shield's bonus as normal."}]},{"type":"section","name":"Shell Defense","entries":[{"type":"text","content":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are <i class=\\"text-dnd-gold\\">prone</i>, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge from your shell."}]},{"type":"section","name":"Survival Instinct","entries":[{"type":"text","content":"You gain proficiency in the <i>Survival</i> skill. Tortles have finely honed survival instincts."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Aquan and Common."}]}],"subraces":[],"traits":["Natural Armor","Natural Weapon"],"languages":[{"aquan":true,"common":true}],"page":3},{"name":"Triton","source":"MOT","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"str":1,"cha":1,"con":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Tritons reach maturity around age 15 and can live up to 200 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tritons are slightly shorter than humans, averaging about 5 feet tall. Your size is Medium."}]},{"type":"section","name":"Swim Speed","entries":[{"type":"text","content":"You have a swimming speed of 30 feet."}]},{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Control Air and Water","entries":[{"type":"text","content":"A child of the sea, you can call on the magic of elemental air and water. You can cast <a href=\\"/spells?search=fog cloud\\" class=\\"text-dnd-gold hover:underline\\">fog cloud</a> with this trait. Starting at 3rd level, you can cast <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> with it, and starting at 5th level, you can also cast <a href=\\"/spells?search=wall of water\\" class=\\"text-dnd-gold hover:underline\\">wall of water</a> with it. Once you cast a spell with this trait, you can't cast that spell with it again until you finish a long rest. Charisma is your spellcasting ability for these spells."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Emissary of the Sea","entries":[{"type":"text","content":"Aquatic beasts have an extraordinary affinity with your people. You can communicate simple ideas with beasts that can breathe water. They can understand the meaning of your words, though you have no special ability to understand them in return."}]},{"type":"section","name":"Guardians of the Depths","entries":[{"type":"text","content":"Adapted to even the most extreme ocean depths, you have resistance to cold damage."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Primordial."}]}],"subraces":[],"traits":["Amphibious"],"languages":[{"common":true,"primordial":true}],"page":26},{"name":"Triton","source":"MPMM","edition":"classic","size":["M"],"speed":{"walk":30,"swim":true},"skillProficiencies":null,"entries":[{"type":"section","name":"Speed","entries":[{"type":"text","content":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."}]},{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Control Air and Water","entries":[{"type":"text","content":"You can cast <a href=\\"/spells?search=fog cloud\\" class=\\"text-dnd-gold hover:underline\\">fog cloud</a> with this trait. Starting at 3rd level, you can cast the <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> spell with this trait. Starting at 5th level, you can also cast the <a href=\\"/spells?search=water walk\\" class=\\"text-dnd-gold hover:underline\\">water walk</a> spell with it. Once you cast any of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have of the appropriate level."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Emissary of the Sea","entries":[{"type":"text","content":"You can communicate simple ideas to any Beast, Elemental, or Monstrosity that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."}]},{"type":"section","name":"Guardian of the Depths","entries":[{"type":"text","content":"Adapted to the frigid ocean depths, you have resistance to cold damage."}]}],"subraces":[],"traits":["Amphibious"],"languages":[{"common":true,"primordial":true}],"page":35},{"name":"Triton","source":"VGM","edition":"classic","size":["M"],"speed":{"walk":30,"swim":30},"ability":[{"str":1,"cha":1,"con":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Tritons reach maturity around age 15 and can live up to 200 years."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tritons are slightly shorter than humans, averaging about 5 feet tall. Your size is Medium."}]},{"type":"section","name":"Swim Speed","entries":[{"type":"text","content":"You have a swimming speed of 30 feet."}]},{"type":"section","name":"Amphibious","entries":[{"type":"text","content":"You can breathe air and water."}]},{"type":"section","name":"Control Air and Water","entries":[{"type":"text","content":"A child of the sea, you can call on the magic of elemental air and water. You can cast <a href=\\"/spells?search=fog cloud\\" class=\\"text-dnd-gold hover:underline\\">fog cloud</a> with this trait. Starting at 3rd level, you can cast <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> with it, and starting at 5th level, you can also cast <a href=\\"/spells?search=wall of water\\" class=\\"text-dnd-gold hover:underline\\">wall of water</a> with it. Once you cast a spell with this trait, you can't cast that spell with it again until you finish a long rest. Charisma is your spellcasting ability for these spells."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Emissary of the Sea","entries":[{"type":"text","content":"Aquatic beasts have an extraordinary affinity with your people. You can communicate simple ideas with beasts that can breathe water. They can understand the meaning of your words, though you have no special ability to understand them in return."}]},{"type":"section","name":"Guardians of the Depths","entries":[{"type":"text","content":"Adapted to even the most extreme ocean depths, you have resistance to cold damage."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Primordial."}]}],"subraces":[],"traits":["Amphibious"],"languages":[{"common":true,"primordial":true}],"page":115},{"name":"Troglodyte","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"str":2,"con":2,"int":-4,"cha":-4}],"skillProficiencies":null,"entries":[{"type":"section","name":"Chameleon Skin","entries":[{"type":"text","content":"You have advantage on Dexterity (<i>Stealth</i>) checks made to hide."}]},{"type":"section","name":"Stench","entries":[{"type":"text","content":"Any creature other than a troglodyte that starts its turn within 5 ft. of you must succeed on a DC 12 Constitution saving throw or be <i class=\\"text-dnd-gold\\">poisoned</i> until the start of the creature's next turn. On a successful saving throw, the creature is immune to the stench of all troglodytes for 1 hour."}]},{"type":"section","name":"Sunlight Sensitivity","entries":[{"type":"text","content":"While in sunlight, you have disadvantage on attack rolls, as well as on Wisdom (<i>Perception</i>) checks that rely on sight."}]},{"type":"section","name":"Natural Armor","entries":[{"type":"text","content":"Your thick hide grants you a +1 bonus to Armor Class."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Troglodyte."}]}],"subraces":[],"traits":["Natural Armor","NPC Race","Sunlight Sensitivity"],"languages":[{"other":true}],"page":282},{"name":"Vampire","source":"PSZ","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Vampires don't mature and age in the same way that other races do. Every living vampire is either a bloodchief, infected by Ulamog's influence in the distant reaches of history, or was spawned by a bloodchief from a living human. Most vampires are thus very old, but few have any memory of their earliest years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Vampires have no innate tendency toward evil, but consuming the life energy of other creatures often pushes them to that end. Regardless of their moral bent, the strict hierarchies of their bloodchiefs inclines them toward a lawful alignment."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Vampires are about the same size and build as humans. Your size is Medium."}]},{"type":"section","name":"Blood Thirst","entries":[{"type":"text","content":"You can drain blood and life energy from a willing creature, or one that is <i class=\\"text-dnd-gold\\">grappled</i> by you, <i class=\\"text-dnd-gold\\">incapacitated</i>, or <i class=\\"text-dnd-gold\\">restrained</i>. Make a melee attack against the target. If you hit, you deal 1 piercing damage and <span class=\\"text-red-400 font-semibold\\">1d6</span> necrotic damage. The target's hit point maximum is reduced by an amount equal to the necrotic damage taken, and you regain hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Vampire."}]},{"type":"section","name":"Vampiric Resistance","entries":[{"type":"text","content":"You have resistance to necrotic damage."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":14},{"name":"Vedalken","source":"GGR","edition":"classic","size":["M"],"speed":30,"ability":[{"int":2,"wis":1}],"skillProficiencies":[{"choose":{"from":["arcana","history","investigation","medicine","performance","sleight of hand"]}}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Vedalken mature slower than humans do, reaching maturity around age 40. Their life span is typically 350 years, with some living to the age of 500."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Vedalken are usually lawful and non-evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Tall and slender, Vedalken stand 6 to 6½ feet tall on average and usually weigh less than 200 pounds. Your size is Medium."}]},{"type":"section","name":"Vedalken Dispassion","entries":[{"type":"text","content":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws."}]},{"type":"section","name":"Tireless Precision","entries":[{"type":"text","content":"You are proficient in one of the following skills of your choice: <i>Arcana</i>, <i>History</i>, <i>Investigation</i>, <i>Medicine</i>, <i>Performance</i>, or <i>Sleight of Hand</i>. You are also proficient with one <i>tool</i> of your choice."},{"type":"text","content":"Whenever you make an ability check with the chosen skill or tool, roll a <span class=\\"text-green-400 font-mono\\">d4</span> and add the number rolled to the check's total."}]},{"type":"section","name":"Partially Amphibious","entries":[{"type":"text","content":"By absorbing oxygen through your skin, you can breathe underwater for up to 1 hour. Once you've reached that limit, you can't use this trait again until you finish a long rest."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Vedalken, and one other language of your choice."}]}],"subraces":[],"traits":["Skill Bonus Dice","Tool Bonus Dice"],"languages":[{"common":true,"other":true,"anyStandard":1}],"page":21},{"name":"Vedalken","source":"PSK","edition":"classic","size":["M"],"speed":30,"ability":[{"int":2,"wis":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Vedalken mature at the same rate humans do, and most are expected to settle down into an adult life by around age 40. They can live 350 to almost 500 years."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Vedalken are most often lawful and rarely evil."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Vedalken are taller than humans but more slender. They average 6 to 6½ feet tall, but usually weigh less than 200 pounds. Your size is Medium."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and Vedalken. The Vedalken language is renowned for its technical treatises and its catalogs of knowledge about the natural world and the aether that pervades it."}]},{"type":"section","name":"Vedalken Cunning","entries":[{"type":"text","content":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic."}]},{"type":"section","name":"Aether Lore","entries":[{"type":"text","content":"Whenever you make an Intelligence (<i>History</i>) check related to magic items or aether-powered technological devices, you can add twice your proficiency bonus, instead of any proficiency bonus you normally apply."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"other":true}],"page":23},{"name":"Verdan","source":"AI","edition":"classic","size":["V"],"speed":30,"ability":[{"con":1,"cha":2}],"skillProficiencies":[{"persuasion":true}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Verdan reach adulthood at around the age of 24, and it is thought that they might live to nearly 200 years old. However, because no verdan has died of old age since the race's initial creation, their upper age limits remain subject to speculation."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Verdan are generally good, although their absence of racial identity and shared history can sometimes see individual verdan become untethered from any moral or ethical framework."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Verdan start out similar in size to the goblins they were created from, ranging from 3 to 4 feet in height. But at some point after reaching maturity, each verdan undergoes a sudden growth spurt of 2 feet or more. At 1st level, you are a Small creature. When you reach 5th level, you become a Medium creature."}]},{"type":"section","name":"Black Blood Healing","entries":[{"type":"text","content":"The black blood that is a sign of your people's connection to That-Which-Endures boosts your natural healing. When you roll a 1 or 2 on any Hit Die you spend at the end of a short rest, you can reroll the die and must use the new roll."}]},{"type":"section","name":"Limited Telepathy","entries":[{"type":"text","content":"You can telepathically speak to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand your telepathy, but it must be able to understand at least one language. This process of communication is slow and limited, allowing you to transmit and receive only simple ideas and straightforward concepts."}]},{"type":"section","name":"Persuasive","entries":[{"type":"text","content":"Your people's lack of history makes you trustworthy and humble. You have proficiency in the <i>Persuasion</i> skill."}]},{"type":"section","name":"Telepathic Insight","entries":[{"type":"text","content":"Your mind's connection to the world around you strengthens your will. You have advantage on all Wisdom and Charisma saving throws."}]},{"type":"section","name":"Language","entries":[{"type":"text","content":"You speak, read, and write Common, Goblin, and one additional language of your choice. This language typically has some connection to one of the areas or cultures that has been part of your life."}]}],"subraces":[],"traits":[],"languages":[{"common":true,"goblin":true,"anyStandard":1}],"page":72},{"name":"Warforged","source":"EFA","edition":"one","size":["S","M"],"speed":30,"skillProficiencies":[{"any":1}],"entries":[{"type":"section","name":"Construct Resilience","entries":[{"type":"text","content":"You have <i>Resistance</i> to Poison damage. You also have <i>Advantage</i> on saving throws to avoid or end the <i class=\\"text-dnd-gold\\">Poisoned</i> condition."}]},{"type":"section","name":"Integrated Protection","entries":[{"type":"text","content":"You gain a +1 bonus to your <i>Armor Class</i>. In addition, armor you have donned can't be removed against your will while you're alive."}]},{"type":"section","name":"Sentry's Rest","entries":[{"type":"text","content":"You don't need to sleep, and magic can't put you to sleep. You can finish a <i>Long Rest</i> in 6 hours if you spend those hours in an inactive, motionless state. During this time, you appear inert but remain conscious."}]},{"type":"section","name":"Specialized Design","entries":[{"type":"text","content":"You gain one skill proficiency and one tool proficiency of your choice."}]},{"type":"section","name":"Tireless","entries":[{"type":"text","content":"You don't gain <i class=\\"text-dnd-gold\\">Exhaustion</i> levels from dehydration, malnutrition, or suffocation."}]}],"subraces":[],"traits":["Improved Resting","Natural Armor"],"languages":[{"common":true,"anyStandard":1}],"page":38},{"name":"Warforged","source":"ERLW","edition":"classic","size":["M"],"speed":30,"ability":[{"con":2,"choose":{"from":["str","dex","int","wis","cha"],"count":1}}],"skillProficiencies":[{"any":1}],"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"A typical warforged is between two and thirty years old. The maximum warforged lifespan remains a mystery; so far, warforged have shown no signs of deterioration due to age. You are immune to magical aging effects."}]},{"type":"section","name":"Alignment","entries":[{"type":"text","content":"Most warforged take comfort in order and discipline, tending toward law and neutrality. But some have absorbed the morality, or lack thereof, of the beings with which they served."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Your size is Medium."}]},{"type":"section","name":"Constructed Resilience","entries":[{"type":"text","content":"You were created to have remarkable fortitude, represented by the following benefits:"},{"type":"list","items":["You have advantage on saving throws against being <i class=\\"text-dnd-gold\\">poisoned</i>, and you have resistance to poison damage.","You don't need to eat, drink, or breathe.","You are immune to disease.","You don't need to sleep, and magic can't put you to sleep."]}]},{"type":"section","name":"Sentry's Rest","entries":[{"type":"text","content":"When you take a long rest, you must spend at least six hours in an inactive, motionless state, rather than sleeping. In this state, you appear inert, but it doesn't render you <i class=\\"text-dnd-gold\\">unconscious</i>, and you can see and hear as normal."}]},{"type":"section","name":"Integrated Protection","entries":[{"type":"text","content":"Your body has built-in defensive layers, which can be enhanced with armor:"},{"type":"list","items":["You gain a +1 bonus to Armor Class.","You can don only armor with which you have proficiency. To don armor other than a shield, you must incorporate it into your body over the course of 1 hour, during which you remain in contact with the armor. To doff armor, you must spend 1 hour removing it. You can rest while donning or doffing armor in this way.","While you live, the armor incorporated into your body can't be removed against your will."]}]},{"type":"section","name":"Specialized Design","entries":[{"type":"text","content":"You gain one skill proficiency and one tool proficiency of your choice."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common and one other language of your choice."}]}],"subraces":[],"traits":["Improved Resting","Natural Armor"],"languages":[{"common":true,"anyStandard":1}],"page":35},{"name":"Yuan-Ti","source":"MPMM","edition":"classic","size":["S","M"],"speed":30,"skillProficiencies":null,"entries":[{"type":"section","name":"Size","entries":[{"type":"text","content":"You are Medium or Small. You choose the size when you select this race."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}]},{"type":"section","name":"Magic Resistance","entries":[{"type":"text","content":"You have advantage on saving throws against spells."}]},{"type":"section","name":"Poison Resilience","entries":[{"type":"text","content":"You have advantage on saving throws you make to avoid or end the <i class=\\"text-dnd-gold\\">poisoned</i> condition on yourself. You also have resistance to poison damage."}]},{"type":"section","name":"Serpentine Spellcasting","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=poison spray\\" class=\\"text-dnd-gold hover:underline\\">poison spray</a> cantrip. You can cast <a href=\\"/spells?search=animal friendship\\" class=\\"text-dnd-gold hover:underline\\">animal friendship</a> an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast <a href=\\"/spells?search=suggestion\\" class=\\"text-dnd-gold hover:underline\\">suggestion</a> with this trait. Once you cast it, you can't do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher."},{"type":"text","content":"Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}]}],"subraces":[],"traits":["Magic Resistance"],"page":36},{"name":"Yuan-ti Pureblood","source":"VGM","edition":"classic","size":["M"],"speed":30,"ability":[{"cha":2,"int":1}],"skillProficiencies":null,"entries":[{"type":"section","name":"Age","entries":[{"type":"text","content":"Purebloods mature at the same rate as humans and have lifespans similar in length to theirs."}]},{"type":"section","name":"Size","entries":[{"type":"text","content":"Purebloods match humans in average size and weight. Your size is Medium."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Innate Spellcasting","entries":[{"type":"text","content":"You know the <a href=\\"/spells?search=poison spray\\" class=\\"text-dnd-gold hover:underline\\">poison spray</a> cantrip. You can cast <a href=\\"/spells?search=animal friendship\\" class=\\"text-dnd-gold hover:underline\\">animal friendship</a> an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast <a href=\\"/spells?search=suggestion\\" class=\\"text-dnd-gold hover:underline\\">suggestion</a> with this trait. Once you cast it, you can't do so again until you finish a long rest. Charisma is your spellcasting ability for these spells."}]},{"type":"section","name":"Magic Resistance","entries":[{"type":"text","content":"You have advantage on saving throws against spells and other magical effects."}]},{"type":"section","name":"Poison Immunity","entries":[{"type":"text","content":"You are immune to poison damage and the <i class=\\"text-dnd-gold\\">poisoned</i> condition."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can speak, read, and write Common, Abyssal, and Draconic."}]}],"subraces":[],"traits":["Magic Resistance","Monstrous Race"],"languages":[{"common":true,"abyssal":true,"draconic":true}],"page":120},{"name":"Zombie","source":"DMG","edition":"classic","size":["M"],"speed":30,"ability":[{"str":1,"con":2,"int":-6,"wis":-4,"cha":-4}],"skillProficiencies":null,"entries":[{"type":"section","name":"Creature Type","entries":[{"type":"text","content":"You are Undead."}]},{"type":"section","name":"Undead Fortitude","entries":[{"type":"text","content":"If damage reduces you to 0 hit points, you must make a Constitution saving throw with a DC of 5+the damage taken, unless the damage is radiant or from a critical hit. On a success, you drop to 1 hit point instead."}]},{"type":"section","name":"Undead Nature","entries":[{"type":"text","content":"You are immune to poison damage, and you can't be <i class=\\"text-dnd-gold\\">poisoned</i>. You don't require air, food, drink, or sleep."}]},{"type":"section","name":"Darkvision","entries":[{"type":"text","content":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}]},{"type":"section","name":"Languages","entries":[{"type":"text","content":"You can't speak, but you can understand the languages you knew in life."}]}],"subraces":[],"traits":["Improved Resting","NPC Race"],"page":282},{"name":"Aarakocra (EEPC)","source":"EEPC","edition":"classic","size":["M"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"auran":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Flight","Talons","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Aarakocra reach maturity by age 3. Compared to humans, aarakocra don’t usually live longer than 30 years."},{"type":"item","name":"Alignment.","entry":"Most aarakocra are good and rarely choose sides when it comes to law and chaos. Tribal leaders and warriors might be lawful, while explorers and adventurers might tend toward chaotic."},{"type":"item","name":"Size.","entry":"Aarakocra are about 5 feet tall. They have thin, lightweight bodies that weigh between 80 and 100 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet."},{"type":"item","name":"Flight.","entry":"You have a flying speed of 50 feet. To use this speed, you can’t be wearing medium or heavy armor."},{"type":"item","name":"Talons.","entry":"You are proficient with your unarmed strikes, which deal 1d4 slashing damage on a hit."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Aarakocra, and Auran."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aarakocra (MPMotM)","source":"MPMM","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Flight","Talons","Wind Caller","Languages"],"entries":[{"type":"text","content":"<i>**//A winged people who originated on the Elemental Plane of Air, aarakocra soar through the sky wherever they wander. The first aarakocra served the Wind Dukes of Aaqa — mighty beings of air — and were imbued with a measure of their masters’ power over winds. Their descendants still command echoes of that power.//**</i> <i>**//From below, aarakocra look like large birds and thus are sometimes called birdfolk. Only when they roost on a branch or walk across the ground is their Humanoid nature clear. Standing upright, aarakocra are typically about 5 feet tall, and they have long, narrow legs that taper to sharp talons. Feathers cover their bodies — usually red, orange, yellow, brown, or gray. Their heads are also avian, often resembling those of parrots or eagles.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Flight.","entry":"Because of your wings, you have a flying speed equal to your walking speed. You can’t use this flying speed if you’re wearing medium or heavy armor."},{"type":"item","name":"Talons.","entry":"You have talons that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Wind Caller.","entry":"Starting at 3rd level, you can cast the Gust of Wind spell with this trait, without requiring a material component. Once you cast the spell with this trait, you can’t do so again until you finish a long rest. You can also cast the spell using any spell slots you have of 2nd level or higher. * Intelligence, Wisdom, or Charisma is your spellcasting ability for it when you cast Gust of Wind with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Court Aasimar (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"elvish":true}],"traits":["Ability Score Increase","Age","Fey Ancestry","Trance","Extra Language","Guidance From the Past"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"You mature at the same rate of an elf, but you can live up to 1,000 years."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"You don't need to sleep. Instead, you meditate deeply, remaining semiconscious for 4 hours a day. After resting in this way, you gain the same benefits that a human does from 8 hours of sleep."},{"type":"item","name":"Extra Language.","entry":"You can speak, read, and write elvish."},{"type":"item","name":"Guidance From the Past.","entry":"Starting at 3rd level, you can use an action to draw from your connection to your ancestors. Misty tendrils flow around you, whispering advice that only you can hear. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you gain advantage on all Wisdom checks and saving throws. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aasimar Ee","source":"VGM","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"elvish":true}],"traits":["Ability Score Increase","Age","Size","Speed","Darkvision","Celestial Resistance","Healing Hands","Light Bearer","Languages","Ability Score Increase","Age","Fey Ancestry","Trance","Extra Language","Guidance From the Past","Ability Score Increase","Shroud of Life and Death"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2."},{"type":"item","name":"Age.","entry":"Aasimar mature at the same rate as humans, but they can live up to 160 years."},{"type":"item","name":"Size.","entry":"Aasimar have the same range of height and weight as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Blessed with a radiant soul, your vision can easily cut through darkness. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Celestial Resistance.","entry":"You have resistance to necrotic damage and radiant damage."},{"type":"item","name":"Healing Hands.","entry":"As an action, you can touch a creature and cause it to regain a number of hit points equal to your level. Once you use this trait, you can't use it again until you finish a long rest."},{"type":"item","name":"Light Bearer.","entry":"You know the Light cantrip. Charisma is your spellcasting ability for it."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Celestial."},{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"You mature at the same rate of an elf, but you can live up to 1,000 years."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"You don't need to sleep. Instead, you meditate deeply, remaining semiconscious for 4 hours a day. After resting in this way, you gain the same benefits that a human does from 8 hours of sleep."},{"type":"item","name":"Extra Language.","entry":"You can speak, read, and write elvish."},{"type":"item","name":"Guidance From the Past.","entry":"Starting at 3rd level, you can use an action to draw from your connection to your ancestors. Misty tendrils flow around you, whispering advice that only you can hear. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you gain advantage on all Wisdom checks and saving throws. * Once you use this trait, you can't use it again until you finish a long rest."},{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Shroud of Life and Death.","entry":"Starting at 3rd level, you can use your action to awaken the power in your blood, causing a nimbus of crimson energy to flow out from out of you. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you shed dim light in a 10-foot radius, and at the end of each of your turns, one creature within 30 feet of you takes necrotic damage equal to half your level (Rounded up). In addition, if you or an ally within 30 feet drops to 0 hit points without being killed outright, you can use your reaction to preserve them, causing them to drop to 1 hitpoint instead. When you use this reaction, it ends your transformation early. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fallen Aasimar (VGM)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Necrotic Shroud"],"entries":[{"type":"text","content":"<i>**//An aasimar who was touched by dark powers as a youth or who turns to evil in early adulthood can become one of the fallen - a group of aasimar whose inner light has been replaced by shadow.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 1."},{"type":"item","name":"Necrotic Shroud.","entry":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing your eyes to turn into pools of darkness and two skeletal, ghostly, flightless wings to sprout from your back. The instant you transform, other creatures within 10 feet of you that can see you must each succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become frightened of you until the end of your next turn. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra necrotic damage equals your level. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Variant Aasimar, Fernian (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Fernian Resistance","Shroud of Flame","Spirit of Fire"],"entries":[{"type":"list","items":[{"type":"item","name":"Fernian Resistance.","entry":"You have resistance to fire damage and necrotic damage."},{"type":"item","name":"Shroud of Flame.","entry":"When you use your Radiant Consumption trait, you deal fire damage instead of radiant damage."},{"type":"item","name":"Spirit of Fire.","entry":"You know the Produce Flames cantrip. Charisma is your spellcasting ability for it."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Variant Aasimar, Mabaran (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Consuming Touch","Herald of Doom"],"entries":[{"type":"list","items":[{"type":"item","name":"Consuming Touch.","entry":"As an action, you can make a melee spell attack against a creature within your reach. On a hit, the target takes necrotic damage equal to your level and you regain hit points equal to half the damage dealt (rounded up). Once you use this trait, you can't use it again until you finish long rest. Charisma is your spellcasting ability for this trait."},{"type":"item","name":"Herald of Doom.","entry":"You know the Toll the Dead cantrip. Charisma is your spellcasting ability for it."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aasimar (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Celestial Resistance","Healing Hands","Light Bearer","Celestial Revelation","Necrotic Shroud","Radiant Consumption","Radiant Soul","Languages"],"entries":[{"type":"text","content":"<i>**//Whether descended from a celestial being or infused with heavenly power, aasimar are mortals who carry a spark of the Upper Planes within their souls. They can fan that spark to bring light, ease wounds, and unleash the fury of the heavens.//**</i> <i>**//Aasimar can arise among any population of mortals. They resemble their parents, but they live for up to 160 years and often have features that hint at their celestial heritage. These often begin subtle and become more obvious when the aasimar gains the ability to reveal their full celestial nature. The Aasimar Celestial Features table has examples you can choose or use as inspiration to create your own.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Celestial Resistance.","entry":"You have resistance to necrotic damage and radiant damage."},{"type":"item","name":"Healing Hands.","entry":"As an action, you can touch a creature and roll a number of d4s equal to your proficiency bonus. The creature regains a number of hit points equal to the total rolled. Once you use this trait, you can’t use it again until you finish a long rest."},{"type":"item","name":"Light Bearer.","entry":"You know the Light cantrip. Charisma is your spellcasting ability for it."},{"type":"item","name":"Celestial Revelation.","entry":"When you reach 3rd level, choose one of the revelation options below. Thereafter, you can use a bonus action to unleash the celestial energy within yourself, gaining the benefits of that revelation. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation below, you can’t use it again until you finish a long rest:"},{"type":"item","name":"Necrotic Shroud.","entry":"Your eyes briefly become pools of darkness, and ghostly, flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you that can see you must succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become frightened of you until the end of your next turn. Until the transformation ends, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."},{"type":"item","name":"Radiant Consumption.","entry":"Searing light temporarily radiates from your eyes and mouth. For the duration, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes radiant damage equal to your proficiency bonus. Until the transformation ends, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."},{"type":"item","name":"Radiant Soul.","entry":"Two luminous, spectral wings sprout from your back temporarily. Until the transformation ends, you have a flying speed equal to your walking speed, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Protector Aasimar (VGM)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Radiant Soul"],"entries":[{"type":"text","content":"<i>**//Protector aasimar are charged by the powers of good to guard the weak, to strike at evil wherever it arises, and to stand vigilant against the darkness. From a young age, a protector aasimar receives advice and directives that urge to stand against evil.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Radiant Soul.","entry":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing your eyes to glimmer and two luminous, incorporeal wings to sprout from your back. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you have a flying speed of 30 feet, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra radiant damage equals your level. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Scourge Aasimar (VGM)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Radiant Consumption"],"entries":[{"type":"text","content":"<i>**//Scourge aasimar are imbued with a divine energy that blazes intensely within them. It feeds a powerful desire to destroy evil - a desire that is, at its best, unflinching and, at its worst, all-consuming. Many scourge aasimar wear masks to block out the world and focus on containing this power, unmasking themselves only in battle.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Radiant Consumption.","entry":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing a searing light to radiate from you, pour out of your eyes and mouth, and threaten to char you. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, you and each creature within 10 feet of you take radiant damage equal to half your level (rounded up). In addition, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra radiant damage equals your level. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Seeker Aasimar (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Shroud of Life and Death"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Shroud of Life and Death.","entry":"Starting at 3rd level, you can use your action to awaken the power in your blood, causing a nimbus of crimson energy to flow out from out of you. * Your transformation lasts for 1 minute or until you end it as a bonus action. During it, you shed dim light in a 10-foot radius, and at the end of each of your turns, one creature within 30 feet of you takes necrotic damage equal to half your level (Rounded up). In addition, if you or an ally within 30 feet drops to 0 hit points without being killed outright, you can use your reaction to preserve them, causing them to drop to 1 hitpoint instead. When you use this reaction, it ends your transformation early. * Once you use this trait, you can't use it again until you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aasimar (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"celestial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Celestial Resistance","Healing Hands","Light Bearer","Languages","Subrace"],"entries":[{"type":"text","content":"<i>**//Aasimar bear within their souls the light of the heavens. They are descended from humans with a touch of the power of Mount Celestia, the divine realm of many lawful good deities. Aasimar are born to serve as champions of the gods, their births hailed as blessed events. They are a people of otherworldly visages, with luminous features that reveal their celestial heritage.//**</i> <i>**//An aasimar, except for one who has turned to evil, has a link to an angelic being. That being – usually a deva – provides guidance to the aasimar, though this connection functions only in dreams. As such, the guidance is not a direct command or a simple spoken word. Instead, the aasimar receives visions, prophecies, and feelings.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2."},{"type":"item","name":"Age.","entry":"Aasimar mature at the same rate as humans, but they can live up to 160 years."},{"type":"item","name":"Alignment.","entry":"Imbued with celestial power, most aasimar are good. Outcast aasimar are most often neutral or even evil."},{"type":"item","name":"Size.","entry":"Aasimar have the same range of height and weight as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Blessed with a radiant soul, your vision can easily cut through darkness. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Celestial Resistance.","entry":"You have resistance to necrotic damage and radiant damage."},{"type":"item","name":"Healing Hands.","entry":"As an action, you can touch a creature and cause it to regain a number of hit points equal to your level. Once you use this trait, you can't use it again until you finish a long rest."},{"type":"item","name":"Light Bearer.","entry":"You know the Light cantrip. Charisma is your spellcasting ability for it."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Celestial."},{"type":"item","name":"Subrace.","entry":"Three subraces of aasimar exist: protector aasimar, scourge aasimar, and fallen aasimar. Choose one of them for your character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Autognome (UA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Armored Casing","Built for Success","Mechanical Nature","Sentry’s Rest","Specialized Design","True Life","Languages"],"entries":[{"type":"text","content":"<i>**//An autognome bears a resemblance to its creator, and most autognomes are programmed to speak and understand Gnomish. The internal components used in an autognome’s manufacture can vary wildly; one autognome might have an actual beating heart in its chest cavity, while another might be powered by stardust or intricate clockwork gears.//**</i> <i>**//Roll on the Autognome History table or choose an entry to determine what event set your auto gnome on the path to adventure. If nothing on the table appeals to you, work with your DM to create an origin story for your autognome.//**</i> <i>**//Like gnomes, autognomes can live for centuries, up to 500 years.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Construct."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet"},{"type":"item","name":"Armored Casing.","entry":"You are encased in thin metal or some other durable material. While you aren’t wearing armor, your base Armor Class is 13 + your Dexterity modifier."},{"type":"item","name":"Built for Success.","entry":"You can add a d4 to one attack roll, ability check, or saving throw you make, and you can do so after seeing the d20 but before the effects of the roll are resolved. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Mechanical Nature.","entry":"You have resistance to poison damage and immunity to disease, and you have advantage on saving throws against being paralyzed or poisoned. You don’t need to eat, drink, or breathe."},{"type":"item","name":"Sentry’s Rest.","entry":"When you take a long rest, you spend at least 6 hours in an inactive, motionless state, instead of sleeping. In this state, you appear inert, but you aren’t unconscious."},{"type":"item","name":"Specialized Design.","entry":"You gain two tool proficiencies of your choice."},{"type":"item","name":"True Life.","entry":"If the Mending spell is cast on you, you can expend a Hit Die, roll it, and regain a number of hit points equal to the roll plus your Constitution modifier (minimum of 1 hit point). In addition, your creator designed you to benefit from common spells that preserve life but that normally don’t affect Constructs: Cure Wounds, Healing Word, and Spare the Dying."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aven Features Core","source":"HB","edition":"classic","size":["M"],"speed":{"walk":25},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Age.","entry":"Like humans, aven reach adulthood in their late teens and can theoretically live into their 80s. Of course, most find a glorious (or inglorious) death long before that point."},{"type":"item","name":"Alignment.","entry":"Most aven lean toward some form of neutrality. Ibis-headed aven, focused more on knowledge than any other virtue, are usually neutral. Hawk-headed aven are inclined toward lawful neutral."},{"type":"item","name":"Size.","entry":"Aven stand from 5 to 6 feet tall, but their bodies are slender and their bones are partially hollow to facilitate their flight. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet. You have a flying speed of 30 feet. You can’t use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can’t use your flying speed if you are encumbered.)"},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Aven."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aven Hawk Headed","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Hawkeyed"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2."},{"type":"item","name":"Hawkeyed.","entry":"You have proficiency in the Perception skill. In addition, attacking at long range doesn’t impose disadvantage on your ranged weapon attack rolls."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aven Ibis Headed","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Kefnet's Blessing"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Kefnet's Blessing.","entry":"You can add half your proficiency bonus, rounded down, to any Intelligence check you make that doesn’t already include your proficiency bonus."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Bugbear (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fey Ancestry","Long-Limbed","Powerful Build","Sneaky","Surprise Attack","Languages"],"entries":[{"type":"text","content":"<i>**//Neither bugs nor bears, bugbears are the hulking cousins of goblins and hobgoblins. With roots in the Feywild, early bugbears resided in hidden places, in hard-to-reach and shadowed spaces. Long ago and from out of the corner of your eye, they came to the Material Plane, urged to spread throughout the multiverse by the conquering god Maglubiyet. Centuries later, they still bear a fey gift for lurking just out of sight, and many of them have sneaked away from that god’s influence.//**</i> <i>**//They are long of limb and covered in coarse hair, with wedge-shaped ears and pointed teeth. Despite their formidable build, bugbears are quiet skulkers, thanks to a fey magic that allows them to hide in spaces seemingly too small for them.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."},{"type":"item","name":"Size.","entry":"Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Long-Limbed.","entry":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Sneaky.","entry":"You are proficient in the Stealth skill. In addition, without squeezing, you can move through and stop in a space large enough for a Small creature."},{"type":"item","name":"Surprise Attack.","entry":"If you hit a creature with an attack roll, the creature takes an extra 2d6 damage if it hasn’t taken a turn yet in the current combat."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Bugbear (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Long-Limbed","Powerful Build","Sneaky","Surprise Attack","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"Bugbears reach adulthood at age 16 and live up to 80 years."},{"type":"item","name":"Alignment.","entry":"Bugbears endure a harsh existence that demands each of them to remain self-sufficient, even at the expense of their fellows. They tend to be chaotic evil."},{"type":"item","name":"Size.","entry":"Bugbears are between 6 and 8 feet tall and weigh between 250 and 350 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Long-Limbed.","entry":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Sneaky.","entry":"You are proficient in the Stealth skill."},{"type":"item","name":"Surprise Attack.","entry":"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra 2d6 damage to it. You can use this trait only once per combat."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Centaur (GGR)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":40},"ability":[],"languages":[{"common":true},{"sylvan":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Fey","Charge","Hooves","Equine Build","Survivor","Languages"],"entries":[{"type":"text","content":"<i>**//Centaurs have the upper bodies, down to the waist, of muscular humans, displaying all the human variety of skin tones and features. Their ears are slightly pointed, but their faces are wider and squarer than those of elves. Below the waist, they have the bodies of small horses, with a similar range of coloration - from various s hades of chestnut or bay to dappled or even zebra like striped patterns. Most centaurs style their hair and their tails in a similar way. Selesnya centaurs favor long, flowing hair. Gruul centaurs cut their hair in rough. spiky styles.//**</i> <i>**//The upper bodies of centaurs are comparable to human torsos in size, and their lower equine bodies average about 4 feet tall al the withers. Though they are smaller than a human rider mounted on a horse, they fill similar roles as cavalry warriors. messengers, outriders, and scouts.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Wisdom score\\tincreases by 1."},{"type":"item","name":"Age.","entry":"Centaurs mature and age at about the same rate as humans."},{"type":"item","name":"Alignment.","entry":"Centaurs are inclined toward neutrality. Those who join the Selesnya are more often neutral good, while those who join the Gruul are typically chaotic neutral."},{"type":"item","name":"Size.","entry":"Centaurs stand between 6 and 7 feet tall, with their equine bodies reaching about 4 feet at the withers. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 40 feet."},{"type":"item","name":"Fey.","entry":"Your creature type is fey, rather than humanoid."},{"type":"item","name":"Charge.","entry":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"type":"item","name":"Hooves.","entry":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Equine Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push or drag. In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."},{"type":"item","name":"Survivor.","entry":"You have proficiency in one of the following skills: Animal Handling, Medicine, Nature, or Survival."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Sylvan. Sylvan is widely spoken in the Selesnya Conclave, for it is rich in vocabulary to describe natural phenomena and spiritual forces."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Centaur (MOT)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":40},"ability":[],"languages":[{"common":true},{"sylvan":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Fey","Charge","Hooves","Equine Build","Survivor","Languages"],"entries":[{"type":"text","content":"<i>**//Though centaurs share the same basic physiology, the centaur bands are commonly associated with their own distinct traits.//**</i> <i>**//Lagonna band centaurs tend to be sleek and muscular, with powerful legs built for endurance rather than speed. They usually have coats of a single color, often with a shine that can look metallic in bright light.//**</i> <i>**//Pheres band centaurs typically have long, nimble legs and lean bodies, and are often marked with natural color patterns on their hide. Pheres centaurs sometimes paint or tattoo their upper bodies to match the patterns on their lower half. Occasionally, a Pheres centaur is born with vertical stripes on their hooves, foretelling an exciting and adventurous life.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Wisdom score\\tincreases by 1."},{"type":"item","name":"Age.","entry":"Centaurs mature and age at about the same rate as humans."},{"type":"item","name":"Alignment.","entry":"Centaurs are inclined toward neutrality. Lagonna centaurs tend to be more lawful, while Pheres centaurs are more often chaotic."},{"type":"item","name":"Size.","entry":"Centaurs stand between 6 and 7 feet tall, with their equine bodies reaching about 4 feet at the withers. Pheres centaurs tend to be slightly larger than Lagonna centaurs. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 40 feet."},{"type":"item","name":"Fey.","entry":"Your creature type is fey, rather than humanoid."},{"type":"item","name":"Charge.","entry":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"type":"item","name":"Hooves.","entry":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Equine Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push or drag. In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."},{"type":"item","name":"Survivor.","entry":"You have proficiency in one of the following skills: Animal Handling, Medicine, Nature, or Survival."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Sylvan."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Centaur (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":40},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Charge","Equine Build","Hooves","Natural Affinity","Languages"],"entries":[{"type":"text","content":"<i>**//Centaurs gallop throughout the multiverse and trace their origins to many different realms. The centaurs presented here hail from the Feywild and mystically resonate with the natural world. From the waist up, they resemble elves, displaying all the elf varieties of skin tone. From the waist down, they have the bodies of horses.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 40 feet."},{"type":"item","name":"Charge.","entry":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"type":"item","name":"Equine Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push or drag. * In addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet instead of the normal 1 extra foot."},{"type":"item","name":"Hooves.","entry":"You have hooves that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Natural Affinity.","entry":"Your fey connection to nature gives you an intuitive connection to the natural world and the animals within it. You therefore have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Changeling (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Changeling Instincts","Shapechanger","Languages"],"entries":[{"type":"text","content":"<i>**//With ever-changing appearances, changelings reside in many societies undetected. Each changeling can supernaturally adopt any face they like. For some changelings, a new face is only a disguise. For other changelings, a new face may reveal an aspect of their soul.//**</i> <i>**//The first changelings in the multiverse appeared in the Feywild, and the wondrous, mutable essence of that plane lingers in changelings today — even in those changelings who have never set foot in the fey realm. Each changeling decides how to use their shape-shifting ability, channeling either the peril or the joy of the Feywild. Sometimes they adopt new forms for the sake of mischief or malice, and other times they don a new identity to right wrongs or delight the downtrodden.//**</i> <i>**//In their true form, changelings appear faded, their features almost devoid of detail. It is rare to see a changeling in that form, for a typical changeling changes their shape the way others might change clothes. A casual shape — one created on the spur of the moment, with no depth or history — is called a mask. A mask can be used to express a mood or to serve a specific purpose and then might never be used again. However, many changelings develop identities that have more depth, crafting whole personas complete with histories and beliefs. A changeling adventurer might have personas for many situations, including negotiation, investigation, and combat.//**</i> <i>**//Personas can be shared by multiple changelings; a community might be home to three healer changelings, with whoever is on duty adopting the persona of Andrea, the gentle physician. Personas can even be passed down through a family, allowing a younger changeling to take advantage of contacts established by the persona’s previous users.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Changeling Instincts.","entry":"Thanks to your connection to the fey realm, you gain proficiency with two of the following skills of your choice: Deception, Insight, Intimidation, Performance, or Persuasion."},{"type":"item","name":"Shapechanger.","entry":"As an action, you can change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight and can change your size between Medium and Small. You can make yourself appear as a member of another race, though none of your game statistics change. You can’t duplicate the appearance of an individual you’ve never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren’t changed by this trait. * You stay in the new form until you use an action to revert to your true form or until you die."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Changeling (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Change Appearance","Unsettling Visage","Divergent Persona","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and either your Dexterity or your Intelligence increases by 1 (your choice)."},{"type":"item","name":"Age.","entry":"Changelings mature slightly faster than humans but share a similar lifespan — typically a century or less. While a changeling can transform to conceal their age, the effects of aging affect them similarly to humans."},{"type":"item","name":"Alignment.","entry":"Changelings hate to be bound in any way, and those who follow the path of the Traveler believe that chaos and change are important aspects of life. Most tend toward pragmatic neutrality as opposed to being concerned with lofty ideals. Few changelings embrace evil."},{"type":"item","name":"Size.","entry":"In their natural forms, changelings average between 5 and 6 feet in height, with a slender build. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Change Appearance.","entry":"As an action, you can transform your appearance or revert to your natural form. You can’t duplicate the appearance of a creature you’ve never seen, and you revert to your natural form if you die. * You decide what you look like, including your height, weight, facial features, the sound of your voice, coloration, hair length, sex, and any other distinguishing characteristics. You can make yourself appear as a member of another race, though none of your game statistics change. You also can’t appear as a creature of a different size than you, and your basic shape stays the same; if you’re bipedal, you can’t use this trait to become quadrupedal, for instance. Your clothing and other equipment don’t change in appearance, size, or shape to match your new form, requiring you to keep a few extra outfits on hand to make the most compelling disguise possible. * Even to the most astute observers, your ruse is usually indiscernible. If you rouse suspicion, or if a wary creature suspects something is amiss, you have advantage on any Charisma (Deception) check you make to avoid detection."},{"type":"item","name":"Unsettling Visage.","entry":"When a creature you can see makes an attack roll against you, you can use your reaction to impose disadvantage on the roll. You must use this feature before knowing whether the attack hits or misses. Using this trait reveals your shapeshifting nature to any creature within 30 feet that can see you. Once you use this trait, you can’t use it again until you finish a short or long rest."},{"type":"item","name":"Divergent Persona.","entry":"You gain proficiency with one tool of your choice. Define a unique identity associated with that proficiency; establish the name, race, gender, age, and other details. While you are in the form of this persona, the related proficiency bonus is doubled for any ability check you make that uses that proficiency."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and two other languages of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Deep Gnome (EEPC)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"gnomish":true}],"traits":["Ability Score Increase","Age","Size","Speed","Superior Darkvision","Gnome Cunning","Stone Camouflage","Languages"],"entries":[{"type":"text","content":"<i>**//Forest gnomes and rock gnomes are the gnomes most commonly encountered in the lands of the surface world. There is another subrace of gnomes rarely seen by any surface-dweller: deep gnomes, also known as svirfneblin. Guarded, and suspicious of outsiders, svirfneblin are cunning and taciturn, but can be just as kind-hearted, loyal, and compassionate as their surface cousins.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2, and your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"Gnomes mature at the same rate as humans, and most are expected to settle into adult life around the age of 40. They can live to 350 years on average, but it's not too uncommon for them to reach 500 years of age."},{"type":"item","name":"Size.","entry":"Gnomes are between 3 and 4 feet tall and weigh around 40 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet."},{"type":"item","name":"Superior Darkvision.","entry":"Your darkvision has a radius of 120 feet."},{"type":"item","name":"Gnome Cunning.","entry":"You have advantage on all Intelligence, Wisdom, and Charisma saves against magic."},{"type":"item","name":"Stone Camouflage.","entry":"You have advantage on Dexterity (stealth) checks to hide in rocky terrain."},{"type":"item","name":"Languages.","entry":"You can read, speak, and write Common and Gnomish."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Deep Gnome (MPMM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Gift of the Svirfneblin","Gnomish Magic Resistance","Svirfneblin Camouflage","Languages"],"entries":[{"type":"text","content":"<i>**//Deep gnomes, or svirfneblin, are natives of the Underdark and are suffused with that subterranean realm’s magic. They can supernaturally camouflage themselves, and their svirfneblin magic renders them difficult to locate. These abilities have enabled them to survive for generations among the perils of the Underdark.//**</i> <i>**//Like other gnomes, deep gnomes can live for centuries, up to 500 years.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered a gnome for any prerequisite or effect that requires you to be a gnome."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Gift of the Svirfneblin.","entry":"Starting at 3rd level, you can cast the Disguise Self spell with this trait. Starting at 5th level, you can also cast the Nondetection spell with it, without requiring a material component. Once you cast either of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Gnomish Magic Resistance.","entry":"You have advantage on Intelligence, Wisdom, and Charisma saving throws against spells."},{"type":"item","name":"Svirfneblin Camouflage.","entry":"When you make a Dexterity (Stealth) check, you can make the check with advantage. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dhakanni Ghaaldar, Guide (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Lead By Example","The Guiding Arts"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Either your Intelligence or Charisma score increases by 1 (your choice)"},{"type":"item","name":"Lead By Example.","entry":"If you fail an ability check or saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (Maximum bonus of +5). Once you use this trait, you cannot do so again until you finish a short or long rest."},{"type":"item","name":"The Guiding Arts.","entry":"You have proficiency in two of the following skills of your choice: History, Intimidation, Perception or Survival."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dhakanni Ghaaldar, Soldier (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Strength in Unity","The Arts of War"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Either your Dexterity or Strength score increases by 1 (your choice)"},{"type":"item","name":"Strength in Unity.","entry":"If you miss with an attack roll or fail a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (Maximum bonus of +5). Once you use this trait, you cannot do so again until you finish a short or long rest."},{"type":"item","name":"The Arts of War.","entry":"You have proficiency in two of the following skills of your choice: Athletics, Intimidation, Perception or Survival."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dhakanni Ghaal'dar Hobgoblins (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Speed","Darkvision","Discipline","Languages","Subrace"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution increases by 2."},{"type":"item","name":"Age.","entry":"Ghaal'dar age at the same rate as humans and have lifespans similar to theirs."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Discipline.","entry":"You have advantage on saving throws against being charmed."},{"type":"item","name":"Languages.","entry":"You can speak, read and write Common and Goblin."},{"type":"item","name":"Subrace.","entry":"Within the Dhrakanni caste system, young ghaal'dar are trained to fulfill one of two roles. Guides are diplomats and scholars, while soldiers are devoted to war. Choose a subrace for your ghaal'dar character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dhampir (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":35},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Darkvision","Spider Climb","Vampiric Bite","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Type.","entry":"Humanoid and Undead"},{"type":"item","name":"Size.","entry":"Medium or Small (choose when you gain this lineage)"},{"type":"item","name":"Speed.","entry":"35 feet"},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light."},{"type":"item","name":"Spider Climb.","entry":"You have a climbing speed equal to your walking speed. In addition, at 3rd level, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free."},{"type":"item","name":"Vampiric Bite.","entry":"Your fanged bite is a natural weapon, which counts as a simple melee weapon with which you are proficient. You add your Constitution modifier to the attack and damage rolls when you attack with your bite. Your bite deals 1d4 piercing damage on a hit. While you are missing half or more of your hit points, you have advantage on attack rolls you make with this bite. When you use your bite and hit a creature that isn’t a Construct or an Undead, you can empower yourself in one of the following ways of your choice: * regain hit points equal to the damage dealt by the bite * gain a bonus to the next ability check or attack roll you make; the bonus equals the damage dealt by the bite * You can empower yourself with your bite a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dhampir (VRGR)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":35},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Size","Speed","Ancestral Legacy","Darkvision","Deathless Nature","Spider Climb","Vampiric Bite"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or increase three different ability scores by 1. If you are replacing your race with this lineage, replace any Ability Score Increase you previously had with this."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. If you are replacing your race with this lineage, you retain any languages you had and gain no new languages."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this lineage."},{"type":"item","name":"Speed.","entry":"Your walking speed is 35 feet."},{"type":"item","name":"Ancestral Legacy.","entry":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. * If you don't keep any of those elements or you choose this lineage at character creation, you gain proficency in two skills of your choice."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."},{"type":"item","name":"Deathless Nature.","entry":"You don't need to breathe."},{"type":"item","name":"Spider Climb.","entry":"You have a climbing speed equal to your walking speed. In addition, at 3rd level, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free."},{"type":"item","name":"Vampiric Bite.","entry":"Your fanged bite is a natural weapon, which counts as a simple melee weapon with which you are proficient. You add your Constitution modifier, instead of your Strength modifier, to the attack and damage rolls when you attack with this bite. It deals 1d4 piercing damage on a hit. While you are missing half or more of your hit points, you have advantage on attack rolls you make with this bite. * When you attack with this bite and hit a creature that isn’t a Construct or an Undead, you can empower yourself in one of the following ways of your choice: * You regain hit points equal to the piercing damage dealt by the bite. * You gain a bonus to the next ability check or attack roll you make; the bonus equals the piercing damage dealt by the bite. * You can empower yourself with this bite a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Chromatic Dragonborn (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Chromatic Ancestry","Breath Weapon","Draconic Resistance","Chromatic Warding","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Chromatic Ancestry.","entry":"You trace your ancestry to a chromatic dragon, granting you a special magical affinity. Choose one type of dragon from the Chromatic Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Chromatic Ancestry |||| ||~ Dragon ||~ Damage Type || || Black || Acid || || Blue || Lightning || || Green || Poison || || Red || Fire || || White || Cold ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action, you can replace one of your attacks with an exhalation of a magical energy in a 30-foot line that is 5 feet wide. Each creature in the area must make a Dexterity saving throw against a DC equal to 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d8 damage of the type associated with your Chromatic Ancestry on a failed save, and half as much damage on a successful one. This damage increases by 1d8 when you reach 5th level (3d8), 11th level (4d8), and 17th level (5d8). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Chromatic Ancestry."},{"type":"item","name":"Chromatic Warding.","entry":"Starting at 3rd level, as an action, you can channel your draconic energies to protect yourself. For 10 minutes, you become immune to the damage type associated with your Chromatic Ancestry. Once you use this trait, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Chromatic Dragonborn (FTD)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Chromatic Ancestry","Breath Weapon","Draconic Resistance","Chromatic Warding","Languages"],"entries":[{"type":"text","content":"<i>**//Dragonborn with chromatic ancestry claim the raw elemental power of chromatic dragons. The vibrant colors of black, blue, green, red, and white dragons gleam in those dragonborn's scaled skin and in the deadly energy of their breath weapons. Theirs is the raw elemental fury of the volcano, of biting arctic winds, and of raging lightning storms, as well as the subtle whisper of swamp and forest, toxic and corrosive.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Chromatic Ancestry.","entry":"You trace your ancestry to a chromatic dragon, granting you a special magical affinity. Choose one type of dragon from the Chromatic Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Chromatic Ancestry |||| ||~ Dragon ||~ Damage Type || || Black || Acid || || Blue || Lightning || || Green || Poison || || Red || Fire || || White || Cold ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Chromatic Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Chromatic Ancestry."},{"type":"item","name":"Chromatic Warding.","entry":"Starting at 5th level, as an action, you can channel your draconic energy to protect yourself. For 1 minute, you become immune to the damage type associated with your Chromatic Ancestry. Once you use this trait, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Draconblood Dragonborn (EGW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Darkvision","Forceful Presence"],"entries":[{"type":"text","content":"<i>**//Draconbloods possess long tails and a knack for social manipulation. They remember the days when they were once mighty conquerors.//**</i> <i>**//A draconblood uses the dragonborn traits in the// Player's Handbook, //with the following traits replacing the// Ability Score Increase //and// Damage Resistance //traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2, and your Charisma score increases by 1."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Forceful Presence.","entry":"When you make a Intimidation or Persuasion check, you can do so with advantage once per long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Gem Dragonborn (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Gem Ancestry","Breath Weapon","Draconic Resistance","Psionic Mind","Gem Flight","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Gem Ancestry.","entry":"You trace your ancestry to a Gem dragon, granting you a special magical affinity. Choose one type of dragon from the Gem Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Gem Ancestry |||| ||~ Dragon ||~ Damage Type || || Amethyst || Force || || Crystal || Radiant || || Emerald || Psychic || || Sapphire || Thunder || || Topaz || Necrotic ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action, you can replace one of your attacks with an exhalation of a magical energy in a 15-foot line that is 5 feet wide. Each creature in the area must make a Dexterity saving throw against a DC equal to 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d8 damage of the type associated with your Gem Ancestry on a failed save, and half as much damage on a successful one. This damage increases by 1d8 when you reach 5th level (3d8), 11th level (4d8), and 17th level (5d8). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Gem Ancestry."},{"type":"item","name":"Psionic Mind.","entry":"You can telepathically speak to any creature you can see within 30 feet of you. You don’t need to share a language with the creature, but the creature must be able to understand at least one language. Your communication doesn’t give the creature the ability to respond to you telepathically."},{"type":"item","name":"Gem Flight.","entry":"Starting at 3rd level, you can use your bonus action to temporarily summon an array of spectral gems that match your Gem Ancestry in the shape of wings that last for 1 minute. For the duration, you gain a flying speed equal to your walking speed and can hover. Once you use this trait, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Gem Dragonborn (FTD)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Gem Ancestry","Breath Weapon","Draconic Resistance","Psionic Mind","Gem Flight","Languages"],"entries":[{"type":"text","content":"<i>**//Gem dragonborn partake of the heritage of gem dragons, who claim to be heirs of Sardior, the Ruby Dragon. The colors and mysterious powers of gem dragons — amethyst, crystal, emerald, sapphire, and topaz — gleam in these dragonborn’s scaled skin and course through their veins. Theirs are the wonders of the mind, the force of will, the brilliant light of insight, and the resounding echo of discovery — but also the desiccation of despair.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Gem Ancestry.","entry":"You trace your ancestry to a Gem dragon, granting you a special magical affinity. Choose one type of dragon from the Gem Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Gem Ancestry |||| ||~ Dragon ||~ Damage Type || || Amethyst || Force || || Crystal || Radiant || || Emerald || Psychic || || Sapphire || Thunder || || Topaz || Necrotic ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Gem Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Gem Ancestry."},{"type":"item","name":"Psionic Mind.","entry":"You can telepathically speak to any creature you can see within 30 feet of you. You don’t need to share a language with the creature, but the creature must be able to understand at least one language."},{"type":"item","name":"Gem Flight.","entry":"Starting at 5th level, you can use a bonus action to manifest spectral wings on your body. These wings last for 1 minute. For the duration, you gain a flying speed equal to your walking speed and can hover. Once you use this trait, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Metallic Dragonborn (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Metallic Ancestry","Breath Weapon","Draconic Resistance","Metallic Breath Weapon","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Metallic Ancestry.","entry":"You trace your ancestry to a metallic dragon, granting you a special magical affinity. Choose one type of dragon from the Metallic Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Metallic Ancestry |||| ||~ Dragon ||~ Damage Type || || Brass || Fire || || Bronze || Lightning || || Copper || Acid || || Gold || Fire || || Silver || Cold ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action, you can replace one of your attacks with an exhalation of a magical energy in a 15-foot line that is 5 feet wide. Each creature in the area must make a Dexterity saving throw against a DC equal to 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d8 damage of the type associated with your Metallic Ancestry on a failed save, and half as much damage on a successful one. This damage increases by 1d8 when you reach 5th level (3d8), 11th level (4d8), and 17th level (5d8). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Metallic Ancestry."},{"type":"item","name":"Metallic Breath Weapon.","entry":"At 3rd level you gain a second breath weapon. When you take the Attack action, you can replace one of your attacks with an exhalation of a magical gas in a 15-foot cone. The save DC for this breath is 8 + your Constitution modifier + your proficiency bonus. When you use this ability, choose one: * Each creature in the area must succeed on a Strength saving throw or be pushed 20 feet away from you and be knocked prone. * Each creature in the area must succeed on a Constitution saving throw or become incapacitated until the start of your next turn. * Once you use your Metallic Breath Weapon, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Metallic Dragonborn (FTD)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Metallic Ancestry","Breath Weapon","Draconic Resistance","Metallic Breath Weapon","Enervating Breath","Repulsion Breath","Languages"],"entries":[{"type":"text","content":"<i>**//Dragonborn with metallic ancestry lay claim to the tenacity of metallic dragons — brass, bronze, copper, gold, and silver — whose hues glint in their scales. Theirs is the fire of hearth and forge, the cold of high mountain air, the spark of inspiration, and the scouring touch of acid that purifies.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Metallic Ancestry.","entry":"You trace your ancestry to a metallic dragon, granting you a special magical affinity. Choose one type of dragon from the Metallic Ancestry table. This determines the damage type for your other traits as shown in the table. ||||~ Metallic Ancestry |||| ||~ Dragon ||~ Damage Type || || Brass || Fire || || Bronze || Lightning || || Copper || Acid || || Gold || Fire || || Silver || Cold ||"},{"type":"item","name":"Breath Weapon.","entry":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Metallic Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10). You can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Draconic Resistance.","entry":"You have resistance to the damage type associated with your Metallic Ancestry."},{"type":"item","name":"Metallic Breath Weapon.","entry":"At 5th level, you gain a second breath weapon. When you take the Attack action on your turn, you can replace one of your attacks with an exhalation in a 15-foot cone. The save DC for this breath is 8 + your Constitution modifier + your proficiency bonus. Whenever you use this trait, choose one:"},{"type":"item","name":"Enervating Breath.","entry":"Each creature in the cone must succeed on a Constitution saving throw or become incapacitated until the start of your next turn."},{"type":"item","name":"Repulsion Breath.","entry":"Each creature in the cone must succeed on a Strength saving throw or be pushed 20 feet away from you and be knocked prone. * Once you use your Metallic Breath Weapon, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dragonborn (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"draconic":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Draconic Ancestry","Breath Weapon","Damage Resistance","Languages"],"entries":[{"type":"text","content":"<i>**//Born of dragons, as their name proclaims, the dragonborn walk proudly through a world that greets them with fearful incomprehension. Shaped by draconic gods or the dragons themselves, dragonborn originally hatched from dragon eggs as a unique race, combining the best attributes of dragons and humanoids. Some dragonborn are faithful servants to true dragons, others form the ranks of soldiers in great wars, and still others find themselves adrift, with no clear calling in life.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Charisma score increases by 1."},{"type":"item","name":"Age.","entry":"Young dragonborn grow quickly. They walk hours after hatching, attain the size and development of a 10-year-old human child by the age of 3, and reach adulthood by 15. They live to be around 80."},{"type":"item","name":"Alignment.","entry":"Dragonborn tend towards extremes, making a conscious choice for one side or the other between Good and Evil (represented by Bahamut and Tiamat, respectively). More side with Bahamut than Tiamat (whose non-dragon followers are mostly kobolds), but villainous dragonborn can be quite terrible indeed. Some rare few choose to devote themselves to lesser dragon deities, such as Chronepsis (Neutral), and fewer still choose to worship Io, the Ninefold Dragon, who is all alignments at once."},{"type":"item","name":"Size.","entry":"Dragonborn are taller and heavier than humans, standing well over 6 feet tall and averaging almost 250 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Draconic Ancestry.","entry":"You are distantly related to a particular kind of dragon. Choose a type of dragon from the below list; this determines the damage and area of your breath weapon, and the type of resistance you gain. ||~ Dragon Color ||~ Damage Type ||~ Breath Weapon || || Black || Acid || 5 by 30 ft. line (DEX save) || || Blue || Lightning || 5 by 30 ft. line (DEX save) || || Brass || Fire || 5 by 30 ft. line (DEX save) || || Bronze || Lightning || 5 by 30 ft. line (DEX save) || || Copper || Acid || 5 by 30 ft. line (DEX save) || || Gold || Fire || 15 ft. cone (DEX save) || || Green || Poison || 15 ft. cone (CON save) || || Red || Fire || 15 ft. cone (DEX save) || || Silver || Cold || 15 ft. cone (CON save) || || White || Cold || 15 ft. cone (CON save) ||"},{"type":"item","name":"Breath Weapon.","entry":"You can use your action to exhale destructive energy. It deals damage in an area according to your ancestry. When you use your breath weapon, all creatures in the area must make a saving throw, the type of which is determined by your ancestry. The DC of this saving throw is 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d6 damage on a failed save, and half as much damage on a successful one. The damage increase to 3d6 at 6th level, 4d6 at 11th, and 5d6 at 16th level. After using your breath weapon, you cannot use it again until you complete a short or long rest."},{"type":"item","name":"Damage Resistance.","entry":"You have resistance to the damage type associated with your ancestry."},{"type":"item","name":"Languages.","entry":"You can read, speak, and write Common and Draconic."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dragonborn Ravenite","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Darkvision","Vengeful Assault"],"entries":[{"type":"text","content":"<i>**//Ravenites have no tails and a hearty physique. They remember the days when they were slaves to the draconblood, as well as the day when they overthrew their masters.//**</i> <i>**//A ravenite uses the dragonborn traits in the// Player's Handbook, //with the following traits replacing the// Ability Score Increase //and// Damage Resistance //traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Vengeful Assault.","entry":"When you take damage from a creature in range of a weapon you are wielding, you can use your reaction to make an attack against that creature. You can do this once per short or long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Duergar (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Duergar Magic","Dwarven Resilience","Psionic Fortitude","Languages"],"entries":[{"type":"text","content":"<i>**//Duergar are dwarves whose ancestors were transformed by centuries living in the deepest places of the Underdark. That chthonic realm is saturated with strange magical energy, and over generations, early duergar absorbed traces of it. They were further altered when mind flayers and other Aberrations invaded and performed horrific experiments on them. Fueled by Underdark magic, those experiments left early duergar with psionic powers, which have been passed down to their descendants. In time, they liberated themselves from their aberrant tyrants and forged a new life for themselves in the Underdark and beyond.//**</i> <i>**//Like other dwarves, duergar typically have a life span of 350 years.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered a dwarf for any prerequisite or effect that requires you to be a dwarf."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Duergar Magic.","entry":"Starting at 3rd level, you can cast the Enlarge/Reduce spell on yourself with this trait, without requiring a material component. Starting at 5th level, you can also cast the Invisibility spell on yourself with this trait, without requiring a material component. Once you cast either of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Dwarven Resilience.","entry":"You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."},{"type":"item","name":"Psionic Fortitude.","entry":"You have advantage on saving throws you make to avoid or end the charmed or stunned condition on yourself."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Duergar (SCAG)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"dwarvish":true}],"traits":["Ability Score Increase","Age","Size","Speed","Superior Darkvision","Dwarven Resilience","Duergar Resilience","Dwarven Combat Training","Tool Proficiency","Stonecunning","Duergar Magic","Sunlight Sensitivity","Languages"],"entries":[{"type":"text","content":"<i>**//The gray dwarves, or duergar, live deep in the Underdark. After delving deeper than any other dwarves, they were enslaved by mind flayers for eons. Although they eventually won their freedom, these grim, ashen-skinned dwarves now take slaves of their own and are as tyrannical as their former masters.//**</i> <i>**//Physically similar to other dwarves in some ways, duergar are wiry and lean, with black eyes and bald heads, with the males growing long, unkempt, gray beards.//**</i> <i>**//Duergar value toil above all else. Showing emotions other than grim determination or wrath is frowned on in their culture, but they can sometimes seem joyful when at work. They have the typical dwarven appreciation for order, tradition, and impeccable craftsmanship, but their goods are purely utilitarian, disdaining aesthetic or artistic value.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Strength score increases by 1."},{"type":"item","name":"Age.","entry":"Dwarves mature at the same rate as humans, but they're considered young until they reach the age of 50. On average, they live about 350 years."},{"type":"item","name":"Size.","entry":"Dwarves stand between 4 and 5 feet tall and average about 150 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet. Your speed is not reduced by wearing heavy armor."},{"type":"item","name":"Superior Darkvision.","entry":"You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Dwarven Resilience.","entry":"You have advantage on saving throws against poison, and you have resistance against poison damage."},{"type":"item","name":"Duergar Resilience.","entry":"You have advantage on saving throws against illusions and against being charmed or paralyzed."},{"type":"item","name":"Dwarven Combat Training.","entry":"You have proficiency with the battleaxe, handaxe, light hammer, and warhammer."},{"type":"item","name":"Tool Proficiency.","entry":"You gain proficiency with the artisan's tools of your choice: smith's tools, brewer's supplies, or mason's tools."},{"type":"item","name":"Stonecunning.","entry":"Whenever you make an Intelligence (History) check related to the origin of stonework, you are considered proficient in the History skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."},{"type":"item","name":"Duergar Magic.","entry":"When you reach 3rd level, you can cast the Enlarge/Reduce spell on yourself once with this trait, using only the spell's enlarge option. When you reach 5th level, you can cast the Invisibility spell on yourself once with this trait. You don't need material components for either spell, and you can't cast them while you're in direct sunlight, although sunlight has no effect on them once cast. You regain the ability to cast these spells with this trait when you finish a long rest. Intelligence is your spellcasting ability for these spells."},{"type":"item","name":"Sunlight Sensitivity.","entry":"You have disadvantage on Attack rolls and Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Dwarvish. Dwarvish is full of hard consonants and guttural sounds, and those characteristics spill over into whatever other language a dwarf might speak."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hill Dwarf (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Dwarven Toughness"],"entries":[{"type":"text","content":"<i>**//As a hill dwarf, you have keen senses, deep intuition, and remarkable resilience. The gold dwarves of Faerun in their mighty southern kingdom are hill dwarves, as are the exiled Neidar and the debased Klar of Krynn in the Dragonlance setting.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Dwarven Toughness.","entry":"Your hit point maximum increases by 1, and it increases by 1 every time you gain a level."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dwarf Mark Of Warding (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Warder's Intuition","Wards and Seals","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If you're a dwarf with the Mark of Warding, you have this subrace, with the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1"},{"type":"item","name":"Warder's Intuition.","entry":"Whenever you make an Intelligence (Investigation) check or an Ability Check involving Thieves' Tools, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Wards and Seals.","entry":"You can cast the Alarm and Mage Armor spells with this trait. Starting at 3rd level, you can also cast the Arcane Lock spell with it. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Intelligence is your Spellcasting Ability for these spells, and you don't require material components when you cast them with this trait."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Warding Spells table are added to the spell list of your Spellcasting class. <b>Mark of Warding Spells</b> ||~ Spell Level ||~ Spell || || 1st || Alarm, Armor of Agathys || || 2nd || Arcane Lock, Knock || || 3rd || Glyph of Warding, Magic Circle || || 4th || Leomund's Secret Chest, Mordenkainen's Faithful Hound || || 5th || Antilife Shell ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Mountain Dwarf (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Dwarven Armor Training"],"entries":[{"type":"text","content":"<i>**//As a mountain dwarf, you're strong and hardy, accustomed to a difficult life in rugged terrain. You're probably on the tall side (for a dwarf), and tend toward lighter coloration, The shield dwarves of northern Faerun, as well as the ruling Hylar clan and the noble Daewar clan of Dragonlance, are mountain dwarves.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2."},{"type":"item","name":"Dwarven Armor Training.","entry":"You have proficiency with light and medium armor."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dwarf (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"dwarvish":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Dwarven Resilience","Dwarven Combat Training","Tool Proficiency","Stonecunning","Languages"],"entries":[{"type":"text","content":"<i>**//Kingdoms rich in ancient grandeur, halls carved into the roots of mountains, the echoing of picks and hammers in deep mines and blazing forges, a commitment to clan and tradition, and a burning hatred of goblins and orcs –\xA0these common threads unite all dwarves.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2."},{"type":"item","name":"Age.","entry":"Dwarves mature at the same rate as humans, but they're considered young until they reach the age of 50. On average, they live about 350 years."},{"type":"item","name":"Alignment.","entry":"Most dwarves are lawful, believing firmly in the benefits of a well-ordered society. They tend toward good as well, with a strong sense of fair play and a belief that everyone deserves to share in the benefits of a just order."},{"type":"item","name":"Size.","entry":"Dwarves stand between 4 and 5 feet tall and average about 150 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet. Your speed is not reduced by wearing heavy armor."},{"type":"item","name":"Darkvision.","entry":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Dwarven Resilience.","entry":"You have advantage on saving throws against poison, and you have resistance against poison damage."},{"type":"item","name":"Dwarven Combat Training.","entry":"You have proficiency with the battleaxe, handaxe, light hammer, and warhammer."},{"type":"item","name":"Tool Proficiency.","entry":"You gain proficiency with the artisan's tools of your choice: smith's tools, brewer's supplies, or mason's tools."},{"type":"item","name":"Stonecunning.","entry":"Whenever you make an Intelligence (History) check related to the origin of stonework, you are considered proficient in the History skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Dwarvish. Dwarvish is full of hard consonants and guttural sounds, and those characteristics spill over into whatever other language a dwarf might speak."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Ruinbound Dwarf (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Personal Symbiont","Symbiont Mastery"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1. While your symbiont is physically disturbing, you have a strong personality and a mysterious charm."},{"type":"item","name":"Personal Symbiont.","entry":"You are bound to an alien entity. It's part of your body and can't be removed. Your symbiont possesses a minor supernatural ability, which it can use on your behalf. * Choose a cantrip from the following list: Acid Splash, Guidance (self only), Infestation, Light, Mage Hand, Poison Spray, Ray of Frost. As long as your personal symbiont is fully exposed, you can cast that cantrip. You can choose to conceal the symbiont, but you can only cast the cantrip you gain with this trait while it's exposed. * When you finish a long rest, you can mutate the symbiont, gaining different benefits when you do so, you can select a different cantrip from this list. Charisma is your spellcasting ability for this cantrip. * Work with your DM to determine the appearance of your symbiont. It is organic and clearly alien, and when you cast a cantrip with this trait, it should be obvious that the symbiont is the source. A symbiont that casts Mage Hand could be a thin tentacle or an ectoplasmic insect that emerges from your body and performs the action. An eyestalk protruding from your shoulder could grant you Guidance as it studies the situation and telepathically advises you - or it might blast your enemies with a Ray of Frost. Infestation Could reflect a cloud of insects always hovering around you."},{"type":"item","name":"Symbiont Mastery.","entry":"You can attune to one magic item that has the Symbiotic Nature property without using an attunement slot. In addition, after you finish a long rest, you can end your attunement to a magic item that has the Symbiotic Nature property."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Eladrin (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fey Ancestry","Fey Step","Autumn","Winter","Spring","Summer","Keen Senses","Trance","Languages"],"entries":[{"type":"text","content":"<i>**//Eladrin are elves of the Feywild, a realm of perilous beauty and boundless magic. Using that magic, eladrin can step from one place to another in the blink of an eye, and each eladrin resonates with emotions captured in the Feywild in the form of seasons — affinities that affect the eladrin’s mood and appearance. An eladrin’s season can change, though some remain in one season forever. Choose your season or roll on the Eladrin Seasons table. Your Trance trait lets you change your season.//**</i> <i>**//Like other elves, eladrin can live to be over 750 years old.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Fey Step.","entry":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. * When you reach 3rd level, your Fey Step gains an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race):"},{"type":"item","name":"Autumn.","entry":"Immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute, or until you or your companions deal any damage to the creatures."},{"type":"item","name":"Winter.","entry":"When you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn."},{"type":"item","name":"Spring.","entry":"When you use your Fey Step, you can touch one willing creature within 5 feet of you. That creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you."},{"type":"item","name":"Summer.","entry":"Immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your proficiency bonus."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Trance.","entry":"You don’t need to sleep, and magic can’t put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. * Whenever you finish this trance, you can change your season, and you can gain two proficiencies that you don’t have, each one with a weapon or a tool of your choice selected from the <i>Player’s Handbook</i>. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Eladrin (MTF)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Autumn","Winter","Spring","Summer","Ability Score Increase","Age","Size","Speed","Darkvision","Fey Ancestry","Trance","Keen Senses","Fey Step","Autumn","Winter","Spring","Summer","Languages"],"entries":[{"type":"text","content":"<i>**//Eladrin are elves native to the Feywild, a realm of beauty, unpredictable emotion, and boundless magic. An eladrin is associated with one of the four seasons and has coloration reminiscent of that season, which can also affect the eladrin's mood://**</i> <i>**//Some eladrin remain associated with a particular season for their entire lives, whereas other eladrin transform, adopting characteristics of a new season.//**</i> <i>**//When finishing a long rest, any eladrin can change their season. An eladrin might choose the season that is present in the world or perhaps the season that most closely matches the eladrin's current emotional state. For example, an eladrin might shift to autumn if filled with contentment, another eladrin could change to winter if plunged into sorrow, still another might be bursting with joy and become an eladrin of spring, and fury might cause an eladrin to change to summer.//**</i> <i>**//The following tables offer personality suggestions for eladrin of each season. You can roll on the tables or use them as inspiration for characteristics of your own.//**</i>"},{"type":"list","items":[{"type":"item","name":"Autumn.","entry":"is the season of peace and goodwill, when summer's harvest is shared with all."},{"type":"item","name":"Winter.","entry":"is the season of contemplation and dolor, when the vibrant energy of the world slumbers."},{"type":"item","name":"Spring.","entry":"is the season of cheerfulness and celebration, marked by merriment as winter's sorrow passes."},{"type":"item","name":"Summer.","entry":"is the season of boldness and aggression, a time of unfettered energy. ||||~ Autumn || ||~ d4 ||~ Autumn Personality Trait || || 1 || If someone is in need, you never withhold aid. || || 2 || You share what you have, with little regard to your own needs. || || 3 || There are no simple meals, only lavish feasts. || || 4 || You stock up on fine food and drink. You hate going without such comforts. || ||~ d4 ||~ Autumn Flaw || || 1 || You trust others without thought. || || 2 || You give to the point that you leave yourself without necessary supplies. || || 3 || Everyone is your friend, or a potential friend. || || 4 || You spend excessively on creature comforts. || ||||~ Winter || ||~ d4 ||~ Winter Personality Trait|| || 1 || The worst case is most likely to occur. || || 2 || You preserve what you have. Better to be hungry today and have food for tomorrow. || || 3 || Life is full of dangers, but you are ready for them. || || 4 || A penny spent is a penny lost forever. || ||~ d4 ||~ Winter Flaw || || 1 || Everything dies eventually. Why bother building anything that is supposedly meant to last? || || 2 || Nothing matters to you, and you allow others to guide your actions. || || 3 || Your needs come first. In winter, all must watch out for themselves. || || 4 || You speak only to point out the flaws in others’ plans. || ||||~ Spring |||| ||~ d4 ||~ Spring Personality Trait || || 1\xA0|| Every day is the greatest day of your life. || || 2 || You do everything with enthusiasm, even the most mundane chores. || || 3 || You love music and song. You supply a tune yourself if no one else can. || || 4 || You can’t stay still. || ||~ d4 ||~ Spring Flaw || || 1 || You overdrink. || || 2 || Toil is for drudges. Yours should be a life of leisure. || || 3 || A pretty face infatuates you in an instant, but your fancy passes with equal speed. || || 4 || Anything worth doing is worth doing again and again. || ||||~ Summer |||| ||~ d4 ||~ Summer Personality Trait || || 1 || You believe that direct confrontation is the best way to solve problems. || || 2 || Overwhelming force can solve almost anything. The tougher the problem, the more force you apply. || || 3 || You stand tall and strong so that others can lean on you. || || 4 || You maintain an intimidating front. Better to prevent fights with a show of force than to harm others. || ||~ d4 ||~ Summer Flaw || || 1 || You are stubborn. Let others change. || || 2 || The best option is one that is swift, unexpected, and overwhelming. || || 3\xA0|| Punch first. Talk later. || || 4 || Your fury can carry you through anything. ||"},{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Charisma score increases by 1."},{"type":"item","name":"Age.","entry":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."},{"type":"item","name":"Size.","entry":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"Elves do not sleep. Instead they meditate deeply, remaining semi-conscious, for 4 hours a day. The Common word for this meditation is \\"trance.\\" While meditating, you dream after a fashion; such dreams are actually mental exercises that have become reflexive after years of practice. After resting in this way, you gain the same benefit a human would from 8 hours of sleep."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Fey Step.","entry":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. Once you use this trait, you can't do so again until you finish a short or long rest. When you reach 3rd level, your Fey Step gains an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Charisma modifier. The effects are as follows:"},{"type":"item","name":"Autumn.","entry":"Immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute, or until you or your companions deal any damage to it."},{"type":"item","name":"Winter.","entry":"When you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn."},{"type":"item","name":"Spring.","entry":"When you use your Fey Step, you can touch one willing creature within 5 feet of you. That creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you."},{"type":"item","name":"Summer.","entry":"Immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your Charisma modifier (minimum of 1 damage)."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Elven."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Aereni Elf (Homebrew)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Aereni Expertise","Cantrip"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase either your Intelligence or Wisdom score by 1."},{"type":"item","name":"Aereni Expertise.","entry":"Choose one skill or tool proficiency granted by your race, class or background. Your proficiency bonus is doubled for any ability check you make using this chosen proficiency."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the cleric or wizard spell list. Your spellcasting ability depends on the class you chose: Wisdom for cleric or Intelligence for wizard."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Avariel Elf (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"auran":true}],"traits":["Flight","Languages"],"entries":[{"type":"text","content":"<i>**//The avariel are winged elves. These rare creatures were more common when the worlds of the multiverse were young, but frequent conflicts with dragons much reduced the winged elves’ number. Still, a few colonies persist here and there in the Material Plane and on the Plane of Air.//**</i>"},{"type":"list","items":[{"type":"item","name":"Flight.","entry":"You have a flying speed of 30 feet. To use this speed, you can't be wearing medium or heavy armor."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Auran."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Bishtahar/Tirahar Elf (Kaladesh)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Elf Weapon Training","Fleet of Foot","Mask of the Wild"],"entries":[{"type":"text","content":"<i>**//Elves who dwell in the forest and countryside are known as the Bishtahar. Most live in isolated communities away from other races, though they still trade with them. In fact, much of Kaladesh’s food supply is grown by elves. Bishtahar cultivators grow food, decorative flowers, wood for building, and elaborate living sculptures in their meandering gardens and fields. They use the plane’s ubiquitous technology to foster the growth of plants and animals, utilizing automatons as gardeners and herders, and employing elaborate, nearly invisible systems controlling heat, water, and nutrients.//**</i> <i>**//Elves who forsake technology entirely are called the Tirahar. Some elves with Tirahar sympathies live within cities or farms, but most simply withdraw to the wilder areas of Kaladesh. No more than one in a hundred elves is counted among the Tirahar, and many members of other races are unaware that these reclusive elves even exist.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"type":"item","name":"Fleet of Foot.","entry":"Your base walking speed increases to 35 feet."},{"type":"item","name":"Mask of the Wild.","entry":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dark Elf/Drow (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Superior Darkvision","Sunlight Sensitivity","Drow Magic","Drow Weapon Training"],"entries":[{"type":"text","content":"<i>**//Descended from an earlier subrace of dark-skinned elves, the drow were banished from the surface world for following the goddess Lolth down the path to evil and corruption. Now they have built their own civilization in the depths of the Underdark, patterned after the Way of Lolth. Also called dark elves. The drow have black skin that resembles polished obsidian and stark white or pale yellow hair. They commonly have very pale eyes (so pale as to be mistaken for white) in shades of lilac, silver, pink, red, and blue. They tend to be smaller and thinner than most elves.//**</i> <i>**//Drow adventurers are rare, and the race does not exist in all worlds. Check with your Dungeon Master to see if you can play a drow character.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Superior Darkvision.","entry":"Your darkvision has a range of 120 feet, instead of 60."},{"type":"item","name":"Sunlight Sensitivity.","entry":"You have disadvantage on attack rolls and Wisdom (Perception) checks that rely on sight when you, the target of the attack, or whatever you are trying to perceive is in direct sunlight."},{"type":"item","name":"Drow Magic.","entry":"You know the Dancing Lights cantrip. When you reach 3rd level, you can cast the Faerie Fire spell once with this trait and regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the Darkness spell once and regain the ability to do so when you finish a long rest. Charisma is your spellcasting ability for these spells."},{"type":"item","name":"Drow Weapon Training.","entry":"You have proficiency with rapiers, shortswords, and hand crossbows."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Grugach Elf (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"sylvan":true}],"traits":["Ability Score Increase","Grugach Weapon Training","Cantrip","Languages"],"entries":[{"type":"text","content":"<i>**//The grugach of the world of Greyhawk shun contact with other folk, preferring the solace of the deepest forests and the companionship of wild animals. Even other elves draw their suspicion.//**</i> <i>**//The grugach tend toward chaos and neutrality. They feel no special duty to anyone beyond their own folk and the forest that is their home. Troubles beyond their borders are best kept there. At the same time, they harbor little ambition beyond a peaceful coexistence with nature.//**</i> <i>**//If anyone is fool enough to disturb a grugach realm, these elves take to arms and fight in earnest. Grugach master the basic weapons needed to hunt and forage in the wood. Every copse of trees becomes a sniper's nest, and each forest meadow is an ambush point. The grugach set pits filled with stakes, snares that leave an intruder helpless to grugach arrows, and other snares designed to kill rather than capture. The grugach fight to the death to preserve their realms.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 1."},{"type":"item","name":"Grugach Weapon Training.","entry":"You have proficiency with the spear, shortbow, longbow, and net."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Druid spell list. Wisdom is your spellcasting ability for it."},{"type":"item","name":"Languages.","entry":"Unlike other elves, you don't speak, read, or write Common. You instead speak, read, and write Sylvan."}]}],"skillProficiencies":null,"homebrew":true},{"name":"High Elf (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Cantrip","Elf Weapon Training","Extra Language"],"entries":[{"type":"text","content":"<i>**//As a high elf, you have a keen mind and a mastery of at least the basics of magic. In many of the worlds of D&D, there are two kinds of high elves. One type (which includes the gray elves and valley elves of Greyhawk, the Silvanesti of Dragonlance, and the sun elves of the Forgotten Realms) is haughty and reclusive, believing themselves to be superior to non-elves and even other elves. The other type (including the high elves of Greyhawk. the Qualinesti of Dragonlance, and the moon elves of the Forgotten Realms) are more common and more friendly, and often encountered among humans and other races.//**</i> <i>**//The sun elves of Faerun (also called gold elves or sunrise elves) have bronze skin and hair of copper, black, or golden blood. Their eyes are golden, silver, or black. Moon elves (also called silver elves or gray elves) are much paler, with alabaster skin sometimes tinged with blue. They often have hair of silver-while, black, or blue, but various shades of blond, brown, and red are not uncommon. Their eyes are blue or green and flecked with gold.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Wizard spell list. Intelligence is your spellcasting ability for it."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"type":"item","name":"Extra Language.","entry":"You can read, speak, and write one additional language of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Juraga Elf (Zendikar)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Elf Weapon Training","Fleet of Foot","Mask of the Wild"],"entries":[{"type":"text","content":"<i>**//The elves of the imperious Joraga nation of Bala Ged have little respect for any other race of Zendikar — or even for other elves. The survival of their nation and its traditions is the Joraga elves’ only goal, and they view the influence of others as a weakness. The Joraga eschew the goods and habits of others, even avoiding the pathways blazed by the Tajuru when possible. Many view the nomadic Joraga clans as little more than bands of roving murderers, but a complex culture hides behind those clans’ aggressive exterior.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"type":"item","name":"Fleet of Foot.","entry":"Your base walking speed increases to 35 feet."},{"type":"item","name":"Mask of the Wild.","entry":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Elf Mark Of Shadow (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Cunning Intuition","Shape Shadows","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If you're an elf with the Mark of Shadow, you have this subrace, with the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1"},{"type":"item","name":"Cunning Intuition.","entry":"Whenever you roll a Dexterity (Stealth) check or a Charisma (Performance) check, roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Shape Shadows.","entry":"You know the [*http:<i>dnd5e.wikidot.com/spell:minor-illusion Minor Illusion] cantrip. Starting at 3rd level, you can cast the [*http:</i>dnd5e.wikidot.com/spell:invisibility Invisibility] spell with this trait, and you regain the ability to cast it when you finish a long rest.Charisma is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class features, the spells on the Mark of Shadow Spells table are added to the spell list of your spellcasting class. <b>Mark of Shadow Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:disguise-self Disguise Self], [*http:</i>dnd5e.wikidot.com/spell:silent-image Silent Image] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:darkness Darkness], [*http:</i>dnd5e.wikidot.com/spell:pass-without-trace Pass Without Trace] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:clairvoyance Clairvoyance], [*http:</i>dnd5e.wikidot.com/spell:major-image Major Image] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:greater-invisibility Greater Invisibility], [*http:</i>dnd5e.wikidot.com/spell:hallucinatory-terrain Hallucinatory Terrain] || || 5th || [*http://dnd5e.wikidot.com/spell:mislead Mislead] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Mul Daya Elf (Zendikar)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Superior Darkvision","Sunlight Sensitivity","Mul Daya Magic","Elf Weapon Training"],"entries":[{"type":"text","content":"<i>**//Elves of the Mul Daya nation of Bala Ged are set apart from other elves by their relationship with the spirits of their elven ancestors. To the Mul Daya, the spirit world and the mortal realm are different only in terms of their tangibility. Death and the spirits of the dead are as much a part of the lives of the Mul Daya as is the natural world. This is not a macabre sentiment to the elves; they simply view it as the truest sense of the natural order.//**</i> <i>**//Mul Daya elves can often be recognized by their face painting and tattooing. Many Mul Daya decorate their skins with an enwrapping vine motif, and make use of poisons and acids collected at great cost from strange creatures and plants in the depths of Kazandu.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 1."},{"type":"item","name":"Superior Darkvision.","entry":"Your darkvision has a radius of 120 feet."},{"type":"item","name":"Sunlight Sensitivity.","entry":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"type":"item","name":"Mul Daya Magic.","entry":"You know the chill touch cantrip. When you reach 3rd level, you can cast the hex spell once with this trait and regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the darkness spell once with this trait and regain the ability to do so when you finish a long rest. Wisdom is your spellcasting ability for these spells."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Pallid Elf (EGW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Incisive Sense","Blessing of the Moonweaver"],"entries":[{"type":"text","content":"<i>**//The pallid elves are a mystical and insightful people with skin as pale as the surface of Exandria's largest moon. They emerged from the Pallid Grove this century and wander the world with childlike curiosity.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Incisive Sense.","entry":"You have advantage on Investigation and Insight checks."},{"type":"item","name":"Blessing of the Moonweaver.","entry":"You know the Light cantrip. When you reach 3rd level, you can cast Sleep once, and it recharges after a long rest. When you reach 5th level, you can cast Invisibility (Self Only) once, and it recharges after a long rest. You do not need the material components required of the spells. Wisdom is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Elf (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Fey Ancestry","Trance","Keen Senses","Languages"],"entries":[{"type":"text","content":"<i>**//Elves are a magical people of otherworldly grace, living in places of ethereal beauty, in the midst of ancient forests or in silvery spires glittering with faerie light, where soft music drifts through the air and gentle fragrances waft on the breeze. Elves love nature and magic, art and artistry, music and poetry.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Age.","entry":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."},{"type":"item","name":"Alignment.","entry":"Elves love freedom, variety, and self-expression, so they lean strongly towards the gentler aspects of chaos. They value and protect others' freedom as well as their own, and are good more often than not. Drow are an exception; their exile into the Underdark has made them vicious and dangerous. Drow are more often evil than not."},{"type":"item","name":"Size.","entry":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"Elves do not sleep. Instead they meditate deeply, remaining semi-conscious, for 4 hours a day. The Common word for this meditation is \\"trance.\\" While meditating, you dream after a fashion; such dreams are actually mental exercises that have become reflexive after years of practice. After resting in this way, you gain the same benefit a human would from 8 hours of sleep."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Elven."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tajuru Elf (Zendkiar)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Skill Versatility"],"entries":[{"type":"text","content":"<i>**//The Tajuru nation is the largest of the three main elven nations, concentrated in Murasa and spread across other parts of Zendikar as hundreds of far-flung clans. Tajuru elves are the most open to people of other races, seeing their skills and perspectives as valuable new tools for survival. The Tajuru are also more open to new lifestyles, be it living in a mountaintop citadel or roaming grassy plains.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Skill Versatility.","entry":"You gain proficiency in any combination of two skills or tools of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Vadahar Elf (Kaladesh)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Elf Weapon Training","Cantrip","Extra Language"],"entries":[{"type":"text","content":"<i>**//The Vahadar are elves who dwell in the cities of Kaladesh. They are comfortable with technology, and work as planners, architects, aether-seers, or inventors. Some of them use the techniques of Bishtahar cultivators to grow food on rooftops, towers, and greenways. The Vahadar are generally integrated into the rest of society on Kaladesh, living in cities dominated by the other races (though, as in Ghirapur, many of them live in specific garden-like neighborhoods) and engaging in trade.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Druid spell list. Wisdom is your spellcasting ability for it."},{"type":"item","name":"Extra Language.","entry":"You can speak, read, and write one extra language of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Wood Elf (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Elf Weapon Training","Fleet of Foot","Mask of the Wild"],"entries":[{"type":"text","content":"<i>**//As a wood elf, you have keen senses and intuition, and your fleet feet carry you quickly and stealthily through your native forests. This category includes the wild elves (grugach) of Greyhawk and the Kagonesti of Dragonlance, as well as the races called wood elves in Greyhawk and the Forgotten Realms. In Faerun, wood elves (also called wild elves. green elves, or forest elves) are reclusive and distrusting of non-elves.//**</i> <i>**//Wood elves' skin tends to be copperish in hue, sometimes with traces of green. Their hair tends toward browns and blacks, but it is occasionally blond or copper-colored. Their eyes are green, brown, or hazel.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Elf Weapon Training.","entry":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"type":"item","name":"Fleet of Foot.","entry":"Your base walking speed increases to 35 feet."},{"type":"item","name":"Mask of the Wild.","entry":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Elf (Zendkiar)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Fey Ancestry","Trance","Keen Senses","Languages"],"entries":[{"type":"text","content":"<i>**//Elves are strongly associated with nature, the magic that flows through their forest homes. Their shamans and druids channel this magic of life and growth, communing with the land or the spirits of the departed. Striving to live in harmony with nature, they celebrate the ties between their communities and their connection with the broader world around them.//**</i> <i>**//The elves of Zendikar have much in common with the elves of other worlds. Your elf character has the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2."},{"type":"item","name":"Age.","entry":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."},{"type":"item","name":"Alignment.","entry":"Elves love freedom, variety, and self-expression, so they lean strongly towards the gentler aspects of chaos. They value and protect others' freedom as well as their own, and are good more often than not. Drow are an exception; their exile into the Underdark has made them vicious and dangerous. Drow are more often evil than not."},{"type":"item","name":"Size.","entry":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"Elves do not sleep. Instead they meditate deeply, remaining semi-conscious, for 4 hours a day. The Common word for this meditation is \\"trance.\\" While meditating, you dream after a fashion; such dreams are actually mental exercises that have become reflexive after years of practice. After resting in this way, you gain the same benefit a human would from 8 hours of sleep."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Elven."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fairy (MPMM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Fairy Magic","Flight","Languages"],"entries":[{"type":"text","content":"<i>**//The Feywild is home to many fantastic peoples, including fairies. Fairies are a wee folk, but not nearly as much so as their pixie and sprite friends. The first fairies spoke Elvish, Goblin, or Sylvan, and encounters with human visitors prompted many of them to learn Common as well.//**</i> <i>**//Infused with the magic of the Feywild, most fairies look like Small elves with insectile wings, but each fairy has a special physical characteristic that sets the fairy apart. For your fairy, roll on the Fey Characteristics table or choose an option from it. You’re also free to come up with your own characteristic if none of the suggestions below fit your character.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Fairy Magic.","entry":"You know the Druidcraft cantrip. * Starting at 3rd level, you can cast the Faerie Fire spell with this trait. Starting at 5th level, you can also cast the Enlarge/Reduce spell with this trait. Once you cast Faerie Fire or Enlarge/Reduce with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Flight.","entry":"Because of your wings, you have a flying speed equal to your walking speed. You can’t use this flying speed if you’re wearing medium or heavy armor."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fairy (UA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Fairy Flight","Fairy Magic","Fey Passage","Languages"],"entries":[{"type":"text","content":"<i>**//The Feywild is home to many fantastic peoples, including fairies. Fairies are a wee folk, but not nearly as much so as their pixie and sprite friends. The first fairies spoke Elvish, Goblin, or Sylvan, and encounters with human visitors prompted many of them to learn Common as well.//**</i> <i>**//Infused with the magic of the Feywild, most fairies look like Small elves with insectile wings, but each fairy has a special physical characteristic that sets the fairy apart. For your fairy, roll on the Fey Characteristics table or choose an option from it. You're also free to come up with your own characteristic if none of the suggestions below fit your character.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"Your size is Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Fairy Flight.","entry":"You have a flying speed equal to your walking speed and can hover. This flight is magical and does not require the use of your wings (if you have them)."},{"type":"item","name":"Fairy Magic.","entry":"You know the Druidcraft and Faerie Fire spells. You can cast Faerie Fire without expending a spell slot, and you must finish a long rest before you can cast it this way again. You can also cast this spell using any spell slots you have. Your spellcasting ability for these spells is your choice of Intelligence, Wisdom, or Charisma."},{"type":"item","name":"Fey Passage.","entry":"You can squeeze through a space as narrow as 1 inch wide."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fairy (WBW)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Life Span","Size","Speed","Fairy Magic","Flight"],"entries":[{"type":"text","content":"<i>**//The Feywild is home to many fantastic peoples, including fairies. Fairies are a wee folk, but not nearly as much so as their pixie and sprite friends. The first fairies spoke Elvish, Goblin, or Sylvan, and encounters with human visitors prompted many of them to learn Common as well.//**</i> <i>**//Infused with the magic of the Feywild, most fairies look like Small elves with insectile wings, but each fairy has a special physical characteristic that sets the fairy apart. For your fairy, roll on the Fey Characteristics table or choose an option from it. You're also free to come up with your own characteristic if none of the suggestions below fit your character.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Life Span.","entry":"Fairies have a life span of about a century."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Fairy Magic.","entry":"You know the Druidcraft cantrip. Starting at 3rd level, you can cast the Faerie Fire spell with this trait. Starting at 5th level, you can also cast the Enlarge/Reduce spell with this trait. Once you cast Faerie Fire or Enlarge/Reduce with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Flight.","entry":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Firbolg (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Firbolg Magic","Hidden Step","Powerful Build","Speech of Beast and Leaf","Languages"],"entries":[{"type":"text","content":"<i>**//Distant cousins of giants, the first firbolgs wandered the primeval forests of the multiverse, and the magic of those forests entwined itself with the firbolgs’ souls. Centuries later, that magic still thrums inside a firbolg, even one who has never lived under the boughs of a great forest.//**</i> <i>**//A firbolg’s magic is an obscuring sort, which allowed their ancestors to pass through a forest without disturbing it. So deep is the connection between a firbolg and the wild places of the world that they can communicate with flora and fauna.//**</i> <i>**//Firbolgs can live up to 500 years.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Firbolg Magic.","entry":"You can cast the Detect Magic and Disguise Self spells with this trait. When you use this version of Disguise Self, you can seem up to 3 feet shorter or taller. Once you cast either of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Hidden Step.","entry":"As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Speech of Beast and Leaf.","entry":"You have the ability to communicate in a limited manner with Beasts, Plants, and vegetation. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Firbolg (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"elvish":true},{"giant":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Firbolg Magic","Hidden Step","Powerful Build","Speech of Beast and Leaf","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and your Strength score increases by 1."},{"type":"item","name":"Age.","entry":"As humanoids related to the fey, firbolg have long lifespans. A firbolg reaches adulthood around 30, and the oldest of them can live for 500 years."},{"type":"item","name":"Alignment.","entry":"As people who follow the rhythm of nature and see themselves as its caretakers, firbolg are typically neutral good. Evil firbolg are rare and are usually the sworn enemies of the rest of their kind."},{"type":"item","name":"Size.","entry":"Firbolg are between 7 and 8 feet tall and weigh between 240 and 300 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Firbolg Magic.","entry":"You can cast Detect Magic and Disguise Self with this trait, using Wisdom as your spellcasting ability for them. Once you cast either spell, you can't cast it again with this trait until you finish a short or long rest. When you use this version of disguise self, you can seem up to 3 feet shorter than normal, allowing you to more easily blend in with humans and elves."},{"type":"item","name":"Hidden Step.","entry":"As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. Once you use this trait, you can't use it again until you finish a short or long rest."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Speech of Beast and Leaf.","entry":"You have the ability to communicate in a limited manner with beasts and plants. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Elvish, and Giant."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Air Genasi (EEPC)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"primordial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Unending Breath","Mingle with the Wind","Languages"],"entries":[{"type":"text","content":"<i>**//Those who think of other planes at all consider them remote, distant realms, but planar influence can be felt throughout the world. It sometimes manifests in beings who, through an accident of birth, carry the power of the planes in their blood. The genasi are one such people, the offspring of genies and mortals.//**</i> <i>**//As an air genasi, you are descended from the djinn. As changeable as the weather, your moods shift from calm to wild and violent with little warning, but these storms rarely last long.//**</i> <i>**//Air genasi typically have light blue skin, hair, and eyes. A faint but constant breeze accompanies them, tousling the hair and stirring the clothing. Some air genasi speak with breathy voices, marked by a faint echo. A few display odd patterns in their flesh or grow crystals from their scalps.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years."},{"type":"item","name":"Alignment.","entry":"Independent and self-reliant, genasi tend toward a neutral alignment."},{"type":"item","name":"Size.","entry":"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Unending Breath.","entry":"You can hold your breath indefinitely while you’re not incapacitated."},{"type":"item","name":"Mingle with the Wind.","entry":"You can cast the Levitate spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Air Genasi (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":35},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Unending Breath","Lightning Resistance","Mingle with the Wind","Languages"],"entries":[{"type":"text","content":"<i>**//Tracing their ancestry to the genies of the Elemental Planes, each genasi can tap into the power of one of the elements. Air, earth, fire, and water — these are the four pillars of the Material Plane and the four types of genasi. Some genasi are direct descendants of a genie, while others were born to non-genasi parents who lived near a place suffused by a genie’s magic.//**</i> <i>**//A typical genasi has a life span of 120 years//**</i> <i>**//Air genasi are descended from djinn, the genies of the Elemental Plane of Air. Embodying many of the airy traits of their otherworldly ancestors, air genasi can draw upon their connection to the winds.//**</i> <i>**//Air genasi’s skin tones include many shades of blue, along with the full range of human skin tones, with bluish or ashen casts. Sometimes their skin is marked by lines that seem like cracks with bluish-white energy spilling out. An air genasi’s hair might blow in a phantom wind or be made entirely of clouds or vapor.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 35 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Unending Breath.","entry":"You can hold your breath indefinitely while you’re not incapacitated."},{"type":"item","name":"Lightning Resistance.","entry":"You have resistance to lightning damage."},{"type":"item","name":"Mingle with the Wind.","entry":"You know the Shocking Grasp cantrip. Starting at 3rd level, you can cast the Feather Fall spell with this trait, without requiring a material component. Starting at 5th level, you can also cast the Levitate spell with this trait, without requiring a material component. Once you cast Feather Fall or Levitate with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Earth Genasi (EEPC)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"primordial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Earth Walk","Merge with Stone","Languages"],"entries":[{"type":"text","content":"<i>**//Those who think of other planes at all consider them remote, distant realms, but planar influence can be felt throughout the world. It sometimes manifests in beings who, through an accident of birth, carry the power of the planes in their blood. The genasi are one such people, the offspring of genies and mortals.//**</i> <i>**//As an earth genasi, you are descended from the cruel and greedy dao, though you aren’t necessarily evil. You have inherited some measure of control over earth, reveling in superior strength and solid power. You tend to avoid rash decisions, pausing long enough to consider your options before taking action.//**</i> <i>**//Elemental earth manifests differently from one individual to the next. Some earth genasi always have bits of dust falling from their bodies and mud clinging to their clothes, never getting clean no matter how often they bathe. Others are as shiny and polished as gemstones, with skin tones of deep brown or black, eyes sparkling like agates. Earth genasi can also have smooth metallic flesh, dull iron skin spotted with rust, a pebbled and rough hide, or even a coating of tiny embedded crystals. The most arresting have fissures in their flesh, from which faint light shines.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Strength score increases by 1."},{"type":"item","name":"Age.","entry":"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years."},{"type":"item","name":"Alignment.","entry":"Independent and self-reliant, genasi tend toward a neutral alignment."},{"type":"item","name":"Size.","entry":"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Earth Walk.","entry":"You can move across difficult terrain made of earth or stone without expending extra movement."},{"type":"item","name":"Merge with Stone.","entry":"You can cast the Pass without Trace spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Earth Genasi (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Earth Walk","Merge with Stone","Languages"],"entries":[{"type":"text","content":"<i>**//Tracing their ancestry to the genies of the Elemental Planes, each genasi can tap into the power of one of the elements. Air, earth, fire, and water — these are the four pillars of the Material Plane and the four types of genasi. Some genasi are direct descendants of a genie, while others were born to non-genasi parents who lived near a place suffused by a genie’s magic.//**</i> <i>**//A typical genasi has a life span of 120 years//**</i> <i>**//Tracing their ancestry to dao, the genies of the Elemental Plane of Earth, earth genasi inherit dao’s steadfast strength and control over earth.//**</i> <i>**//An earth genasi’s skin can be the colors of stone and earth or a human skin tone with glittering sparkles like gem dust. Some earth genasi have lines marking their skin like cracks, either showing glimmering gemlike veins or a dim, yellowish glow. Earth genasi hair can appear carved of stone or crystal or resemble strands of spun metal.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Earth Walk.","entry":"You can move across difficult terrain without expending extra movement if you are using your walking speed on the ground or a floor."},{"type":"item","name":"Merge with Stone.","entry":"You know the Blade Ward cantrip. You can cast it as normal, and you can also cast it as a bonus action a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest. * Starting at 5th level, you can cast the Pass Without Trace spell with this trait, without requiring a material component. Once you cast that spell with this trait, you can’t do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fire Genasi (EEPC)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"primordial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Fire Resistance","Reach to the Blaze","Languages"],"entries":[{"type":"text","content":"<i>**//Those who think of other planes at all consider them remote, distant realms, but planar influence can be felt throughout the world. It sometimes manifests in beings who, through an accident of birth, carry the power of the planes in their blood. The genasi are one such people, the offspring of genies and mortals.//**</i> <i>**//As a fire genasi, you have inherited the volatile mood and keen mind of the efreet. You tend toward impatience and making snap judgments. Rather than hide your distinctive appearance, you exult in it.//**</i> <i>**//Nearly all fire genasi are feverishly hot as if burning inside, an impression reinforced by flaming red, coal- black, or ash-gray skin tones. The more human-looking have fiery red hair that writhes under extreme emotion, while more exotic specimens sport actual flames dancing on their heads. Fire genasi voices might sound like crackling flames, and their eyes flare when angered. Some are accompanied by the faint scent of brimstone.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years."},{"type":"item","name":"Alignment.","entry":"Independent and self-reliant, genasi tend toward a neutral alignment."},{"type":"item","name":"Size.","entry":"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. Your ties to the Elemental Plane of Fire make your darkvision unusual: everything you see in darkness is in a shade of red."},{"type":"item","name":"Fire Resistance.","entry":"You have resistance to fire damage."},{"type":"item","name":"Reach to the Blaze.","entry":"You know the Produce Flame cantrip. Once you reach 3rd level, you can cast the Burning Hands spell once with this trait as a 1st-level spell, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fire Genasi (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fire Resistance","Reach to the Blaze","Languages"],"entries":[{"type":"text","content":"<i>**//Tracing their ancestry to the genies of the Elemental Planes, each genasi can tap into the power of one of the elements. Air, earth, fire, and water — these are the four pillars of the Material Plane and the four types of genasi. Some genasi are direct descendants of a genie, while others were born to non-genasi parents who lived near a place suffused by a genie’s magic.//**</i> <i>**//A typical genasi has a life span of 120 years//**</i> <i>**//Descended from efreet, the genies of the Elemental Plane of Fire, fire genasi channel the flamboyant and often destructive nature of flame. They show their heritage in their skin tones, which can range from deep charcoal to shades of red and orange. Some bear skin tones common to humanity but with fiery marks, such as slowly swirling lights under their skin that resemble embers or glowing red lines tracing over their bodies like cracks. Fire genasi hair can resemble threads of fire or sooty smoke.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fire Resistance.","entry":"You have resistance to fire damage."},{"type":"item","name":"Reach to the Blaze.","entry":"You know the Produce Flame cantrip. Starting at 3rd level, you can cast the Burning Hands spell with this trait. Starting at 5th level, you can also cast the Flame Blade spell with this trait, without requiring a material component. Once you cast Burning Hands or Flame Blade with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Water Genasi (EEPC)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"primordial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Swim","Acid Resistance","Amphibious","Call to the Wave","Languages"],"entries":[{"type":"text","content":"<i>**//Those who think of other planes at all consider them remote, distant realms, but planar influence can be felt throughout the world. It sometimes manifests in beings who, through an accident of birth, carry the power of the planes in their blood. The genasi are one such people, the offspring of genies and mortals.//**</i> <i>**//The lapping of waves, the spray of sea foam on the wind, the ocean depths — all of these things call to your heart. You wander freely and take pride in your independence, though others might consider you selfish.//**</i> <i>**//Most water genasi look as if they just finished bathing, with beads of moisture collecting on their skin and hair. They smell of fresh rain and clean water. Blue or green skin is common, and most have somewhat overlarge eyes, blue-black in color. A water genasi’s hair might float freely, swaying and waving as if underwater. Some have voices with undertones reminiscent of whale song or trickling streams.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2 and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years."},{"type":"item","name":"Alignment.","entry":"Independent and self-reliant, genasi tend toward a neutral alignment."},{"type":"item","name":"Size.","entry":"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Swim.","entry":"You have a swimming speed of 30 feet."},{"type":"item","name":"Acid Resistance.","entry":"You have resistance to acid damage."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Call to the Wave.","entry":"You know the Shape Water cantrip. When you reach 3rd level, you can cast the Create or Destroy Water spell as a 2nd-level spell once with this trait, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Water Genasi (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Acid Resistance","Amphibious","Call to the Wave","Languages"],"entries":[{"type":"text","content":"<i>**//Tracing their ancestry to the genies of the Elemental Planes, each genasi can tap into the power of one of the elements. Air, earth, fire, and water — these are the four pillars of the Material Plane and the four types of genasi. Some genasi are direct descendants of a genie, while others were born to non-genasi parents who lived near a place suffused by a genie’s magic.//**</i> <i>**//A typical genasi has a life span of 120 years//**</i> <i>**//Water genasi descend from marids, aquatic genies from the Elemental Plane of Water. Water genasi are perfectly suited to life underwater and carry the power of the waves inside themselves.//**</i> <i>**//Their skin is often shades of blue or green, sometimes a blend of the two. If they have a human skin tone, there is a glistening texture that catches the light, like water droplets or nearly invisible fish scales. Their hair can resemble seaweed, waving as if in a current, or it can even be like water itself.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Acid Resistance.","entry":"You have resistance to acid damage."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Call to the Wave.","entry":"You know the Acid Splash cantrip. Starting at 3rd level, you can cast the Create or Destroy Water spell with this trait. Starting at 5th level, you can also cast the Water Walk spell with this trait, without requiring a material component. Once you cast Create or Destroy Water or Water Walk with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Giff (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Damage Dealer","Hippo Build","Languages"],"entries":[{"type":"text","content":"<i>**//Giff are tall, broad-shouldered folk with hippo-like features. Some have smooth skin, while others have short bristles on their faces and the tops of their heads. As beings of impressive size and unforgettable appearance, giff are noticed wherever they go.//**</i> <i>**//Storytelling is a rich tradition among giff, and it’s not uncommon to see a giff recounting their past exploits to an enraptured crowd. Having a friendly giff nearby when a tavern brawl erupts can also be useful, for a giff can usually more than hold their own when pleasant revelry devolves into fisticuffs.//**</i> <i>**//The giff are split into two camps concerning how their name is pronounced. Half of them say it with a hard g, half with a soft g. Disagreements over the correct pronunciation often blossom into hard feelings, loud arguments, and headbutting contests, but rarely escalate beyond that.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."},{"type":"item","name":"Damage Dealer.","entry":"Like a hippopotamus in a crystal wareshop, you are naturally adept at damaging things. When you roll a 1 on a damage die for a melee attack, you can reroll the die and use the new roll. You can do so no more than once per turn."},{"type":"item","name":"Hippo Build.","entry":"You have advantage on Strength-based ability checks and Strength saving throws. In addition, you count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Githyanki (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Astral Knowledge","Githyanki Psionics","Psychic Resilience","Languages"],"entries":[{"type":"text","content":"<i>**//Once members of a people who escaped servitude to mind flayers, githyanki split from their cousins, githzerai, and fled to the Astral Plane. In that timeless, silvery realm, githyanki honed their psionic powers and built a great city called Tu’narath. They have since spread throughout the multiverse, starting in outposts outside the Astral Plane, called creches, where time passes and their children can reach adulthood.//**</i> <i>**//A lanky people with skin tones of yellows, greens, and browns, githyanki complement their physical prowess with psionic might, instilled in them by mind flayers and cultivated over eons in the Astral Plane. Now all githyanki can use their psychic bond with that plane to access splinters of knowledge left behind by beings who travel, live, and die among the silver astral clouds.//**</i> <i>**//Githyanki who reside in the Astral Plane can live indefinitely.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Astral Knowledge.","entry":"You can mystically access a reservoir of experiences of entities connected to the Astral Plane. Whenever you finish a long rest, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the <i>Player’s Handbook</i>, as you momentarily project your consciousness into the Astral Plane. These proficiencies last until the end of your next long rest."},{"type":"item","name":"Githyanki Psionics.","entry":"You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. * Starting at 3rd level, you can cast the Jump spell with this trait. Starting at 5th level, you can also cast the Misty Step spell with it. Once you cast Jump or Misty Step with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."},{"type":"item","name":"Psychic Resilience.","entry":"You have resistance to psychic damage."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Githyanki (MTF)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Size","Speed","Alignment","Decadent Mastery","Martial Prodigy","Githyanki Psionics","Languages","Gith Tables"],"entries":[{"type":"text","content":"<i>**//The warlike githyanki and the contemplative githzerai are a sundered people –\xA0two cultures that utterly despise one another. The brutal githyanki are trained from birth as warriors, while the githzerai hone their minds to a razor’s edge in their fortresses within Limbo. But before there were githyanki or githzerai, these creatures were a single race enslaved by the illithids.//**</i> <i>**//Although they attempted to overthrow their masters many times, their rebellions were repeatedly crushed until a great leader named Gith arose. After much bloodshed, Gith and her followers threw off the yoke of their illithid masters, but another leader named Zerthimon emerged in the aftermath of battle. Zerthimon challenged Gith's motives, claiming that her strict martial leadership and desire for vengeance amounted to little more than another form of slavery for her people. A rift erupted between followers of each leader, and they eventually became the two races whose enmity endures to this day: the Githyanki in the way of Gith, and the Githzerai in the way of Zerthimon.//**</i> <i>**//Whether these tall, gaunt creatures were peaceful or savage, cultured or primitive before the illithids enslaved and changed them, none can say. Not even the original name of their race remains from that distant time.//**</i> <i>**//The githyanki plunder countless worlds from the decks of their astral vessels and the backs of red dragons. Feathers, beads, gems, and precious metals decorate their armor and weapons – the legendary silver swords with which they cut through their foes. Since winning their freedom from the illithids, the githyanki have become ruthless conquerors under the rulership of their dread lich-queen, Vlaakith.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Gith reach adulthood in their late teens and live for about a century."},{"type":"item","name":"Size.","entry":"Gith are taller and leaner than humans, with most a slender 6 feet in height. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Alignment.","entry":"Githyanki tend toward lawful evil. They are aggressive and arrogant, and they remain the faithful servants of their lich-queen, Vlaakith. Renegade githyanki tend toward chaos."},{"type":"item","name":"Decadent Mastery.","entry":"You learn one language of your choice, and you are proficient with one skill or tool of your choice. In the timeless city of Tu'narath, githyanki have bountiful time to master odd bits of knowledge."},{"type":"item","name":"Martial Prodigy.","entry":"You are proficient with light and medium armor and with shortswords, longswords, and greatswords."},{"type":"item","name":"Githyanki Psionics.","entry":"You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. * When you reach 3rd level, you can cast the Jump spell once with this trait, and you regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the Misty Step spell once with this trait, and you regain the ability to do so when you finish a long rest. * Intelligence is your spellcasting ability for these spells. When you cast them with this trait, they don't require components."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Gith."},{"type":"item","name":"Gith Tables.","entry":"This section provides tables for players and DMs who want to create githyanki characters ||||~ Githyanki Character Concepts || ||~ d4 ||~ Githyanki Personality Trait || || 1 || When I'm bored I make my own excitement, and I'm always bored. || || 2 || I treat others as if they were animals that simply don't know any better. || || 3 || Violence is a spice that makes life worth living. || || 4 || Old age is a concept that I find fascinating. Maybe someday I too will be aged. || ||~ d4 ||~ Githyanki Ideal || || 1 || <b>Fidelity.</b> Warriors are only as good as the vows they keep. || || 2 || <b>Power.</b> The weak rule the strong. || || 3 || <b>Duty.</b> It is by Vlaakith's will alone that I act. || || 4 || <b>Freedom.</b> No strong soul should be enslaved. Better to die first than live as another's puppet. || ||~ d4 ||~ Githyanki Bond || || 1 || There is no greater duty than to serve the Revered Queen. || || 2 || Humanity thrives only because we conquered the illithids. Therefore, what is theirs is ours. || || 3 || Without battle, life has no purpose. || || 4 || Life is but a spark in the dark. We all go dark, but those who dare can burn bright. || ||~ d4 ||~ Githyanki Flaw || || 1 || Hunger and thirst are unbearable pains to me. || || 2 || I can't see a non-githyanki as a real threat. || || 3 || I follow orders, regardless of their implications. || || 4 || I start projects but never finish them. ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Githzerai (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Githzerai Psionics","Mental Discipline","Psychic Resilience","Languages"],"entries":[{"type":"text","content":"<i>**//Githzerai migrated to the Everchanging Chaos of Limbo after the ancient schism that split their ancestors from their cousins, githyanki. Limbo is a roiling maelstrom of matter and energy, collapsing and reforming without purpose or direction, until a creature exerts deliberate will to stabilize it. Through their potent psionic power, githzerai carved a home for themselves amid the chaos. As the ages passed, githzerai explorers ranged out to other planes and worlds of the multiverse.//**</i> <i>**//Githzerai are generally slender, with speckled skin in shades of yellow, green, or brown. Eons of cultivating their mental powers within the endless chaos of Limbo have imbued githzerai with the ability to shape psionic energy to protect themselves and probe minds.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Githzerai Psionics.","entry":"You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. * Starting at 3rd level, you can cast the Shield spell with this trait. Starting at 5th level, you can also cast the Detect Thoughts spell with it. Once you cast Shield or Detect Thoughts with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."},{"type":"item","name":"Mental Discipline.","entry":"Your innate psychic defenses grant you advantage on saving throws you make to avoid or end the charmed and frightened conditions on yourself."},{"type":"item","name":"Psychic Resilience.","entry":"You have resistance to psychic damage."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Githzerai (MTF)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Size","Speed","Alignment","Mental Discipline","Githzerai Psionics","Languages","Gith Tables"],"entries":[{"type":"text","content":"<i>**//The warlike githyanki and the contemplative githzerai are a sundered people –\xA0two cultures that utterly despise one another. The brutal githyanki are trained from birth as warriors, while the githzerai hone their minds to a razor’s edge in their fortresses within Limbo. But before there were githyanki or githzerai, these creatures were a single race enslaved by the illithids.//**</i> <i>**//Although they attempted to overthrow their masters many times, their rebellions were repeatedly crushed until a great leader named Gith arose. After much bloodshed, Gith and her followers threw off the yoke of their illithid masters, but another leader named Zerthimon emerged in the aftermath of battle. Zerthimon challenged Gith's motives, claiming that her strict martial leadership and desire for vengeance amounted to little more than another form of slavery for her people. A rift erupted between followers of each leader, and they eventually became the two races whose enmity endures to this day: the Githyanki in the way of Gith, and the Githzerai in the way of Zerthimon.//**</i> <i>**//Whether these tall, gaunt creatures were peaceful or savage, cultured or primitive before the illithids enslaved and changed them, none can say. Not even the original name of their race remains from that distant time.//**</i> <i>**//Focused philosophers and austere ascetics, the githzerai pursue lives of rigid order. Lean and muscular, they wear unadorned clothing free of ornamentation, keeping their own counsel and trusting few creatures outside of their own kind. Having turned their backs on their warlike githyanki kin, the githzerai maintain a strict monastic lifestyle, dwelling on islands of order in the vast sea of chaos that is the plane of Limbo.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Gith reach adulthood in their late teens and live for about a century."},{"type":"item","name":"Size.","entry":"Gith are taller and leaner than humans, with most a slender 6 feet in height. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Alignment.","entry":"Githzerai tend toward lawful neutral. Their rigorous training in psychic abilities requires an implacable mental discipline."},{"type":"item","name":"Mental Discipline.","entry":"You have advantage on saving throws against the charmed and frightened conditions. Under the tutelage of monastic masters, githzerai learn to govern their own minds."},{"type":"item","name":"Githzerai Psionics.","entry":"You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait. * When you reach 3rd level, you can cast the Shield spell once with this trait, and you regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the Detect Thoughts spell once with this trait, and you regain the ability to do so when you finish a long rest. * Wisdom is your spellcasting ability for these spells. When you cast them with this trait, they don't require components."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Gith."},{"type":"item","name":"Gith Tables.","entry":"This section provides tables for players and DMs who want to create githzerai characters. ||||~ Githzerai Character Concepts || ||~ d4 ||~ Githzerai Personality Trait || || 1 || All energy must be expended to a useful end. Frivolity is the first step to defeat. || || 2 || Patience in all things. The first step in any venture is the most treacherous. || || 3 || Emotions are a trap, meant to weaken the intellect and disturb the nerves. Pay them no heed. || || 4 || Begin only those tasks you will finish. Strike only that which you will kill. || ||~ d4 ||~ Githzerai Ideal || || 1 || <b>Faith.</b> Zerthimon shall return, and I will be worthy to walk beside him. || || 2 || <b>Courage.</b> The mind can master anything if it is unfettered by fear. || || 3 || <b>Duty.</b> My people survive only because those like me place their needs above our own. || || 4 || <b>Freedom.</b> No strong soul should be enslaved. Better to die first than live as another's puppet. || ||~ d4 ||~ Githzerai Bond || || 1 || Zerthimon provides an example of conduct that I strive to duplicate. || || 2 || Menyar-Ag hand-picked me for my duties, and I will never betray the trust he showed in me. || || 3 || Vlaakith and her toadies will be defeated, if not by me then by those who follow in my footsteps. || || 4 || I will not rest until the last elder brain is destroyed. || ||~ d4 ||~ Githzerai Flaw || || 1 || I see githyanki machinations behind every threat. || || 2 || I believe in the supremacy of the gith and that githzerai and githyanki will align to rule the multiverse. || || 3 || I respond to even minor threats with overwhelming displays of force. || || 4 || The next time I laugh will be the first. The sound of merriment takes me to the edge of violence. ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Forest Gnome (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Natural Illusionist","Speak with Small Beasts"],"entries":[{"type":"text","content":"<i>**//As a forest gnome, you have a natural knack for illusion and inherent quickness and stealth. In the worlds of D&D, forest gnomes are rare and secretive. They gather in hidden communities in sylvan forests, using illusions and trickery to conceal themselves from threats or to mask their escape should they be detected. Forest gnomes tend to be friendly with other good-spirited woodland folk, and they regard elves and good fey as their most important allies. These gnomes also befriend small forest animals and rely on them for information about threats that might prowl their lands.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Natural Illusionist.","entry":"You know the Minor Illusion cantrip. Intelligence is your spellcasting modifier for it."},{"type":"item","name":"Speak with Small Beasts.","entry":"Through sound and gestures, you may communicate simple ideas with Small or smaller beasts."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Gnome Mark Of Scribing (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Gifted Scribe","Scribe's Insight","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If you're a gnome with the Mark of Scribing, you have this subrace, with the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1"},{"type":"item","name":"Gifted Scribe.","entry":"Whenever you make an Intelligence (History) or an Ability Check involving Calligrapher's Supplies, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Scribe's Insight.","entry":"You know the [*http:<i>dnd5e.wikidot.com/spell:message Message] cantrip. You can also cast the [*http:</i>dnd5e.wikidot.com/spell:comprehend-languages Comprehend Languages] spell with this trait. Starting at 3rd level, you can also cast the [*http://dnd5e.wikidot.com/spell:magic-mouth Magic Mouth] spell with it. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Intelligence is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Scribing Spells table are added to the spell list of your Spellcasting class. <b>Mark of Scribing Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:comprehend-languages Comprehend Languages], [*http:</i>dnd5e.wikidot.com/spell:illusory-script Illusory Script] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:animal-messenger Animal Messenger], [*http:</i>dnd5e.wikidot.com/spell:silence Silence] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:sending Sending], [*http:</i>dnd5e.wikidot.com/spell:tongues Tongues] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:arcane-eye Arcane Eye], [*http:</i>dnd5e.wikidot.com/spell:divination Divination] || || 5th || [*http://dnd5e.wikidot.com/spell:dream Dream] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Gnome (PHB)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"gnomish":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Gnome Cunning","Languages"],"entries":[{"type":"text","content":"<i>**//A constant hum of busy activity pervades the warrens and neighborhoods where gnomes form their close-knit communities. Louder sounds punctuate the hum: a crunch of grinding gears here, a minor explosion there, a yelp of surprise or triumph, and especially bursts of laughter. Gnomes take delight in life, enjoying every moment of invention, exploration, investigation, creation, and play.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2."},{"type":"item","name":"Age.","entry":"Gnomes mature at the same rate as humans, and most are expected to settle into adult life around the age of 40. They can live to 350 years on average, but it's not too uncommon for them to reach 500 years of age."},{"type":"item","name":"Alignment.","entry":"Gnomes are generally Good. Those who tend towards Law are sages, engineers, researchers, scholars, investigators, or inventors. Those who tend towards Chaos are often minstrels, tricksters, wanderers, or fanciful jewelers. Gnomes are light-hearted, and even the tricksters amongst them favor harmless pranks over vicious schemes."},{"type":"item","name":"Size.","entry":"Gnomes are between 3 and 4 feet tall and weigh around 40 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Gnome Cunning.","entry":"You have advantage on all Intelligence, Wisdom, and Charisma saves against magic."},{"type":"item","name":"Languages.","entry":"You can read, speak, and write Common and Gnomish."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Rock Gnome (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Artificer's Lore","Tinker"],"entries":[{"type":"text","content":"<i>**//As a rock gnome, you have a natural inventiveness and hardiness beyond that of other gnomes. Most gnomes in the worlds of D&D are rock gnomes, including the tinker gnomes of the Dragonlance setting.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Artificer's Lore.","entry":"Whenever you make an Intelligence (History) check related to magical, alchemical, or technological items, you can add twice your proficiency bonus instead of any other proficiency bonus that may apply."},{"type":"item","name":"Tinker.","entry":"You have proficiency with artisan tools (tinker's tools). Using those tools, you can spend 1 hour and 10 gp worth of materials to construct a Tiny clockwork device (AC 5, 1 hp). The device ceases to function after 24 hours (unless you spend 1 hour repairing it to keep the device functioning), or when you use your action to dismantle it; at that time, you can reclaim the materials used to create it. You can have up to three such devices active at a time. When you create a device, choose one of the following options: * <i><b>Clockwork Toy.</b></i> This toy is a clockwork animal, monster, or person, such as a frog, mouse, bird, dragon, or soldier. When placed on the ground, the toy moves 5 feet across the ground on each of your turns in a random direction. It makes noises as appropriate to the creature it represents. * <i><b>Fire Starter.</b></i> The device produces a miniature flame, which you can use to light a candle, torch, or campfire. Using the device requires your action. * <i><b>Music Box.</b></i> When opened, this music box plays a single song at a moderate volume. The box stops playing when it reaches the song's end or when it is closed. * At your DM's discretion, you may make other objects with effects similar in power to these. The Prestidigitation cantrip is a good baseline for such effects."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dankwood Goblin (AWM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Speak with Small Beasts","Nimble Escape","Languages"],"entries":[{"type":"text","content":"<i>**//Dankwood goblins are much like any other run-of-the-mill goblin but they are much more gentle and artistic than the savage and uncouth goblins of the world.//**</i> <i>**//They are inquisitive and have a magical bond with the small forest creatures with which they are often friends. They are fast and numble and love to explore. Because of this they make great adventurers and guides.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Dankwood goblins reach adulthood at age 8 and live up to 60 years."},{"type":"item","name":"Alignment.","entry":"Dankwood goblins are typically neutral or neutral good, though some mischievous dankwood goblins are chaotic neutral."},{"type":"item","name":"Size.","entry":"Dankwood goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet"},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Speak with Small Beasts.","entry":"Through sounds nad gestures you can communicate simple ideas with Small of smaller beasts. Dankwood goblins love animals and often keep squirrels, badgers, rabbits, moles, woodpeckers, and other creatures as beloved pets."},{"type":"item","name":"Nimble Escape.","entry":"You can take the Disengage or Hide action as a bonus action on each of your turns."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goblin (Ixalan)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Agile Climber","Darkvision","Languages"],"entries":[{"type":"text","content":"<i>**//Goblins are native to Ixalan, and their eager curiosity drew them to the ships of the Brazen Coalition where the pirates first made landfall on the Sun Empire's shores. Though they still thrive in remote jungle colonies, goblins are most commonly seen swinging on the ropes of sleek pirate ships.//**</i> <i>**//Goblins stand about three feet tall, though they rarely stand upright. They prefer a crouched posture that lets them scramble quickly on all fours, aided by their long prehensile tails. Their hearing and eyesight make them excellent lookouts, and their agility serves them well as crew members on pirate ships. They climb, swing, and jump easily among a ship's ropes, and can get into tight spaces that humans can't. For better or worse, many goblins are also incorrigible pranksters, and they often have a hard time determining when a prank is inappropriate, is poorly timed, or has gone too far.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Age.","entry":"Goblins mature faster than humans, reaching adulthood around age 12. They age noticeably faster, and though few goblins live to old age, the most cautious rarely live longer than 50 years."},{"type":"item","name":"Alignment.","entry":"Most goblins are wildly chaotic, with no particular inclination toward good or evil but a strong tendency toward mischief."},{"type":"item","name":"Size.","entry":"Goblins average about 3 feet tall and weigh about 40 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet"},{"type":"item","name":"Agile Climber.","entry":"You have a climbing speed of 25 feet. You can't use your climbing speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your climbing speed if you are encumbered.)"},{"type":"item","name":"Darkvision.","entry":"Accustomed to life in the jungle night, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common (if it exists in your campaign) and Goblin."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goblin (MPMM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fey Ancestry","Fury of the Small","Nimble Escape","Languages"],"entries":[{"type":"text","content":"<i>**//A subterranean folk, goblins can be found in every corner of the multiverse, often beside their bugbear and hobgoblin kin. Long before the god Maglubiyet conquered them, early goblins served in the court of the Queen of Air and Darkness, one of the Feywild’s archfey. Goblins thrived in her dangerous domain thanks to a special boon from her—a supernatural knack for finding the weak spots in foes larger than themselves and for getting out of trouble. Goblins brought this fey boon with them to worlds across the Material Plane, even if they don’t remember the fey realm they inhabited before Maglubiyet’s rise. Now many goblins pursue their own destinies, escaping the plots of both archfey and gods.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Fury of the Small.","entry":"When you damage a creature with an attack or a spell and the creature’s size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus. * You can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."},{"type":"item","name":"Nimble Escape.","entry":"You can take the Disengage or Hide action as a bonus action on each of your turns."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goblin (VGM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Fury of the Small","Nimble Escape","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Goblins reach adulthood at age 8 and live up to 60 years."},{"type":"item","name":"Alignment.","entry":"Goblins are typically neutral evil, as they care only for their own needs. A few goblins might tend toward good or neutrality, but only rarely."},{"type":"item","name":"Size.","entry":"Goblins are between 3 and 4 feet tall and weigh between 40 and 80 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fury of the Small.","entry":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."},{"type":"item","name":"Nimble Escape.","entry":"You can take the Disengage or Hide action as a bonus action on each of your turns."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goblin (Zendikar)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Grit","Languages","Tribe","Grotag Tamer","Lavastep Grit","Tuktuk Cunning"],"entries":[{"type":"text","content":"<i>**//Goblins are an inquisitive and adaptable race hampered by their small size, their natural cowardice, and a severe shortage of common sense. They eagerly explore areas that others hesitate to enter, and obsessively fiddle with magic that more sensible folk would take careful precautions with. They prize ancient artifacts not for their inherent value, but primarily as a mark of status—for a precious trophy proves that its owner survived a delve into a deep and dangerous ruin.//**</i> <i>**//A typical goblin stands between three-and-a-half and five feet tall, with a slender, elongated build. Goblins' arms are unusually long and spindly, making them adept at climbing cliffs and trees. Their skin has a stony texture, ranging in color from red-brown to moss green or gray. Their ears are large and swept back, their eyes are intensely red, and many sport heavy bone protrusions on their spines or elbows. Males have similar growths jutting from their chins, while females have heavier growths on their foreheads.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2."},{"type":"item","name":"Age.","entry":"Goblins mature faster than humans, reaching adulthood around age 12. They age noticeably faster, and though few goblins live to old age, the most cautious rarely live longer than 50 years."},{"type":"item","name":"Alignment.","entry":"Most goblins are wildly chaotic, with no particular inclination toward good or evil."},{"type":"item","name":"Size.","entry":"Goblins average about 3 feet tall and weigh about 40 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet"},{"type":"item","name":"Darkvision.","entry":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Grit.","entry":"You have resistance to fire damage and psychic damage. In addition, when you are wearing no armor, your AC is equal to 11 + your Dexterity modifier."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common (if it exists in your campaign) and Goblin."},{"type":"item","name":"Tribe.","entry":"Most goblins on Zendikar belong to one of three tribes: the Grotag, the Lavastep, and the Tuktuk. Choose one of these tribes. * Grotag Tribe * Smaller and weaker than their cousins, and with larger hands and feet, goblins of the Grotag tribe attempt to live by their wits-though seldom with much success. When a Grotag goblin has the bright idea of trying to tame fleshpiercer mites, at least a few others will be willing to follow that goblin into a nest-usually to predictably horrible results. But though the Grotag seem to have a never-ending supply of bad ideas, and a horrible ratio of bad ideas to good, the Grotag likewise seem to have a never-ending supply of Grotag. As such, by trial and error (and more error), these goblins have stumbled across a great deal of knowledge useful for surviving the deep places of Zendikar, and for dealing with the creatures that live there. The Grotag imagine themselves to have a sort of empathy with beasts, and they lose hundreds of goblins each year to ill-advised attempts at monster taming. But, every now and again, one of these efforts is successful."},{"type":"item","name":"Grotag Tamer.","entry":"You have proficiency in the Animal Handling skill. * Lavastep Tribe * The Lavastep tribe is the most industrious of the goblin tribes, and possesses much hard-won knowledge of the geothermal activity in Akoum. More so than members of the other tribes, the Lavastep goblins build surprisingly effective equipment out of the crystal shards and veins of strange metals that occasionally boil up to the surface. The most warlike of their kind, Lavastep goblins frequently harass the kor, elves, and humans of Akoum."},{"type":"item","name":"Lavastep Grit.","entry":"You have advantage on Dexterity (Stealth) checks made to hide in rocky or subterranean environments. * Tuktuk Tribe * Among the goblins, the Tuktuk are most likely to hire themselves out as ruin guides to other races. Of course, their usual plan is to help find something of value, steal it, trigger a trap intentionally, and then run."},{"type":"item","name":"Tuktuk Cunning.","entry":"You have proficiency with thieves' tools."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goliath (EEPC)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"giant":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Natural Athlete","Stone's Endurance","Powerful Build","Mountain Born","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Goliaths have lifespans comparable to humans. They enter adulthood in their late teens and usually live less than a century."},{"type":"item","name":"Alignment.","entry":"Goliath society, with its clear roles and tasks, has a strong lawful bent. The goliath sense of fairness, balanced with an emphasis on self-sufficiency and personal accountability, pushes them toward neutrality."},{"type":"item","name":"Size.","entry":"Goliaths are between 7 and 8 feet tall and weigh between 280 and 340 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Natural Athlete.","entry":"You have proficiency in the Athletics skill."},{"type":"item","name":"Stone's Endurance.","entry":"You can focus yourself to occasionally shrug off injury. When you take damage, you can use your reaction to roll a d12. Add your Constitution modifier to the number rolled, and reduce the damage by that total. After you use this trait, you can’t use it again until you finish a short or long rest."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Mountain Born.","entry":"You have resistance to cold damage. You’re also acclimated to high altitude, including elevations above 20,000 feet."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Giant."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Goliath (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Little Giant","Mountain Born","Stone's Endurance","Languages"],"entries":[{"type":"text","content":"<i>**//The first goliaths lived on the highest mountain peaks — far above the tree line, where the air is thin and frigid winds howl. Distantly related to giants and infused with the supernatural essence of their ancestors’ mountainous home, goliaths stand between 7 and 8 feet tall and have a wide array of skin tones resembling different types of stone.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Little Giant.","entry":"You have proficiency in the Athletics skill, and you count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Mountain Born.","entry":"You have resistance to cold damage. You also naturally acclimate to high altitudes, even if you’ve never been to one. This includes elevations above 20,000 feet."},{"type":"item","name":"Stone's Endurance.","entry":"You can supernaturally draw on unyielding stone to shrug off harm. When you take damage, you can use your reaction to roll a d12. Add your Constitution modifier to the number rolled and reduce the damage by that total. * You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Grung (OGA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[],"traits":["Ability Score Increase","Age","Alignment","Arboreal Alertness","Size","Speed","Amphibious","Poison Immunity","Poisonous Skin","Standing Leap","Water Dependency","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2 and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Grungs mature to adulthood in a single year, but have been known to live up to 50 years."},{"type":"item","name":"Alignment.","entry":"Most grungs are lawful, having been raised in a strict caste system. They tend toward evil as well, coming from a culture where social advancement occurs rarely, and most often because another member of your army has died and there is no one else of that caste to fill the vacancy."},{"type":"item","name":"Arboreal Alertness.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Size.","entry":"Grungs stand between 2 ½ and 3 ½ feet tall and average about 30 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"You have a walking speed of 25 feet. Your sticky finger and toe pads give you a climb speed of 25 feet."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Poison Immunity.","entry":"You are immune to poison damage and the poisoned condition."},{"type":"item","name":"Poisonous Skin.","entry":"Any creature that grapples you or otherwise comes into direct contact with your skin must succeed on a DC 12 Constitution saving throw or become poisoned for 1 minute. A poisoned creature no longer in direct contact with you can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. * You can also apply this poison to any piercing weapon as part of an attack with that weapon, though when you hit the poison reacts differently. The target must succeed on a DC 12 Constitution saving throw or take 2d4 poison damage."},{"type":"item","name":"Standing Leap.","entry":"Your long jump is up to 25 feet and your high jump is up to 15 feet, with or without a running start."},{"type":"item","name":"Water Dependency.","entry":"If you fail to immerse yourself in water for at least 1 hour during a day, you suffer 1 level of exhaustion at the end of that day. You can recover from this exhaustion only through magic or by immersing yourself in water for at least 1 hour."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Grung."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hadozee (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Dexterous Feet","Glide","Languages"],"entries":[{"type":"text","content":"<i>**//Hadozees are people with simian features that long ago adapted to live among the tall trees of their home world. They are natural climbers, with feet as dexterous as their hands, even to the extent of having opposable thumbs. Membranes of skin hang loosely from their arms and legs. When stretched taut, these membranes enable a hadozee to glide.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a climbing speed equal to your walking speed."},{"type":"item","name":"Dexterous Feet.","entry":"You can take the Use an Object action as a bonus action."},{"type":"item","name":"Glide.","entry":"If you are not incapacitated or wearing heavy armor, you can extend your skin membranes and glide. When you do so, you can perform the following aerial maneuvers: * When you fall, you can move up to 5 feet horizontally for every 1 foot you descend. * When you would take damage from a fall, you can use your reaction to reduce the fall’s damage to 0."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Half-Elf Mark Of Detection (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Deductive Intuition","Magical Detection","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your Half-Elf has the Mark of Detection, these features replace the Ability Score Increase and the Half-Elf Versatility traits in the// Player's Handbook.**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and one other Ability Score of your choice increases by 1."},{"type":"item","name":"Deductive Intuition.","entry":"Whenever you make a Intelligence (Investigation) or a Wisdom (Insight) check, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Magical Detection.","entry":"You can cast the [*http:<i>dnd5e.wikidot.com/spell:detect-magic Detect Magic] and the [*http:</i>dnd5e.wikidot.com/spell:detect-poison-and-disease Detect Poison and Disease] spells with this trait. Starting at 3rd level, you can also cast the [*http://dnd5e.wikidot.com/spell:see-invisibility See Invisibility] spell with it. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Intelligence is your Spellcasting Ability for these spells, and you don't require material components for them."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Detection Spells table are added to the spell list of your Spellcasting class. <b>Mark of Detection Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:detect-magic Detect Magic], [*http:</i>dnd5e.wikidot.com/spell:detect-poison-and-disease Detect Poison and Disease] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:detect-thoughts Detect Thoughts], [*http:</i>dnd5e.wikidot.com/spell:find-traps Find Traps] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:clairvoyance Clairvoyance], [*http:</i>dnd5e.wikidot.com/spell:nondetection Nondetection] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:arcane-eye Arcane Eye],[*http:</i>dnd5e.wikidot.com/spell:divination Divination] || || 5th || [*http://dnd5e.wikidot.com/spell:legend-lore Legend Lore] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Half-Elf Mark Of Storm (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Windwright's Intuition","Storm's Boon","Headwinds","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your Half-Elf has the Mark of Storm, these features replace the Ability Score Increase and the Half-Elf Versatility traits in the// Player's Handbook.**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and your Dexterity score increases by 1."},{"type":"item","name":"Windwright's Intuition.","entry":"Whenever you make a Dexterity (Acrobatics) check or any Ability Check involving Navigator's Tools, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Storm's Boon.","entry":"You have resistance to Lightning damage."},{"type":"item","name":"Headwinds.","entry":"You know the [*http:<i>dnd5e.wikidot.com/spell:gust Gust] cantrip. Starting at 3rd level, you can also cast the [*http:</i>dnd5e.wikidot.com/spell:gust-of-wind Gust of Wind] spell with it. Once you cast this spell with this trait, you can't cast that spell again until you finish a Long Rest. Charisma is your Spellcasting Ability for this spell."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Storm Spells table are added to the spell list of your Spellcasting class. <b>Mark of Storm Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:feather-fall Feather Fall], [*http:</i>dnd5e.wikidot.com/spell:fog-cloud Fog Cloud] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:gust-of-wind Gust of Wind], [*http:</i>dnd5e.wikidot.com/spell:levitate Levitate] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:sleet-storm Sleet Storm], [*http:</i>dnd5e.wikidot.com/spell:wind-wall Wind Wall] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:conjure-minor-elementals Conjure Minor Elementals], [*http:</i>dnd5e.wikidot.com/spell:control-water Control Water] || || 5th || [*http://dnd5e.wikidot.com/spell:conjure-elemental Conjure Elemental] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Half Elf (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Fey Ancestry","Languages","Half-Elf Versatility"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and two other ability scores of your choice each increase by 1."},{"type":"item","name":"Age.","entry":"Half-elves age at much the same rate as humans, reaching adulthood at the age of 20. They live much longer than humans, however, often exceeding 180 years."},{"type":"item","name":"Alignment.","entry":"Half-elves share the chaotic bent of their elven heritage. They both value personal freedom and creative expression, demonstrating neither love of leaders nor desire for followers. They chafe at rules, resent others' demands, and sometimes prove unreliable, or at least unpredictable. They are good and evil in equal numbers, a trait they share with their human parents."},{"type":"item","name":"Size.","entry":"Half-elves are more or less the same size as humans, ranging from 5 to 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Thanks to your elven heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Languages.","entry":"You can read, speak, and write Common, Elven, and one language of your choice."},{"type":"item","name":"Half-Elf Versatility.","entry":"Choose one of the following traits: * <i><b>Skill Versatility (General).</b></i> You gain proficiency in two skills of your choice. * <i><b>Elf Weapon Training (High or Wood Elf Heritage).</b></i> You have proficiency with the longsword, shortsword, shortbow, and longbow. * <i><b>Cantrip (High Elf Heritage).</b></i> You know one cantrip of your choice from the wizard spell list. Intelligence is your spellcasting ability for it. * <i><b>Fleet of Foot (Wood Elf Heritage).</b></i> Your base walking speed increases to 35 feet. * <i><b>Mask of the Wild (Wood Elf Heritage).</b></i> You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena. * <i><b>Drow Magic (Dark Elf Heritage).</b></i> You know the Dancing Lights cantrip. When you reach 3rd level, you can cast Faerie Fire once, and it recharges after a long rest. When you reach 5th level, you can cast Darkness once, and it recharges after a long rest. Charisma is your spellcasting ability for these spells. * <i><b>Swim Speed (Aquatic Elf Heritage).</b></i> You have a swimming speed of 30 feet."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Half-Orc Mark Of Finding (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Darkvision","Hunter's Intuition","Finder's Magic","Languages","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your Half-Orc has the Mark of Finding, replace all Racial Traits found in the// Player's Handbook //with these, except for Age, Alignment, Size, and Speed.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60ft. of you as if it were bright light, and in darkness as if it were dim light. You can't discern colors in darkness, only shades of grey."},{"type":"item","name":"Hunter's Intuition.","entry":"Whenever you make a Wisdom (Perception) or a Wisdom (Survival) check, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Finder's Magic.","entry":"You can cast the [*http:<i>dnd5e.wikidot.com/spell:hunters-mark Hunter's Mark] spell with this trait. Starting at 3rd level, you can also cast the [*http:</i>dnd5e.wikidot.com/spell:locate-object Locate Object] spell with it. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Wisdom is your Spellcasting Ability for these spells."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Finding Spells table are added to the spell list of your Spellcasting class. <b>Mark of Finding Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:Faerie-Fire Faerie Fire], [*http:</i>dnd5e.wikidot.com/spell:longstrider Longstrider] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:locate-animals-or-plants Locate Animals or Plants], [*http:</i>dnd5e.wikidot.com/spell:locate-object Locate Object] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:clairvoyance Clairvoyance], [*http:</i>dnd5e.wikidot.com/spell:speak-with-plants Speak With Plants] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:divination Divination], [*http:</i>dnd5e.wikidot.com/spell:locate-creature Locate Creature] || || 5th || [*http://dnd5e.wikidot.com/spell:commune-with-nature Commune With Nature] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Half Orc (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"dwarvish":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Menacing","Relentless Endurance","Savage Attacks","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Half-orcs mature a little faster than humans, reaching adulthood around age 14. They age noticeably faster and rarely live longer than 75 years."},{"type":"item","name":"Alignment.","entry":"Half-orcs inherit a tendency toward chaos from their orc parents and are not strongly inclined toward good. Half-orcs raised among orcs and willing to live out their lives among them are usually evil."},{"type":"item","name":"Size.","entry":"Half-orcs are somewhat larger and bulkier than humans, and they range from 5 to well over 6 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Thanks to your orc blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Menacing.","entry":"You gain proficiency in the Intimidation skill."},{"type":"item","name":"Relentless Endurance.","entry":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."},{"type":"item","name":"Savage Attacks.","entry":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Orc. Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Ghostwise Halfling (SCAG)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Silent Speech"],"entries":[{"type":"text","content":"<i>**//Ghostwise halflings trace their ancestry back to a war among halfling tribes that sent their ancestors into flight from Luiren. Ghostwise halflings are the rarest of the// hin, //found only in the Chondalwood and a few other isolated forests, clustered in tight-knit clans.//**</i> <i>**//Many ghostwise clans select a natural landmark as the center of their territory, and members carry a piece of that landmark with them at all times. Clan warriors known as nightgliders bond with and ride giant owls as mounts.//**</i> <i>**//Because these folk are clannish and mistrustful of outsiders, ghostwise halfling adventurers are rare. Ask your DM if you can play a member of this subrace, which has the halfling traits in the// Player's Handbook, //plus the subrace traits below.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Silent Speech.","entry":"You can speak telepathically to any creature within 30 feet of you. The creature understands you only if the two of you share a language. You can speak telepathically in this way to one creature at a time."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Lightfoot Halfling (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Naturally Stealthy"],"entries":[{"type":"text","content":"<i>**//As a lightfoot halfling, you can easily hide from notice, even using other people as cover. You're inclined to be affable and get along well with others. In the Forgotten Realms, lightfoot halflings have spread the farthest and thus are the most common variety.//**</i> <i>**//Lightfoots are more prone to wanderlust than other halflings, and often dwell alongside other races or take up a nomadic life. In the world of Grayhawk, these halflings are called hairfeet or tallfellows.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Naturally Stealthy.","entry":"You can attempt to hide even when you are only obscured by a creature that is at least one size larger than you."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Lotusden Halfling (EGW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Children of the Woods","Timberwalk"],"entries":[{"type":"text","content":"<i>**//Long tied to the natural heart of the Lotusden Greenwood, these halflings have adapted to live synergistically with the chaotic laws of the wilds.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Children of the Woods.","entry":"You know the Druidcraft Cantrip. At 3rd level, you can cast the Entangle spell once per long rest. At 5th level, you can cast Spike Growth spell once per long rest. These spells don't require the material components normally required. Wisdom is your spellcasting ability for these spells."},{"type":"item","name":"Timberwalk.","entry":"Ability checks made to track you are at disadvantage and you can move through difficult terrain made of non-magical plants and overgrowth without expending extra movement."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Halfling Mark Of Healing (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Medical Intuition","Healing Touch","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If you're a halfling with the Mark of Healing, you have this subrace, with the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Medical Intuition.","entry":"Whenever you roll a Wisdom (Medicine) check or an ability check involving an Herbalism Kit, roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Healing Touch.","entry":"You can cast the [*http:<i>dnd5e.wikidot.com/spell:cure-wounds Cure Wounds] spell with this trait. Beginning at 3rd level, you can also cast the [*http:</i>dnd5e.wikidot.com/spell:lesser-restoration Lesser Restoration] spell with this trait. Once you cast either spell with this trait, you can't cast that spell again until you finish a long rest. Wisdom is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class features, the spells on the Mark of Healing Spells table are added to the spell list of your spellcasting class. <b>Mark of Healing Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:cure-wounds Cure Wounds], [*http:</i>dnd5e.wikidot.com/spell:healing-word Healing Word] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:lesser-restoration Lesser Restoration], [*http:</i>dnd5e.wikidot.com/spell:prayer-of-healing Prayer of Healing] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:aura-of-vitality Aura of Vitality], [*http:</i>dnd5e.wikidot.com/spell:mass-healing-word Mass Healing Word] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:aura-of-purity Aura of Purity], [*http:</i>dnd5e.wikidot.com/spell:aura-of-life Aura of Life] || || 5th || [*http://dnd5e.wikidot.com/spell:greater-restoration Greater Restoration] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Halfling Mark Of Hospitality (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Ever Hospitable","Innkeeper's Magic","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If you're a halfling with the Mark of Hospitality, you have this subrace, with the following traits.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Ever Hospitable.","entry":"Whenever you roll a Charisma (Persuasion) check or an ability check involving Brewer's Tools or Cook's Utensils, roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Innkeeper's Magic.","entry":"You know the [*http:<i>dnd5e.wikidot.com/spell:prestidigitation Prestidigitation ] cantrip. You can also cast [*http:</i>dnd5e.wikidot.com/spell:purify-food-and-drink Purify Food and Drink] and [*http://dnd5e.wikidot.com/spell:unseen-servant Unseen Servant] with this trait. Once you cast either spell with this trait, you can't cast that spell again until you finish a long rest. Charisma is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class features, the spells on the Mark of Hospitality Spells table are added to the spell list of your spellcasting class. <b>Mark of Hospitality Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:goodberry Goodberry], [*http:</i>dnd5e.wikidot.com/spell:sleep Sleep] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:aid Aid], [*http:</i>dnd5e.wikidot.com/spell:calm-emotions Calm Emotions] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:create-food-and-water Create Food and Water], [*http:</i>dnd5e.wikidot.com/spell:leomunds-tiny-hut Leomund's Tiny Hut] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:aura-of-purity Aura of Purity], [*http:</i>dnd5e.wikidot.com/spell:mordenkainens-private-sanctum Mordenkainen's Private Sanctum] || || 5th || [*http://dnd5e.wikidot.com/spell:hallow Hallow] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Halfling (PHB)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":25},"ability":[],"languages":[{"common":true},{"halfling":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Lucky","Brave","Nimble","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Age.","entry":"A halfling reaches adulthood at the age of 20 and generally lives into the middle of his or her second century."},{"type":"item","name":"Alignment.","entry":"Most halflings are lawful good. As a rule, they are good-hearted and kind, hate to see others in pain, and have no tolerance for oppression. They are also very orderly and traditional, leaning heavily on the support of their community and the comfort of the old ways."},{"type":"item","name":"Size.","entry":"Halflings average about 3 feet tall and weigh about 40 pounds. Your size is small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 25 feet."},{"type":"item","name":"Lucky.","entry":"When you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die. You must use the new result, even if it is a 1."},{"type":"item","name":"Brave.","entry":"You have advantage on saving throws against being frightened."},{"type":"item","name":"Nimble.","entry":"You can move through the space of any creature that is of a size larger than yours."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Halfling."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Stout Halfling (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Stout Resilience"],"entries":[{"type":"text","content":"<i>**//As a stout halfling, you're hardier than average and have some resistance to poison. Some say that stouts have dwarven blood. In the Forgotten Realms, these halflings are called stronghearts, and they're most common in the south.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Stout Resilience.","entry":"You have advantage on saving throws against poison, and you have resistance to poison damage."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Harengon (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Hare-Trigger","Leporine Senses","Lucky Footwork","Rabbit Hop","Languages"],"entries":[{"type":"text","content":"<i>**//Harengons originated in the Feywild, where they spoke Sylvan and embodied the spirit of freedom and travel. In time, these rabbitfolk hopped into other worlds, bringing the fey realm’s exuberance with them and learning new languages as they went.//**</i> <i>**//Harengons are bipedal, with the characteristic long feet of the rabbits they resemble and fur in a variety of colors. They share the keen senses and powerful legs of leporine creatures and are full of energy, like a wound-up spring. Harengons are blessed with a little fey luck, and they often find themselves a few fortunate feet away from dangers during adventures.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Hare-Trigger.","entry":"You can add your proficiency bonus to your initiative rolls."},{"type":"item","name":"Leporine Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Lucky Footwork.","entry":"When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're prone or your speed is 0."},{"type":"item","name":"Rabbit Hop.","entry":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Harengon (WBW)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Life Span","Size","Speed","Hare-Trigger","Leporine Senses","Lucky Footwork","Rabbit Hop"],"entries":[{"type":"text","content":"<i>**//Harengons originated in the Feywild, where they spoke Sylvan and embodied the spirit of freedom and travel. In time, these rabbitfolk hopped into other worlds, bringing the fey realm's exuberance with them and learning new languages as they went.//**</i> <i>**//Harengons are bipedal, with the characteristic long feet of the rabbits they resemble and fur in a variety of colors. They share the keen senses and powerful legs of leporine creatures and are full of energy, like a wound-up spring. Harengons are blessed with a little fey luck, and they often find themselves a few fortunate feet away from dangers during adventures.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Life Span.","entry":"Harengons have a life span of about a century."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Hare-Trigger.","entry":"You can add your proficiency bonus to your initiative rolls."},{"type":"item","name":"Leporine Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Lucky Footwork.","entry":"When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're prone or your speed is 0."},{"type":"item","name":"Rabbit Hop.","entry":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hexblood (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Darkvision","Fey Resilience","Hex Magic","Magic Token","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Type.","entry":"Fey and Humanoid"},{"type":"item","name":"Size.","entry":"Medium or Small (choose when you gain this lineage)"},{"type":"item","name":"Speed.","entry":"30 feet"},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light."},{"type":"item","name":"Fey Resilience.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Hex Magic.","entry":"You can cast the Disguise Self and Hex spells with this trait. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you gain this lineage). Once you cast either of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using any spells slots you have."},{"type":"item","name":"Magic Token.","entry":"As an action, you can harmlessly pull out one of your nails, a tooth, or a lock of hair. This token is imbued with magic until you finish a long rest. While the token is imbued in this way, you can use an action to send a telepathic message to the creature holding or carrying the token, as long as you are on the same plane of existence and are within 10 miles of it. The message can contain up to twenty-five words. * In addition, while you are within 10 miles of the token, you can use an action to enter a trance for 1 minute, during which you can see and hear from the token as if you were located where it is. While you are using your senses at the token’s location, you are blinded and deafened in regard to your own surroundings. Afterward, the token is harmlessly destroyed. * Once you create a token using this feature, you can’t do so again until you finish a long rest, at which point your missing part regrows."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hexblood (VRGR)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Size","Speed","Ancestral Legacy","Darkvision","Eerie Token","//Telepathic Message.//","//Remote Viewing.//","Hex Magic"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or increase three different ability scores by 1. If you are replacing your race with this lineage, replace any Ability Score Increase you previously had with this."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. If you are replacing your race with this lineage, you retain any languages you had and gain no new languages."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this lineage."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet"},{"type":"item","name":"Ancestral Legacy.","entry":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. * If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."},{"type":"item","name":"Eerie Token.","entry":"As a bonus action, you can harmlessly remove a lock of your hair, one of your nails, or one of your teeth. This token is imbued with magic until you finish a long rest. While the token is imbued this way, you can take these actions:"},{"type":"item","name":"//Telepathic Message.//.","entry":"As an action, you can send a telepathic message to the creature holding or carrying the token, as long as you are within 10 miles of it. The message can contain up to twenty-five words."},{"type":"item","name":"//Remote Viewing.//.","entry":"If you are within 10 miles of the token, you can enter a trance as an action. The trance lasts for 1 minute, but it ends early if you dismiss it (no action required) or are incapacitated. During this trance, you can see and hear from the token as if you were located where it is. While you are using your senses at the token's location, you are blinded and deafened in regard to your own surroundings. When the trance ends, the token is harmlessly destroyed. * Once you create a token using this feature, you can't do so again until you finish a long rest, at which point your missing part regrows."},{"type":"item","name":"Hex Magic.","entry":"You can cast the Disguise Self and Hex spells with this trait. Once you cast either of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose the ability when you gain this lineage)."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hobgoblin (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fey Ancestry","Fey Gift","Hospitality","Passage","Spite","Fortune from the Many","Languages"],"entries":[{"type":"text","content":"<i>**//Hobgoblins trace their origins to the ancient courts of the Feywild, where they first appeared with their goblin and bugbear kin. Many of them were driven from the Feywild by the conquering god Maglubiyet, who marshaled them as soldiers, but the fey realm left its mark; wherever they are in the multiverse, they continue to channel an aspect of the Feywild’s rule of reciprocity, which creates a mystical bond between the giver and the receiver of a gift.//**</i> <i>**//On some worlds, such bonds lead hobgoblins to form communities with deep ties to one another. In Eberron and the Forgotten Realms, vast hobgoblin legions have emerged, with ranks of devoted soldiers famed for their unity.//**</i> <i>**//Hobgoblins are generally taller than their goblin cousins but not quite as big as bugbears. They have curved, pointed ears and noses that turn bright red or blue during displays of emotion.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered a goblinoid for any prerequisite or effect that requires you to be a goblinoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Fey Gift.","entry":"You can use this trait to take the Help action as a bonus action, and you can do so a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest. * Starting at 3rd level, choose one of the options below each time you take the Help action with this trait:"},{"type":"item","name":"Hospitality.","entry":"You and the creature you help each gain a number of temporary hit points equal to 1d6 plus your proficiency bonus."},{"type":"item","name":"Passage.","entry":"You and the creature you help each increase your walking speeds by 10 feet until the start of your next turn."},{"type":"item","name":"Spite.","entry":"Until the start of your next turn, the first time the creature you help hits a target with an attack roll, that target has disadvantage on the next attack roll it makes within the next minute."},{"type":"item","name":"Fortune from the Many.","entry":"If you miss with an attack roll or fail an ability check or a saving throw, you can draw on your bonds of reciprocity to gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +3). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hobgoblin of the Feywild (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Fey Ancestry","Fey Gift","Hospitality","Passage","Spite","Fortune from the Many","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Fey Gift.","entry":"You can use this trait to take the Help action as a bonus action, and you can do so a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest. Starting at 3rd level, choose one of the options below each time you take the Help action, whether as a bonus action or an action:"},{"type":"item","name":"Hospitality.","entry":"You and the target of your Help action each gain a number of temporary hit points equal to 1d6 plus your proficiency bonus."},{"type":"item","name":"Passage.","entry":"You and the target of your Help action each increase your walking speeds by 10 feet until the start of your next turn."},{"type":"item","name":"Spite.","entry":"Until the start of your next turn, the first time you or the target of your Help action hits a creature with an attack roll, that creature has disadvantage on the next attack roll that it makes within the next minute."},{"type":"item","name":"Fortune from the Many.","entry":"If you miss with an attack roll or fail an ability check or a saving throw, you can draw on your bonds of reciprocity to gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Hobgoblin (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Martial Training","Saving Face","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Hobgoblins mature at the same rate as humans and have lifespans similar in length to theirs."},{"type":"item","name":"Alignment.","entry":"Hobgoblin society is built on fidelity to a rigid, unforgiving code of conduct. As such, they tend toward lawful evil."},{"type":"item","name":"Size.","entry":"Hobgoblins are between 5 and 6 feet tall and weigh between 150 and 200 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Martial Training.","entry":"You are proficient with two martial weapons of your choice and with light armor."},{"type":"item","name":"Saving Face.","entry":"Hobgoblins are careful not to show weakness in front of their allies, for fear of losing status. If you miss with an attack roll or fail an ability check or a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). Once you use this trait, you can't use it again until you finish a short or long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Gavony Human (Innistrad)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase"],"entries":[{"type":"text","content":"<i>**//Whether safe behind the walls of the High City of Thraben or out in the moors with little more than shuttered windows, barred doors, and grim determination to stand against the horrors of the night, the humans of Gavony are the most well-rounded people of Innistrad.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your ability scores each increase by 1."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Keldon Human (Dominaria)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Languages","Natural Athlete","Keldon Resilience","Icehaven Born"],"entries":[{"type":"text","content":"<i>**//The people of Keld are human, but they are like no other humans anywhere. Nearly all adults stand over six feet tall, and heights above seven feet are not uncommon. They are massively muscled and have gray skin, ranging from an ashy gray-white to a deeper bluegray. The typical Keldon’s hairline points sharply down in the middle of the forehead and at either temple, but recedes elsewhere — sometimes dramatically. Keldons are remarkably resistant to the cold of their homeland, baring skin even in near-freezing temperatures without discomfort.//**</i> <i>**//Keldons value self-reliance, strength, and courage above all else. Anything that is the product of their own labor is a fine thing. Anything else is treated with a healthy dose of skepticism. At best, they are a proud, pragmatic, passionate people, and their loyalty is fierce once earned. At worst, they can be reckless, hot-tempered, and violent — and no small number of Keldons still consider these qualities virtues rather than vices.//**</i> <i>**//The humans of Keld have the following traits, which replace the standard human traits presented in the// Player’s Handbook.**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Keldons reach adulthood in their late teens and live less than a century."},{"type":"item","name":"Alignment.","entry":"Keldons tend toward chaotic alignments, and many walk a fine line between good and evil."},{"type":"item","name":"Size.","entry":"Keldons are taller and heavier than the human norms of other cultures, standing almost universally above 6 feet tall and reaching heights above 7 feet. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Keldon."},{"type":"item","name":"Natural Athlete.","entry":"You have proficiency in the Athletics skill."},{"type":"item","name":"Keldon Resilience.","entry":"You have proficiency in Strength saving throws."},{"type":"item","name":"Icehaven Born.","entry":"You are naturally adapted to cold climates, as described in chapter 5 of the <i>Dungeon Master’s Guide</i>."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kessig Human (Innistrad)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Forest Folk","Fleet of Foot","Sure-Footed","Spring Attack"],"entries":[{"type":"text","content":"<i>**//For the Kessiger, life is work. Kessigers are farmers, millers, weavers, and stonemasons, living close to the land and working hard for every meal. This makes them self-reliant, pragmatic, and plainspoken.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity and Wisdom scores each increase by 1."},{"type":"item","name":"Forest Folk.","entry":"You have proficiency in the Survival skill."},{"type":"item","name":"Fleet of Foot.","entry":"Your base walking speed is 40 feet."},{"type":"item","name":"Sure-Footed.","entry":"When you use the Dash action, difficult terrain doesn’t cost you extra movement on that turn."},{"type":"item","name":"Spring Attack.","entry":"When you make a melee attack against a creature, you don’t provoke opportunity attacks from that creature for the rest of your turn, whether you hit or not."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human Mark Of Finding (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Darkvision","Hunter's Intuition","Finder's Magic","Languages","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your Human has the Mark of Finding, replace all Racial Traits found in the// Player's Handbook //with these, except for Age, Alignment, Size, and Speed.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60ft. of you as if it were bright light, and in darkness as if it were dim light. You can't discern colors in darkness, only shades of grey."},{"type":"item","name":"Hunter's Intuition.","entry":"Whenever you make a Wisdom (Perception) or a Wisdom (Survival) check, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Finder's Magic.","entry":"You can cast the [*http:<i>dnd5e.wikidot.com/spell:hunters-mark Hunter's Mark] spell with this trait. Starting at 3rd level, you can also cast the [*http:</i>dnd5e.wikidot.com/spell:locate-object Locate Object] spell with it. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Wisdom is your Spellcasting Ability for these spells."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Goblin."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Finding Spells table are added to the spell list of your Spellcasting class. <b>Mark of Finding Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:Faerie-Fire Faerie Fire], [*http:</i>dnd5e.wikidot.com/spell:longstrider Longstrider] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:locate-animals-or-plants Locate Animals or Plants], [*http:</i>dnd5e.wikidot.com/spell:locate-object Locate Object] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:clairvoyance Clairvoyance], [*http:</i>dnd5e.wikidot.com/spell:speak-with-plants Speak With Plants] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:divination Divination], [*http:</i>dnd5e.wikidot.com/spell:locate-creature Locate Creature] || || 5th || [*http://dnd5e.wikidot.com/spell:commune-with-nature Commune With Nature] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human Mark Of Handling (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Wild Intuition","Primal Connection","The Bigger They Are","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your human character has the Mark of Handling, the following traits replace the human's Ability Score Increase trait found in the Player's Handbook//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2, and one other Ability Score of your choice increases by 1."},{"type":"item","name":"Wild Intuition.","entry":"Whenever you make a Wisdom (Animal Handling) or a Intelligence (Nature) check, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Primal Connection.","entry":"You can cast the [*http:<i>dnd5e.wikidot.com/spell:animal-friendship Animal Friendship] spell and the [*http:</i>dnd5e.wikidot.com/spell:speak-with-animals Speak With Animals] with this trait, requiring no material components. Once you cast either spell with this trait, you can't cast that spell again until you finish a Long Rest. Wisdom is your Spellcasting Ability for these spells."},{"type":"item","name":"The Bigger They Are.","entry":"Starting at 3rd level, you can target a Beast or a Monstrosity when you cast [*http:<i>dnd5e.wikidot.com/spell:animal-friendship Animal Friendship] or [*http:</i>dnd5e.wikidot.com/spell:speak-with-animals Speak With Animals], provided that the creature's intelligence is 3 or lower."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Handling Spells table are added to the spell list of your Spellcasting class. <b>Mark of Handling Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:animal-friendship Animal Friendship], [*http:</i>dnd5e.wikidot.com/spell:speak-with-animals Speak With Animals] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:beast-sense Beast Sense], [*http:</i>dnd5e.wikidot.com/spell:calm-emotions Calm Emotions] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:beacon-of-hope Beacon of Hope], [*http:</i>dnd5e.wikidot.com/spell:conjure-animals Conjure Animals] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:aura-of-life Aura of Life], [*http:</i>dnd5e.wikidot.com/spell:dominate-beast Dominate Beast] || || 5th || [*http://dnd5e.wikidot.com/spell:awaken Awaken] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human Mark Of Making (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Artisan's Intuition","Artisan's Gift","Spellsmith","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your human character has the Mark of Making, the following traits replace the human's Ability Score Increase trait found in the Player's Handbook//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2, and one other Ability Score of your choice increases by 1."},{"type":"item","name":"Artisan's Intuition.","entry":"Whenever you make an Intelligence (Arcana) or an Ability Check involving Artisan's Tools, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Artisan's Gift.","entry":"You gain proficiency in one type of Artisan's Tools of your choice."},{"type":"item","name":"Spellsmith.","entry":"You learn the [*http:<i>dnd5e.wikidot.com/spell:mending Mending] cantrip. You can also cast the [*http:</i>dnd5e.wikidot.com/spell:magic-weapon Magic Weapon] spell with this trait. When you do so, the spell lasts for 1 hour and doesn't require concentration. Once you cast this spell with this trait, you can't cast that spell again until you finish a Long Rest. Intelligence is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Making Spells table are added to the spell list of your Spellcasting class. <b>Mark of Making Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:identify Identify], [*http:</i>dnd5e.wikidot.com/spell:tensers-floating-disk Tenser's Floating Disk] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:continual-flame Continual Flame], [*http:</i>dnd5e.wikidot.com/spell:magic-weapon Magic Weapon] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:conjure-barrage Conjure Barrage], [*http:</i>dnd5e.wikidot.com/spell:elemental-weapon Elemental Weapon] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:fabricate Fabricate], [*http:</i>dnd5e.wikidot.com/spell:stone-shape Stone Shape] || || 5th || [*http://dnd5e.wikidot.com/spell:creation Creation] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human Mark Of Passage (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Courier's Speed","Intuitive Motion","Magical Passage","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your human character has the Mark of Passage, the following traits replace the human's Ability Score Increase trait found in the Player's Handbook//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and one other Ability Score of your choice increases by 1."},{"type":"item","name":"Courier's Speed.","entry":"You gain a base walking speed of 35ft."},{"type":"item","name":"Intuitive Motion.","entry":"Whenever you make an Dexterity (Acrobatics) or an Ability Check involving operating or maintaining a Land Vehicle, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Magical Passage.","entry":"You can cast the [*http://dnd5e.wikidot.com/spell:misty-step Misty Step] spell with this trait. Once you cast this spell with this trait, you can't cast that spell again until you finish a Long Rest. Dexterity is your Spellcasting Ability for these spells."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Passage Spells table are added to the spell list of your Spellcasting class. <b>Mark of Passage Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:expeditious-retreat Expeditious Retreat], [*http:</i>dnd5e.wikidot.com/spell:jump Jump] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:misty-step Misty Step], [*http:</i>dnd5e.wikidot.com/spell:pass-without-trace Pass Without Trace] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:blink Blink], [*http:</i>dnd5e.wikidot.com/spell:phantom-steed Phantom Steed] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:dimension-door Dimension Door], [*http:</i>dnd5e.wikidot.com/spell:freedom-of-movement Freedom of Movement] || || 5th || [*http://dnd5e.wikidot.com/spell:teleportation-circle Teleportation Circle] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human Mark Of Sentinel (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Sentinel's Intuition","Guardian's Shield","Vigilant Guardian","Spells of the Mark"],"entries":[{"type":"text","content":"<i>**//If your human character has the Mark of Sentinel, the following traits replace the human's Ability Score Increase trait found in the Player's Handbook//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Sentinel's Intuition.","entry":"Whenever you make an Wisdom (Insight) or a Wisdom (Perception) check, you can roll a d4 and add the number rolled to the total ability check."},{"type":"item","name":"Guardian's Shield.","entry":"You can cast the [*http://dnd5e.wikidot.com/spell:shield Shield] spell with this trait. Once you cast this spell with this trait, you can't cast that spell again until you finish a Long Rest. Wisdom is your Spellcasting Ability for these spells."},{"type":"item","name":"Vigilant Guardian.","entry":"Once a creature that you can see within 5ft of you is hit with an attack roll, you can use your reaction to swap places with the creature, and you are hit by the attack instead. Once you use this trait, you can't do so again until you finish a long rest."},{"type":"item","name":"Spells of the Mark.","entry":"If you have the Spellcasting or Pact Magic class feature, the spells on the Mark of Sentinel Spells table are added to the spell list of your Spellcasting class. <b>Mark of Sentinel Spells</b> ||~ Spell Level ||~ Spell || || 1st || [*http:<i>dnd5e.wikidot.com/spell:compelled-duel Compelled Duel], [*http:</i>dnd5e.wikidot.com/spell:shield-of-faith Shield of Faith] || || 2nd || [*http:<i>dnd5e.wikidot.com/spell:warding-bond Warding Bond], [*http:</i>dnd5e.wikidot.com/spell:zone-of-truth Zone of Truth] || || 3rd || [*http:<i>dnd5e.wikidot.com/spell:counterspell Counterspell], [*http:</i>dnd5e.wikidot.com/spell:protection-from-energy Protection From Energy] || || 4th || [*http:<i>dnd5e.wikidot.com/spell:death-ward Death Ward], [*http:</i>dnd5e.wikidot.com/spell:guardian-of-faith Guardian of Faith] || || 5th || [*http://dnd5e.wikidot.com/spell:bigbys-hand Bigby's Hand] ||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Nephalia Human (Innistrad)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Breadth of Knowledge"],"entries":[{"type":"text","content":"<i>**//Beneath an ever-present shroud of fog billowing in from the sea, the people of Nephalia maintain a semblance of normalcy, buying and selling goods from across Innistrad in their bustling markets, setting out to sea in tiny fishing boats, or tilling the soggy earth in waterlogged fields.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence and Charisma scores each increase by 1."},{"type":"item","name":"Breadth of Knowledge.","entry":"You gain proficiency in any combination of four skills or with four tools of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Human (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"elvish":true},{"dwarvish":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your ability scores each increase by 1."},{"type":"item","name":"Age.","entry":"Humans reach adulthood in their late teens and live less than a century."},{"type":"item","name":"Alignment.","entry":"Humans tend toward no particular alignment. The best and the worst are found among them."},{"type":"item","name":"Size.","entry":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: Orc curses, Elvish musical expressions, Dwarvish military phrases, and so on."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Stensia Human (Innistrad)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Daunting","Tough"],"entries":[{"type":"text","content":"<i>**//Countless generations of hardship and proximity to the vampire strongholds—leading to lost children and neighbors—have taught Stensians to guard their hearts. They are proud and fervent in their beliefs but seem brusque or even cold to the people of other provinces.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength and Constitution scores each increase by 1."},{"type":"item","name":"Daunting.","entry":"You have proficiency in the Intimidation skill."},{"type":"item","name":"Tough.","entry":"Your hit point maximum increases by 2, and it increases by 2 every time you gain a level."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Variant Human","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Skills","Feat"],"entries":[{"type":"text","content":"<i>**//If your campaign uses the optional feat rules from chapter 5 of the// Player's Handbook, //your Dungeon Master might allow these variant traits, all of which replace the human's// Ability Score Increase //trait.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Two different ability scores of your choice increase by 1."},{"type":"item","name":"Skills.","entry":"You gain proficiency in one skill of your choice."},{"type":"item","name":"Feat.","entry":"You gain one Feat of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kalashtar (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Dual Mind","Mental Discipline","Mind Link","Psychic Glamour","Severed from Dreams","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom and Charisma scores both increase by 1. In addition, one ability score of your choice increases by 1."},{"type":"item","name":"Age.","entry":"Kalashtar develop physically at the same rate as humans do and have similar lifespans."},{"type":"item","name":"Alignment.","entry":"The noble spirit tied to a kalashtar drives it toward lawful and good behavior. Most kalashtar combine strong self-discipline with compassion for all sentient beings, but some kalashtar resist the virtuous influence of their spirit."},{"type":"item","name":"Size.","entry":"Kalashtar are similar in build to humans, though they are typically a few inches taller. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Dual Mind.","entry":"When you make a Wisdom saving throw, you can use your reaction to gain advantage on the roll. You can use this trait immediately before or after you roll, but before any of the roll's effects occur."},{"type":"item","name":"Mental Discipline.","entry":"You have resistance to psychic damage."},{"type":"item","name":"Mind Link.","entry":"You can speak telepathically to any creature you can see within 60 feet of you. You don’t need to share a language with the creature for it to understand your telepathic messages, but the creature must be able to understand at least one language or be telepathic itself. * As a bonus action when you’re speaking telepathically to a creature, you can give that creature the ability to speak telepathically to you until the start of your next turn. To use this ability, the creature must be within 60 feet of you and be able to see you."},{"type":"item","name":"Psychic Glamour.","entry":"Choose one of the following skills: Insight, Intimidation, Performance, or Persuasion. You have advantage on all ability checks you make with that skill."},{"type":"item","name":"Severed from Dreams.","entry":"Kalashtar sleep, but they don’t connect to the plane of dreams as other creatures do. Instead, their minds draw from the memories of their otherworldly spirit while they sleep. As such, you are immune to magical spells and effects that require you to dream, like the Dream spell, but not to spells and effects that put you to sleep, like the Sleep spell."},{"type":"item","name":"Languages.","entry":"You can speak, read and write Common, Quori, and one other language of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kender (Revised UA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Fearless","Kender Curiosity","Taunt","Languages"],"entries":[{"type":"text","content":"<i>**//During the mythical origins of Krynn, Reorx, god of craft, indulged in an age of unfettered creation. Many peoples sprang from his divine forge, but not all among them remained as the god created them. Altered by unbridled magic, a group of gnomes were transformed and gifted almost supernatural curiosity and fearlessness. These were the first kender.//**</i> <i>**//Originating on the world of Krynn, kender are diminutive Humanoids that look like humans with pointed ears and diverse appearances. Kender have a supernatural curiosity that drives them to adventure. Due to this inquisitiveness, many kender find themselves falling through portals to other planes and worlds.//**</i> <i>**//Kender sometimes amass impressive collections of curiosities. Some might collect mundane knickknacks or relics from magical sites, while others might become professional thieves.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Fearless.","entry":"You are immune to the frightened condition."},{"type":"item","name":"Kender Curiosity.","entry":"Thanks to the mystical origin of your people, you gain proficiency with one of the following skills of your choice: Insight, Investigation, Sleight of Hand, Stealth, or Survival."},{"type":"item","name":"Taunt.","entry":"You have an extraordinary ability to fluster creatures. As a bonus action, you can unleash a string of provoking words at a creature within 60 feet of you that can hear and understand you. The target must succeed on a Wisdom saving throw or it has disadvantage on attack rolls against targets other than you until the start of your next turn. The DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race). You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kender (UA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Brave","Kender Ace","Taunt","Languages"],"entries":[{"type":"text","content":"<i>**//Native to the world of Krynn, Kender are diminutive\\t Humanoids that look like humans with pointed ears and diverse appearances. Kender have a supernatural curiosity that drives them on to adventures big and small. This curiosity is said to be connected to the whimsical magic of the Feywild, that some believe kender have a high affinity for. Due to their curiosity, many kender have found themselves falling through gates and portals to other planes and worlds.//**</i> <i>**//Unknown to most mortals, a magical phenomenon surrounds a kender. Spurred by their curiosity and love for trinkets, curios, and keepsakes, a kender’s pouches or\\tpockets will be\\tmagically filled with these objects. No one knows where these objects come from, not even the kender. This has led many kender to be mislabeled as thieves when they fish these items out of their pockets//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Brave.","entry":"You have advantage on saving throws you make to avoid or end the frightened condition on yourself."},{"type":"item","name":"Kender Ace.","entry":"Starting at 3rd level, you possess a magical ability to pull an item out of a bag or another container; as a bonus action, you can reach into a container you’re carrying and roll on the Kender Aces table to determine what item you pull out. The object glimmers softly and disappears after 1 hour. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. ||||~ Kender Aces |||| ||~ d6 ||~ Item || || 1 || 5d6 gold pieces || || 2 || 1 simple weapon of your choice that has the light property || || 3 || 1 item of your choice from the Adventuring Gear table in the <i>Player’s Handbook</i>. The item must cost no more than 1 gp and weigh no more than 1 lb. || || 4 || 1 random item from the Trinkets table in the <i>Player’s Handbook</i>. || || 5 || Your choice of a crowbar or a grappling hook || || 6 || 1 item of your choice from the Tools table in the <i>Player’s Handbook</i>. The item must cost no more than 10 gp. ||"},{"type":"item","name":"Taunt.","entry":"You have a supernatural ability to home in on a creature’s\\temotional raw nerves and craft a taunt that flusters that creature. As a bonus action, you can unleash a barrage of insults at a creature within 60 feet of you that can hear and understand you. The target must succeed on a Wisdom saving throw (DC equal to 8 + your proficiency bonus + your Charisma modifier), or it has disadvantage on attack rolls until the start of your next turn. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kenku (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Expert Duplication","Kenku Recall","Mimicry","Languages"],"entries":[{"type":"text","content":"<i>**//Feathered folk who resemble ravens, kenku are blessed with keen observation and supernaturally accurate memories. None of them can remember the origin of the first kenku, however, and they often joke that there are as many kenku origin stories as there are kenku. Some of them paint their genesis as a curse, being a flightless bird people doomed to mimic other people’s creations. Other kenku recite cryptic but beautiful poems about their advent being a blessed event in which they were sent into the multiverse to observe and catalog its many wonders.//**</i> <i>**//Whatever their true origin, kenku are most often found in the Shadowfell and the Material Plane, and they tend to have the coloration typical of ravens.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"Your size is Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Expert Duplication.","entry":"When you copy writing or craftwork produced by yourself or someone else, you have advantage on any ability checks you make to produce an exact duplicate."},{"type":"item","name":"Kenku Recall.","entry":"Thanks to your supernaturally good memory, you have proficiency in two skills of your choice. * Moreover, when you make an ability check using any skill in which you have proficiency, you can give yourself advantage on the check before rolling the d20. You can give yourself advantage in this way a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Mimicry.","entry":"You can accurately mimic sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations only with a successful Wisdom (Insight) check against a DC of 8 + your proficiency bonus + your Charisma modifier."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kenku (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"auran":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Expert Forgery","Kenku Training","Mimicry","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Kenku have shorter lifespans than humans. They reach maturity at about 12 years old and can live to 60."},{"type":"item","name":"Alignment.","entry":"Kenku are chaotic creatures, rarely making enduring commitments, and they care mostly for preserving their own hides. They are generally chaotic neutral in outlook."},{"type":"item","name":"Size.","entry":"Kenku are around 5 feet tall and weigh between 90 and 120 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Expert Forgery.","entry":"You can duplicate other creatures' handwriting and craftwork. You have advantage on all checks made to produce forgeries or duplicates of existing objects."},{"type":"item","name":"Kenku Training.","entry":"You are proficient in your choice of two of the following skills: Acrobatics, Deception, Stealth, and Sleight of Hand."},{"type":"item","name":"Mimicry.","entry":"You can mimic sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations with a successful Wisdom (Insight) check opposed by your Charisma (Deception) check."},{"type":"item","name":"Languages.","entry":"You can read and write Common and Auran, but you can speak only by using your Mimicry trait."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kobold (MPMM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Draconic Cry","Kobold Legacy","Craftiness","Defiance","Draconic Sorcery","Languages"],"entries":[{"type":"text","content":"<i>**//Some of the smallest draconic creatures in the multiverse, kobolds display their draconic ancestry in the glint of their scales and in their roars. Legends tell of the first kobolds emerging from the Underdark near the lairs of the earliest dragons. In some lands, kobolds serve chromatic or metallic dragons — even worshiping them as divine beings. In other places, kobolds know too well how dangerous those dragons can be and help others defend against draconic destruction.//**</i> <i>**//Whatever their relationship to dragons, kobold scales tend to be rust colored, although the occasional kobold sports a scale color more akin to that of a chromatic or a metallic dragon. A kobold’s cry can express a range of emotion: anger, resolve, elation, fear, and more. Regardless of the emotion expressed, their cry resonates with draconic power.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Draconic Cry.","entry":"As a bonus action, you let out a cry at your enemies within 10 feet of you. Until the start of your next turn, you and your allies have advantage on attack rolls against any of those enemies who could hear you. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Kobold Legacy.","entry":"Kobolds’ connection to dragons can manifest in unpredictable ways in an individual kobold. Choose one of the following legacy options for your kobold:"},{"type":"item","name":"Craftiness.","entry":"You have proficiency in one of the following skills of your choice: Arcana, Investigation, Medicine, Sleight of Hand, or Survival."},{"type":"item","name":"Defiance.","entry":"You have advantage on saving throws to avoid or end the frightened condition on yourself."},{"type":"item","name":"Draconic Sorcery.","entry":"You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kobold (UA)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Type","Size","Speed","Darkvision","Draconic Legacy","Draconic Roar"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or you increase three different scores by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Small."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Draconic Legacy.","entry":"The kobold connection to dragons can manifest in unpredictable ways in an individual kobold. Choose one of the following legacy options when you select this race: * You have advantage on saving throws to avoid or end the frightened condition on yourself. * You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race). * You can make unarmed strikes with your tail. When you hit with it, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Draconic Roar.","entry":"As a bonus action, you let out a draconic roar at your enemies within 10 feet of you. Until the end of your next turn, you and your allies have advantage on attack rolls against any of those enemies who could hear the roar. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Kobold (VGM)","source":"HB","edition":"classic","size":["S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"draconic":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Grovel, Cower, and Beg","Pack Tactics","Sunlight Sensitivity","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Age.","entry":"Kobolds reach adulthood at age 6 and can live up to 120 years but rarely do so."},{"type":"item","name":"Alignment.","entry":"Kobolds are fundamentally selfish, making them evil, but their reliance on the strength of their group makes them trend toward law."},{"type":"item","name":"Size.","entry":"Kobolds are between 2 and 3 feet tall and weigh between 25 and 35 pounds. Your size is Small."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Grovel, Cower, and Beg.","entry":"As an action on your turn, you can cower pathetically to distract nearby foes. Until the end of your next turn, your allies gain advantage on attack rolls against enemies within 10 feet of you that can see you. Once you use this trait, you can't use it again until you finish a short or long rest."},{"type":"item","name":"Pack Tactics.","entry":"You have advantage on an attack roll against a creature if at least one of your allies is within 5 feet of the creature and the ally isn't incapacitated."},{"type":"item","name":"Sunlight Sensitivity.","entry":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Draconic."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Lizardfolk (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Bite","Hold Breath","Hungry Jaws","Natural Armor","Nature's Intuition","Languages"],"entries":[{"type":"text","content":"<i>**//The saurian lizardfolk are thought by some sages to be distant cousins of dragonborn and kobolds. Despite their resemblance to those other scaled folk, however, lizardfolk are their own people and have lived on the worlds of the Material Plane since the worlds’ creation. Gifted by the gods with remarkable physical defenses and a mystical connection to the natural world, lizardfolk can survive with just their wits in situations that would be deadly for other folk. Because of that fact, many lizardfolk myths state that their people were placed by the gods in the Material Plane to guard its natural wonders.//**</i> <i>**//Lizardfolk have colorful scales and exhibit a wide array of scale patterns. Their individual facial features are as varied as those of lizards.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."},{"type":"item","name":"Bite.","entry":"You have a fanged maw that you can use to make unarmed strikes. When you hit with it, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Hold Breath.","entry":"You can hold your breath for up to 15 minutes at a time."},{"type":"item","name":"Hungry Jaws.","entry":"You can throw yourself into a feeding frenzy. As a bonus action, you can make a special attack with your Bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Natural Armor.","entry":"You have tough, scaly skin. When you aren’t wearing armor, your base AC is 13 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield’s benefits apply as normal while you use your natural armor."},{"type":"item","name":"Nature's Intuition.","entry":"Thanks to your mystical connection to nature, you gain proficiency with two of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Lizardfolk (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"draconic":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Bite","Cunning Artisan","Hold Breath","Hunter's Lore","Natural Armor","Hungry Jaws","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increase by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Lizardfolk reach maturity around age 14 and rarely live longer than 60 years."},{"type":"item","name":"Alignment.","entry":"Most lizardfolk are neutral. They see the world as a place of predators and prey, where life and death are natural processes. They wish only to survive, and prefer to leave other creatures to their own devices."},{"type":"item","name":"Size.","entry":"Lizardfolk are a little bulkier and taller than humans, and their colorful frills make them appear even larger. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet, and you have a swimming speed of 30 feet."},{"type":"item","name":"Bite.","entry":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Cunning Artisan.","entry":"As part of a short rest, you can harvest bone and hide from a slain beast, construct, dragon, monstrosity, or plant creature of size Small or larger to create one of the following items: a shield, a club, a javelin, or 1d4 darts or blowgun needles. To use this trait, you need a blade, such as a dagger, or appropriate artisan's tools, such as leatherworker's tools."},{"type":"item","name":"Hold Breath.","entry":"You can hold your breath for up to 15 minutes at a time."},{"type":"item","name":"Hunter's Lore.","entry":"You gain proficiency with two of the following skills of your choice: Animal Handling, Nature, Perception, Stealth, and Survival."},{"type":"item","name":"Natural Armor.","entry":"You have tough, scaly skin. When you aren't wearing armor, your AC is 13 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."},{"type":"item","name":"Hungry Jaws.","entry":"In battle, you can throw yourself into a vicious feeding frenzy. As a bonus action, you can make a special attack with your bite. If the attack hits, it deals its normal damage, and you gain temporary hit points (minimum of 1) equal to your Constitution modifier, and you can't use this trait again until you finish a short or long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Draconic."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Locathah (LR)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"aquan":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Natural Armor","Observant and Athletic","Leviathan Will","Limited Amphibiousness","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2 and your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"Locathah mature to adulthood by the age of 10 but have been known to live up to 80 years."},{"type":"item","name":"Alignment.","entry":"Most locathah are true neutral or have some aspect of neutrality in their alignment. They tend toward good, coming from a culture where compassion for the downtrodden is a commonality."},{"type":"item","name":"Size.","entry":"Locathah stand between 5 and 6 feet tall and average about 150 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet, and you have a swim speed of 30 feet."},{"type":"item","name":"Natural Armor.","entry":"You have tough, scaly skin. When you aren’t wearing armor, your AC is 12 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield’s benefits apply as normal while you use your natural armor."},{"type":"item","name":"Observant and Athletic.","entry":"You have proficiency in the Athletics and Perception skills."},{"type":"item","name":"Leviathan Will.","entry":"You have advantage on saving throws against being charmed, frightened, paralyzed, poisoned, stunned, or put to sleep."},{"type":"item","name":"Limited Amphibiousness.","entry":"You can breathe air and water, but you need to be submerged at least once every 4 hours to avoid suffocating."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Aquan and Common."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Merfolk Ixalan","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Amphibious","Languages","Subrace","Ability Score Increase","Mask of the Wild","Cantrip","Ability Score Increase","Lore of the Waters","Cantrip"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Age.","entry":"Merfolk mature at the same rate humans do and reach adulthood around the age of 20. They live considerably longer than humans, though, often reaching well over 100 years."},{"type":"item","name":"Alignment.","entry":"Most merfolk are neutral, living in close harmony with nature."},{"type":"item","name":"Size.","entry":"Merfolk are significantly taller than most humans, standing between seven and eight feet tall and averaging about 300 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet. You also have a swimming speed of 30 feet."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common (if it exists in your campaign), Merfolk and one additional language of your choice."},{"type":"item","name":"Subrace.","entry":"Merfolk are actually two separate subspecies. The green merfolk favor the land, walking among the trees and savoring the sunlight that filters through the leaves, while the blue merfolk are more at home in the waters of the Great River and the Inner Sea. * Green Merfolk * Green merfolk generally have yellow chests and pale green faces, shading to dark blues and purples on their backs and limbs. The patterns on their skin suggest the colors of the tree frogs common in the rain forest, as do their eyes of orange, lime green, or sky blue. Their fins are relatively short and thick. They climb trees with ease, move through undergrowth unhindered, and often wield magic to shape vines and branches to their will."},{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2."},{"type":"item","name":"Mask of the Wild.","entry":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Druid spell list. Wisdom is your spellcasting ability for it. * Blue Merfolk * Blue merfolk often have burgundy or magenta on their faces and chests, with lighter shades of blue and purple elsewhere. Their eyes are red, orange, or blue, and their long, thin, and elegant fins resemble scarves or veils of fine fabric. They swim easily, even upstream, and clamber over rocks and through rapids with ease. They prefer to dwell in shallow waters, but spend a fair amount of time on land as well."},{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2."},{"type":"item","name":"Lore of the Waters.","entry":"You gain proficiency in History and Nature."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Wizard spell list. Intelligence is your spellcasting ability for it."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Merfolk Zendikar","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Amphibious","Languages","Creeds","Ability Score Increase","Wind Creed Manipulation","Cantrip","Ability Score Increase","Water Creed Navigation","Cantrip","Ability Score Increase","Creed of the Trickster","Cantrip"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 1."},{"type":"item","name":"Age.","entry":"Merfolk mature at the same rate humans do and reach adulthood around the age of 20. They live considerably longer than humans, though, often reaching well over 100 years."},{"type":"item","name":"Alignment.","entry":"Most merfolk are neutral, though merfolk of the Emeria and Cosi creeds have chaotic leanings."},{"type":"item","name":"Size.","entry":"Merfolk are about the same size and build as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet. You also have a swimming speed of 30 feet."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Merfolk and one additional language of your choice."},{"type":"item","name":"Creeds.","entry":"The merfolk race is divided into three creeds, founded on the principles of Emeria (wind), Ula (water), and Cosi (the trickster). A merfolk isn’t born into a creed but chooses it upon reaching adulthood, and it is rare for a merfolk not to choose a creed. Merfolk of the wind and water creeds aren’t hostile to each other, but members of each creed regard the other creed with a vague disdain. Members of both those creeds regard the Cosi creed with suspicion and some degree of fear, and Cosi-creed adherents tend to keep their affiliation secret. Choose one of these creeds for your character. * Emeria (Wind) Creed * Merfolk who followed Emeria’s creed seek wisdom and truth in the Wind Realm, exploring the mystical forces—rather than natural causes—behind historical events. They are evasive and intentionally enigmatic in their interactions with others, and are often described as manipulative and deceptive."},{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2."},{"type":"item","name":"Wind Creed Manipulation.","entry":"You have proficiency in the Deception and Persuasion skills."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Druid spell list. Wisdom is your spellcasting ability for it. * Ula (Water) Creed * Ula-creed merfolk emphasize intellectual pursuits, stressing hard evidence and reason over passion. They are analytical scholars, chroniclers, explorers, and navigators who pride themselves on being blunt and straightforward."},{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2."},{"type":"item","name":"Water Creed Navigation.","entry":"You have proficiency with navigator’s tools and in the Survival skill."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Wizard spell list. Intelligence is your spellcasting ability for it. * Cosi Creed * No merfolk will openly admit to following the creed of the trickster, but those who do view Cosi as an ally who can grant them control over the chaotic forces of the world."},{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by an additional 1 (for a total of 2), and your Intelligence score increases by 1."},{"type":"item","name":"Creed of the Trickster.","entry":"You have proficiency in the Sleight of Hand and Stealth skills."},{"type":"item","name":"Cantrip.","entry":"You know one cantrip of your choice from the Bard spell list. Charisma is your spellcasting ability for it."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Minotaur (GGR)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Alignment","Size","Speed","Horns","Goring Rush","Hammering Horns","Imposing Presence","Languages"],"entries":[{"type":"text","content":"<i>**//The minotaurs of Ravnica are strong in body. dedication, and courage. They are at home on the battlefield, willing to fight for their various causes. They combine a burning fury in battle with keen tactics that make them excellent commanders as well as valuable shock troops.//**</i> <i>**//Minotaurs are barrel-chested humanoids with heads resembling those of bulls. Their horns range in size from about 1 foot long to great, curling weapons easily three times that length. They often ornament their horns with metal rings or sheathe them in metal to protect them from damage.//**</i> <i>**//Manes of shaggy fur extend down minotaurs' necks and powerful backs, and males have long tufts of hair on their chins and cheeks. Their legs end in heavy, cloven hooves. Minotaurs are born with long, tufted tails, but minotaurs of the Ordruun clan (and some others) have their tails docked as part of a coming-of-age ceremony; they find the heavy armor of the Boros legion much more comfortable without a long tail in the way.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Alignment.","entry":"Most minotaurs who join the Boros Legion lean toward lawful alignments, while those associated with the Cult of Rakdos or the Gruul Clans tend toward chaotic alignments."},{"type":"item","name":"Size.","entry":"Minotaurs average over 6 feet in height, and they have stocky builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Horns.","entry":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Goring Rush.","entry":"Immediately after you use the Dash action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."},{"type":"item","name":"Hammering Horns.","entry":"Immediately after you hit a creature with a melee attack as a part of the Attack action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."},{"type":"item","name":"Imposing Presence.","entry":"You have proficiency in one of the following skills of your choice: Intimidation or Persuasion."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Minotaur."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Minotaur Krynn (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Conqueror’s Virtue","Age","Alignment","Size","Speed","Horns","Goring Rush","Hammering Horns","Labyrinthine Recall","Sea Reaver","Languages"],"entries":[{"type":"text","content":"<i>**//In\\tthe\\tworld\\tof\\tKrynn,\\tthe\\tsetting\\tof\\tthe\\tDragonlance\\tsaga,\\tminotaurs\\tlive\\tin\\tan\\thonor‐based\\tsociety\\twhere\\tstrength\\tdetermines\\tpower\\tin\\tboth\\tthe\\tgladiatorial\\tarenas\\tand\\tin\\tdaily\\tlife.\\tAt\\thome\\ton\\tboth\\tland\\tand\\tsea,\\tthe\\tminotaurs\\tof\\tKrynn\\tare\\tferocious\\tsea\\traiders\\twho\\trank\\tas\\tthe\\tablest\\tand\\tmost\\tdangerous\\tsailors\\tin\\tthe\\tworld.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 1."},{"type":"item","name":"Conqueror’s Virtue.","entry":"From\\ta\\tyoung\\tage,\\tyou focused\\ton\\tone\\tof\\tthe\\tthree\\tvirtues\\tof\\tstrength, cunning,\\tor\\tintellect.\\tYour\\tchoice\\tof\\tyour Strength,\\tIntelligence,\\tor\\tWisdom\\tscore\\tincreases\\tby\\t1."},{"type":"item","name":"Age.","entry":"Minotaurs\\tenter\\tadulthood\\tat\\taround\\tthe age\\tof\\t17\\tand\\tcan\\tlive\\tup\\tto\\t150\\tyears."},{"type":"item","name":"Alignment.","entry":"Minotaurs\\tbelieve\\tin\\ta\\tstrict\\tcode of\\thonor,\\tand\\tthus\\ttend\\ttoward\\tlaw.\\tThey\\tare loyal\\tto\\tthe\\tdeath\\tand\\tmake\\timplacable\\tenemies,\\teven\\tas\\ttheir\\tbrutal\\tculture\\tand\\tdisdain\\tfor weakness\\tpush\\tthem\\ttoward\\tevil."},{"type":"item","name":"Size.","entry":"Minotaurs\\ttypically\\tstand\\twell\\tover\\t6\\tfeet tall\\tand\\tweigh\\tan\\taverage\\tof\\t300\\tpounds.\\tYour size\\tis\\tMedium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Horns.","entry":"You\\tare\\tnever\\tunarmed.\\tYou\\tare proficient\\twith\\tyour\\thorns,\\twhich\\tare\\ta\\tmelee weapon\\tthat\\tdeals\\t1d10\\tpiercing\\tdamage.\\tYour horns\\tgrant\\tyou\\tadvantage\\ton\\tall\\tchecks\\tmade\\tto\\tshove\\ta\\tcreature,\\tbut\\tnot\\tto\\tavoid\\tbeing\\tshoved\\tyourself."},{"type":"item","name":"Goring Rush.","entry":"When\\tyou\\tuse\\tthe\\tDash\\taction\\tduring\\tyour\\tturn,\\tyou\\tcan\\tmake\\ta\\tmelee\\tattack\\twith\\tyour\\thorns\\tas\\ta\\tbonus\\taction."},{"type":"item","name":"Hammering Horns.","entry":"When\\tyou\\tuse\\tthe\\tAttack action\\tduring\\tyour\\tturn\\tto\\tmake\\ta\\tmelee\\tattack,\\tyou\\tcan\\tattempt\\tto\\tshove\\ta\\tcreature\\twith\\tyour\\thorns\\tas\\ta\\tbonus\\taction.\\tYou\\tcannot\\tuse\\tthis shove\\tattempt\\tto\\tknock\\ta\\tcreature\\tprone."},{"type":"item","name":"Labyrinthine Recall.","entry":"You\\tcan\\tperfectly\\trecall\\tany\\tpath\\tyou\\thave\\ttraveled."},{"type":"item","name":"Sea Reaver.","entry":"You\\tgain\\tproficiency\\twith\\tnavigator’s\\ttools\\tand\\tvehicles\\t(water)."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Minotaur."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Minotaur (MOT)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Horns","Goring Rush","Hammering Horns","Imposing Presence","Languages"],"entries":[{"type":"text","content":"<i>**//The minotaurs who dwell in the badlands of Phoberos and the remote polis of Skophos are caught between two worlds. Some follow the dark god Mogis, who has tyrannized them for ages untold and shown them a trail of slaughter that is all many minotaurs have ever known. Others, though, have emerged from this bloody path and found a world that welcomes those who pursue their own destinies and heroic callings.//**</i> <i>**//Minotaurs are barrel-chested humanoids with heads resembling those of bulls. Their horns range in size from about 1 foot long to great, curling weapons easily three times that length. Theros minotaurs often carve their horns to sharpen their edges, etch symbols of power into them, or sheathe them in bronze to prevent them from shattering during battle.//**</i> <i>**//Thick hair extends down minotaurs' necks and powerful backs, and some have long patches of hair on their chins and cheeks. Their legs end in heavy, cloven hooves, and they have long, tufted tails. Minotaur priests often adorn themselves with sacred items, be they trophies from fallen foes, keepsakes from their homeland, or naturally occurring marks of their god's favor.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Minotaurs mature and age at about the same rate as humans."},{"type":"item","name":"Alignment.","entry":"Minotaurs who leave the walls of Skophos have the opportunity to be free of its culture and pursue chaotic alignments, while those who remain within the polis and its tyrannical regime tend toward lawful alignments."},{"type":"item","name":"Size.","entry":"Minotaurs average over 6 feet in height, and they have stocky builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Horns.","entry":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Goring Rush.","entry":"Immediately after you use the Dash action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."},{"type":"item","name":"Hammering Horns.","entry":"Immediately after you hit a creature with a melee attack as a part of the Attack action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."},{"type":"item","name":"Imposing Presence.","entry":"You have proficiency in one of the following skills of your choice: Intimidation or Persuasion."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Minotaur."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Minotaur (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Horns","Goring Rush","Hammering Horns","Labyrinthine Recall","Languages"],"entries":[{"type":"text","content":"<i>**//Minotaurs are barrel-chested humanoids with heads resembling those of bulls. Blessed with a supernaturally strong sense of direction, minotaurs make great navigators. Some sages believe minotaurs were first created by the Lady of Pain to patrol the magical mazes that she uses to trap her foes.//**</i> <i>**//Minotaur horns range in size from about 1 foot long to easily three times that length. Minotaurs often carve their horns to sharpen their edges, etch symbols of power into them, or sheathe them in bronze to prevent them from shattering during battle.//**</i> <i>**//Thick hair extends down minotaurs’ necks and powerful backs, and some have long patches of hair on their chins and cheeks. Their legs end in heavy, cloven hooves, and they have long, tufted tails.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Horns.","entry":"You have horns that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier piercing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Goring Rush.","entry":"Immediately after you take the Dash action on your turn and move at least 20 feet, you can make one melee attack with your Horns as a bonus action."},{"type":"item","name":"Hammering Horns.","entry":"Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to push that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."},{"type":"item","name":"Labyrinthine Recall.","entry":"You always know which direction is north, and you have advantage on any Wisdom (Survival) check you make to navigate or track."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Orc (EGW)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Aggressive","Powerful Build","Primal Intuition","Languages"],"entries":[{"type":"text","content":"<i>**//Orcs are one of Exandria's youngest races, and are said to have been born from elves seared by the blood of Gruumsh, the Ruiner, when Corellon pierced the orc god's eye on the field of battle. For long years, orcs were feared as mindless abominations, drawn to slaughter like moths to flame.//**</i> <i>**//Stories tell of how the blood of the Ruiner flows in the veins of all orcs, driving them to commit acts of terrible violence and anger. Orcs call this fury// hgar'Gruum//, or the curse of ruin, and use it to refer to everything from battle rage to a bad temper. Half-orcs are said to have inherited the blood of the Ruiner, and to carry the same bloodlust and fury that orcs do.//**</i> <i>**//Orcs and half-orcs do feel a certain pull toward violence and anger. But the simple truth is that there is no curse of ruin. No supernatural power drives orcs to kill. Rather, they are simply victims of the same selfish, violent impulses that corrupt all mortal beings.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2 and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Orcs reach adulthood at age 16 and live up to 80 years."},{"type":"item","name":"Alignment.","entry":"Orcs fear the curse of ruin that is said to plague their race, and tend strongly toward either chaos (accepting their fate), or toward law (rejecting it)."},{"type":"item","name":"Size.","entry":"Orcs stand easily 8 feet tall and corded with powerful muscles, weighing up to 280 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Aggressive.","entry":"As a bonus action, you can move up to your speed toward an enemy of your choice that you can see or hear. You must end this move closer to the enemy than you started."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Primal Intuition.","entry":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Nature, Perception, and Survival."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Orc."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Orc (E:RLW)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Aggressive","Powerful Build","Primal Intuition","Languages"],"entries":[{"type":"text","content":"<i>**//Thousands of years before humans came to Khorvaire, the land was dominated by wild orcs and goblinoids of the Dhakaani Empire. The goblin empire scattered the orc tribes and forced them into harsh and unwanted lands: the swamps of the Shadow Marches, the Demon Wastes, and the depths of the Ironroot Mountains. But in the Shadow Marches, the orcs learned the secrets of druidic magic from the dragon Vvaraak, becoming the first of the Gatekeepers. With the invasion of the alien daelkyr from Xoriat, the Gatekeepers put the dragon's teaching to the test, creating magical seals that bound the daelkyr in the depths of Khyber and protected Eberron against further incursion from the plane of madness.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Orcs reach adulthood at age 12 and live up to 50 years."},{"type":"item","name":"Alignment.","entry":"The orcs of Eberron are a passionate people, given to powerful emotion and deep faith. They are generally chaotic, but can be any alignment."},{"type":"item","name":"Size.","entry":"Orcs are usually over 6 feet tall and weigh between 230 and 280 pounds. Your size is Medium. To set your height and weight randomly, start with rolling a size modifier. * Size modifier = 2d8 * Height = 5 feet + 4 inches + your size modifier in inches * Weight in pounds = 175 + (2d6 x your size modifier)"},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Aggressive.","entry":"As a bonus action, you can move up to your speed toward an enemy of your choice that you can see or hear. You must end this move closer to the enemy than you started."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Primal Intuition.","entry":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Nature, Perception, and Survival."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Orc."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Orc (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Adrenaline Rush","Darkvision","Powerful Build","Relentless Endurance","Languages"],"entries":[{"type":"text","content":"<i>**//Orcs trace their creation to the one-eyed god Gruumsh, an unstoppable warrior and powerful leader. The divine qualities of Gruumsh resonate within orcs, granting them a reflection of his toughness and tenacity that can’t be matched, and the god equipped his children to be able to live above or below ground.//**</i> <i>**//On some worlds, such as Eberron, orcs were among the first defenders of the natural order from the encroachments of Fiends and other extraplanar threats. Gruumsh’s blessings have made orcs tireless guardians and mighty allies wherever they are found, even when they turn their devotion to other gods.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Adrenaline Rush.","entry":"You can take the Dash action as a bonus action. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. * Whenever you use this trait, you gain a number of temporary hit points equal to your proficiency bonus."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Relentless Endurance.","entry":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. Once you use this trait, you can’t do so again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Orc (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"orc":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Aggressive","Primal Intuition","Powerful Build","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2 and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Orcs reach adulthood at age 12 and live up to 50 years."},{"type":"item","name":"Alignment.","entry":"Orcs are vicious raiders, who believe that the world should be theirs. They also respect strength above all else and believe the strong must bully the weak to ensure that weakness does not spread like a disease. They are usually chaotic evil."},{"type":"item","name":"Size.","entry":"Orcs are usually over 6 feet tall and weigh between 230 and 280 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Aggressive.","entry":"As a bonus action, you can move up to your speed toward an enemy of your choice that you can see or hear. You must end this move closer to the enemy than you started."},{"type":"item","name":"Primal Intuition.","entry":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Nature, Perception, and Survival."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Orc."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Owlfolk (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Magic Sight","Nimble Flight","Silent Feathers","Languages"],"entries":[{"type":"text","content":"<i>**//Distant kin of giant owls, owlfolk come in many shapes and sizes, from petite and fluffy to widewinged and majestic. Owlfolk have arms and legs like other Humanoids, as well as wings that extend from their back and shoulders.//**</i> <i>**//Because of their ancestral tie to the Feywild, owlfolk can innately see the magic of their surroundings. Like owls, owlfolk are graced with feathers that make no sound when they move or fly, making it easy for them to sneak up on you in the library.//**</i> <i>**//Your owlfolk character might be nocturnal. Or perhaps your character is simply prone to rise later, embodying the common nickname of night owl.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 90 feet of you as if it were bright light and in darkness as if it were dim light."},{"type":"item","name":"Magic Sight.","entry":"Your keen senses can focus to see the presence of magic. You gain the ability to cast the Detect Magic spell, but only as a ritual. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma. You can also cast this spell normally with any spell slots you have."},{"type":"item","name":"Nimble Flight.","entry":"Thanks to your wings, you have a flying speed equal to your walking speed. When you fall, you can use your reaction to make a Dexterity saving throw (DC 10) to stop falling and fly in place until the start of your next turn."},{"type":"item","name":"Silent Feathers.","entry":"You have proficiency in the Stealth skill."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Owlin (SCC)","source":"SaCoC","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Size","Speed","Darkvision","Flight","Silent Feathers"],"entries":[{"type":"text","content":"<i>**//Distant kin of giant owls from the Feywild, owlin come in many shapes and sizes, from petite and fluffy to wide-winged and majestic. Owlin have arms and legs like other Humanoids, as well as wings that extend from their back and shoulders.</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 120 feet of yourself as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Flight.","entry":"Thanks to your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."},{"type":"item","name":"Silent Feathers.","entry":"You have proficiency in the Stealth skill."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Plasmoid (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Amorphous","Darkvision","Hold Breath","Natural Resilience","Shape Self","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are an Ooze."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Amorphous.","entry":"You can squeeze through a space as narrow as 1 inch wide, provided you are wearing and carrying nothing. You also have advantage on ability checks you make to initiate or escape a grapple."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Hold Breath.","entry":"You can hold your breath for 1 hour."},{"type":"item","name":"Natural Resilience.","entry":"You have resistance to acid and poison damage, and you have advantage on saving throws against being poisoned."},{"type":"item","name":"Shape Self.","entry":"If you are not incapacitated, you can reshape your body to give yourself a head, one or two arms, one or two legs, and makeshift hands and feet, or you can revert to a limbless blob (no action required). As a bonus action, you can extrude a pseudopod that is up to 6 inches wide and 10 feet long or reabsorb it into your body. You can use this pseudopod to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour out the contents of a container. The pseudopod can’t attack, activate magic items, or carry more than 10 pounds."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Rabbitfolk (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Hare-Trigger","Leporine Senses","Lucky Footwork","Rabbit Hop","Languages"],"entries":[{"type":"text","content":"<i>**//Bounding across the wilds, rabbitfolk from the Feywild embody a spirit of freedom and travel.//**</i> <i>**//Rabbitfolk are bipedal, with the characteristic long feet of the animal they resemble and fur in a variety of colors. They share the keen senses and powerful legs of leporine creatures and are full of energy, like a wound-up spring. Rabbitfolk are blessed with a little fey luck, and they often find themselves a few fortunate feet away from dangers during adventures.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Hare-Trigger.","entry":"You add your proficiency bonus to your initiative rolls."},{"type":"item","name":"Leporine Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Lucky Footwork.","entry":"When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the result, potentially turning the failure into a success."},{"type":"item","name":"Rabbit Hop.","entry":"Once during each of your turns when you walk at least 5 feet, you can hop, rolling a d12 and moving that many feet in a direction of your choice. This extra distance doesn’t cost movement, but you can hop only if your speed isn’t 0."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Reborn (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Type","Size","Speed","Darkvision","Deathless Nature","Knowledge from a Past Life","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1."},{"type":"item","name":"Type.","entry":"Humanoid, as well as Construct or Undead (choose when you gain this lineage)"},{"type":"item","name":"Size.","entry":"Medium or Small (choose when you gain this lineage)"},{"type":"item","name":"Speed.","entry":"30 feet"},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light."},{"type":"item","name":"Deathless Nature.","entry":"You have escaped death, a fact represented by the following benefits: * You have advantage on saving throws against disease and being poisoned, and you have resistance to poison damage. * You have advantage on death saving throws. * You don’t need to eat, drink, or breathe. * You don’t need to sleep, and magic can’t put you to sleep. You can finish a long rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."},{"type":"item","name":"Knowledge from a Past Life.","entry":"You temporarily remember sporadic glimpses of the past, perhaps faded memories from ages ago or a previous life. When you make an ability check that uses a skill, you can roll a d6 and add the number rolled to the check. You can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Reborn (VRGR)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Languages","Creature Type","Size","Speed","Ancestral Legacy","Deathless Nature","Knowledge from a Past Life"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2 and increase a different one by 1, or increase three different ability scores by 1. If you are replacing your race with this lineage, replace any Ability Score Increase you previously had with this."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. If you are replacing your race with this lineage, you retain any languages you had and gain no new languages."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you gain this lineage."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Ancestral Legacy.","entry":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it. * If you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."},{"type":"item","name":"Deathless Nature.","entry":"You have escaped death, a fact represented by the following benefits: * You have advantage on saving throws against disease and being poisoned, and you have resistance to poison damage. * You have advantage on death saving throws. * You don’t need to eat, drink, or breathe. * You don’t need to sleep, and magic can’t put you to sleep. You can finish a long rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."},{"type":"item","name":"Knowledge from a Past Life.","entry":"You temporarily remember glimpses of the past, perhaps faded memories from ages ago or a previous life. When you make an ability check that uses a skill, you can roll a d6 immediately after seeing the number on the d20 and add the number on the d6 to the check. You can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Satyr (MOT)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":35},"ability":[],"languages":[{"common":true},{"sylvan":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Fey","Ram","Magic Resistance","Mirthful Leaps","Reveler","Languages"],"entries":[{"type":"text","content":"<i>**//Satyrs have a well-earned reputation for their good spirits, gregarious personalities, and love of revels. Most satyrs are driven by simple desires, to see the world and to sample its every pleasure. While their spontaneity and whimsy sometimes put them at odds with more stoic peoples, satyrs rarely let the moodiness of others hinder their own happiness. Life is a blessing from the gods, after all, and the proper response to such a gift, as far as most satyrs are concerned, is to accept it with relish.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and your Dexterity score increases by 1."},{"type":"item","name":"Age.","entry":"Satyrs mature and age at about the same rate as humans."},{"type":"item","name":"Alignment.","entry":"Satyrs delight in living a life free of the mantle of law. They gravitate toward being good, but some have devious streaks and enjoy causing dismay."},{"type":"item","name":"Size.","entry":"Satyrs range from just under 5 feet to about 6 feet in height, with generally slender builds. Your size is medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 35 feet."},{"type":"item","name":"Fey.","entry":"Your creature type is fey, rather than humanoid."},{"type":"item","name":"Ram.","entry":"You can use your head and horns to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier."},{"type":"item","name":"Magic Resistance.","entry":"You have advantage on saving throws against spells and other magical effects."},{"type":"item","name":"Mirthful Leaps.","entry":"Whenever you make a long or high jump, you can roll a d8 and add the number to the number of feet you cover, even when making a standing jump. This extra distance costs movement as normal."},{"type":"item","name":"Reveler.","entry":"You have proficiency in the Performance and Persuasion skills, and you have proficiency with one musical instrument of your choice."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Sylvan."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Satyr (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":35},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Ram","Magic Resistance","Mirthful Leaps","Reveler","Languages"],"entries":[{"type":"text","content":"<i>**//Originating in the Feywild — a realm of pure emotion-satyrs thrive on the energy of merriment. They resemble elves but have goatlike legs, cloven hooves, and ram or goat horns. The magic of the fey realm has given them an innate ability to perform, to delight, and to resist magical intrusion. While they’re usually found in the Feywild, satyrs do wander to other planes of existence, most often to the Material Plane. There they seek to bring a bit of their home plane’s splendor to other worlds.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Fey."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 35 feet."},{"type":"item","name":"Ram.","entry":"You can use your head and horns to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Magic Resistance.","entry":"You have advantage on saving throws against spells."},{"type":"item","name":"Mirthful Leaps.","entry":"Whenever you make a long jump or a high jump, you can roll a d8 and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as normal."},{"type":"item","name":"Reveler.","entry":"As an embodiment of revelry, you have proficiency in the Performance and Persuasion skills, and you have proficiency with one musical instrument of your choice."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Sea Elf (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Child of the Sea","Darkvision","Fey Ancestry","Friend of the Sea","Keen Senses","Trance","Languages"],"entries":[{"type":"text","content":"<i>**//Sea elves fell in love with the wild beauty of the ocean in the earliest days of the multiverse. While other elves traveled from realm to realm, sea elves navigated the currents and explored the waters of many worlds. Today these elves can be found wherever oceans exist, as well as in the Elemental Plane of Water.//**</i> <i>**//Like other elves, sea elves can live to be over 750 years old.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."},{"type":"item","name":"Child of the Sea.","entry":"You can breathe air and water, and you have resistance to cold damage."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Friend of the Sea.","entry":"Aquatic animals have an extraordinary affinity with your people. You can communicate simple ideas to any Beast that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Trance.","entry":"You don’t need to sleep, and magic can’t put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. * Whenever you finish this trance, you can gain two proficiencies that you don’t have, each one with a weapon or a tool of your choice selected from the <i>Player’s Handbook</i>. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Sea Elf (MTF)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"aquan":true}],"traits":["Ability Score Increase","Age","Size","Speed","Darkvision","Fey Ancestry","Trance","Keen Senses","Sea Elf Training","Child of the Sea","Friend of the Sea","Languages"],"entries":[{"type":"text","content":"<i>**//Sea elves fell in love with the wild beauty of the ocean in the earliest days of the multiverse. While other elves traveled from realm to realm, the sea elves navigated the deepest currents and explored the waters across a hundred worlds. Today, they live in small, hidden communities in the ocean shallows and on the Elemental Plane of Water.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."},{"type":"item","name":"Size.","entry":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"Elves do not sleep. Instead they meditate deeply, remaining semi-conscious, for 4 hours a day. The Common word for this meditation is \\"trance.\\" While meditating, you dream after a fashion; such dreams are actually mental exercises that have become reflexive after years of practice. After resting in this way, you gain the same benefit a human would from 8 hours of sleep."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Sea Elf Training.","entry":"You have proficiency with the spear, trident, light crossbow, and net."},{"type":"item","name":"Child of the Sea.","entry":"You have a swimming speed of 30 feet, and you can breathe air and water."},{"type":"item","name":"Friend of the Sea.","entry":"Using gestures and sounds, you can communicate simple ideas with any beast that has an innate swimming speed."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Elven, and Aquan."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shadar-Kai (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Blessing of the Raven Queen","Darkvision","Fey Ancestry","Keen Senses","Necrotic Resistance","Trance","Languages"],"entries":[{"type":"text","content":"<i>**//Shadar-kai are the elves of the Shadowfell, originally drawn to that dread realm by the Raven Queen. Over the centuries, some of them have continued to serve her, while others have ventured into the Material Plane to forge their own destinies.//**</i> <i>**//Once shadar-kai were Fey like the rest of their elven kin; now they exist in a state between life and death, thanks to being transformed by the Shadowfell’s grim energy.//**</i> <i>**//Shadar-kai have ashen skin tones, and while they’re in the Shadowfell, they also become wizened, reflecting the somber nature of that gloomy plane.//**</i> <i>**//Like other elves, shadar-kai can live to be over 750 years old.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid. You are also considered an elf for any prerequisite or effect that requires you to be an elf."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Blessing of the Raven Queen.","entry":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. * Starting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Necrotic Resistance.","entry":"You have resistance to necrotic damage."},{"type":"item","name":"Trance.","entry":"You don’t need to sleep, and magic can’t put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness. * Whenever you finish this trance, you can gain two proficiencies that you don’t have, each one with a weapon or a tool of your choice selected from the <i>Player’s Handbook</i>. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shadar-Kai (MTF)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Size","Speed","Darkvision","Fey Ancestry","Trance","Keen Senses","Necrotic Resistance","Blessing of the Raven Queen","Languages"],"entries":[{"type":"text","content":"<i>**//Sworn to the Raven Queen's service, the mysterious shadar-kai venture into the Material Plane from the Shadowfell to advance her will. Once they were fey like the rest of their elven kin, and now they exist in a strange state between life and death. Eladrin and shadar-kai are like reflections of each other: one bursting with emotion, the other nearly devoid of it.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old."},{"type":"item","name":"Size.","entry":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Fey Ancestry.","entry":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"type":"item","name":"Trance.","entry":"Elves do not sleep. Instead they meditate deeply, remaining semi-conscious, for 4 hours a day. The Common word for this meditation is \\"trance.\\" While meditating, you dream after a fashion; such dreams are actually mental exercises that have become reflexive after years of practice. After resting in this way, you gain the same benefit a human would from 8 hours of sleep."},{"type":"item","name":"Keen Senses.","entry":"You have proficiency in the Perception skill."},{"type":"item","name":"Necrotic Resistance.","entry":"You have resistance to necrotic damage."},{"type":"item","name":"Blessing of the Raven Queen.","entry":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. Once you use this trait, you can't do so again until you finish a long rest. Starting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Elven."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Beasthide (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Natural Athlete","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//Stoic and solid, a beasthide shifter draws strength and stability from the beast within. Beasthide shifters are typically tied to the bear or the boar, but any creature known for its toughness could apply.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 2, and your Strength score increases by 1."},{"type":"item","name":"Natural Athlete.","entry":"You have proficiency in the Athletics skill."},{"type":"item","name":"Shifting Feature.","entry":"Whenever you shift, you gain 1d6 additional temporary hit points, and while shifted, you have a +1 bonus to your Armor Class."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Cliffwalk (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//Your cliffwalk heritage grants you the agility of a mountain goat.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Shifting Feature.","entry":"While shifting, you gain a climb speed of 30 feet."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Longtooth (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Fierce","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//Longtooth shifters are fierce and aggressive, but they form deep bonds with their friends. Many longtooth shifters have canine traits that become more pronounced as they shift, but they might instead draw on tigers, hyenas, or other predators.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Dexterity score increases by 1."},{"type":"item","name":"Fierce.","entry":"You have proficiency in the Intimidation skill."},{"type":"item","name":"Shifting Feature.","entry":"While shifted, you can use your elongated fangs to make an unarmed strike as a bonus action. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Bestial Instincts","Darkvision","Shifting","Beasthide","Longtooth","Swiftstride","Wildhunt","Languages"],"entries":[{"type":"text","content":"<i>**//Shifters are sometimes called weretouched, as they are descendants of people who contracted full or partial lycanthropy. Humanoids with a bestial aspect, shifters can’t fully change shape, but they can temporarily enhance their animalistic features by entering a state they call shifting.//**</i> <i>**//Shifters are similar to humans in height and build but are typically more lithe and flexible. Their facial features have a bestial cast, often with large eyes and pointed ears; most shifters also have prominent canine teeth. They grow fur-like hair on nearly every part of their bodies. While a shifter’s appearance might remind an onlooker of an animal, they remain clearly identifiable as shifters even when at their most feral.//**</i> <i>**//Most shifters resemble a particular kind of lycanthrope. You can choose the kind of lycanthrope in your past, or you can determine it randomly by rolling on the Lycanthrope Ancestor table. The table also provides a suggestion for the Shifting option you might have as a result of your ancestry.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Bestial Instincts.","entry":"Channeling the beast within, you have proficiency in one of the following skills of your choice: Acrobatics, Athletics, Intimidation, or Survival."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Shifting.","entry":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 x your proficiency bonus. You can shift a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest. * Whenever you shift, you gain an additional benefit based on one of the following options (choose when you select this race):"},{"type":"item","name":"Beasthide.","entry":"You gain 1d6 additional temporary hit points. While shifted, you have a +1 bonus to your Armor Class."},{"type":"item","name":"Longtooth.","entry":"When you shift and as a bonus action on your other turns while shifted, you can use your elongated fangs to make an unarmed strike. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Swiftstride.","entry":"While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn’t provoke opportunity attacks."},{"type":"item","name":"Wildhunt.","entry":"While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you unless you’re incapacitated."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Razorclaw (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//As a razorclaw shifter, you make swift, slashing strikes in battle//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Shifting Feature.","entry":"While shifting, you can make an unarmed strike as a bonus action. You can use your Dexterity for its attack roll and damage bonus, and this attack deals slashing damage."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Swiftstride (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Graceful","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//Swiftstride shifters are graceful and quick. Typically feline in nature, swiftstride shifters are often aloof and difficult to pin down physically or socially.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Charisma score increase by 1."},{"type":"item","name":"Graceful.","entry":"You have proficiency in the Acrobatics skill."},{"type":"item","name":"Shifting Feature.","entry":"While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when an enemy ends its turn within 5 feet of you. This reactive movement doesn’t provoke opportunity attacks."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Shifter: Wildhunt (E:RLW)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Natural Tracker","Mark the Scent","Shifting Feature"],"entries":[{"type":"text","content":"<i>**//Wildhunt shifters are sharp and insightful. Some are constantly alert, ever wary for possible threats. Others focus on their intuition, searching within. Wildhunt shifters are excellent hunters, and they also tend to become the spiritual leaders of shifter communities.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 2."},{"type":"item","name":"Natural Tracker.","entry":"You have proficiency in the Survival skill."},{"type":"item","name":"Mark the Scent.","entry":"As a bonus action, you can mark one creature you can see within 10 feet of you. Until the end of your next long rest, your proficiency bonus is doubled for any ability check you make to find the marked creature, and you always know the location of that creature if it is within 60 feet of you. You can’t use this trait again until you finish a short or long rest."},{"type":"item","name":"Shifting Feature.","entry":"While shifted, you have advantage on Wisdom checks."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tabaxi (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Cat's Claws","Cat's Talent","Darkvision","Feline Agility","Languages"],"entries":[{"type":"text","content":"<i>**//Created by the Cat Lord—a divine being of the Upper Planes—to blend the qualities of humanoids and cats, tabaxi are a varied people in both attitude and appearance. In some lands, tabaxi live like the cats they resemble, naturally curious and at home in playful environments. In other places, tabaxi live as other folk do, not exhibiting the feline behavior the Cat Lord intended.//**</i> <i>**//Tabaxi’s appearance is as varied as their attitudes. Some tabaxi have features or patterning in their fur like tigers, jaguars, or other big cats, while others have appearances more like a house cat. Still others have unique patterns or might style their fur to their preferences — or might even be hairless!//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a climbing speed equal to your walking speed."},{"type":"item","name":"Cat's Claws.","entry":"You can use your claws to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Cat's Talent.","entry":"You have proficiency in the Perception and Stealth skills."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Feline Agility.","entry":"Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can’t use it again until you move 0 feet on one of your turns."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tabaxi (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Feline Agility","Cat's Claws","Cat's Talent","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Charisma score increases by 1."},{"type":"item","name":"Age.","entry":"Tabaxi have lifespans equivalent to humans."},{"type":"item","name":"Alignment.","entry":"Tabaxi tend toward chaotic alignments, as they let impulse and fancy guide their decisions. They are rarely evil, with most of them driven by curiosity rather than greed or other dark impulses."},{"type":"item","name":"Size.","entry":"Tabaxi are taller on average than humans and relatively slender. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You have a cat's keen senses, especially in the dark. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Feline Agility.","entry":"Your reflexes and agility allow you to move with a burst of speed. When you move on your tum in combat, you can double your speed until the end of the tum. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."},{"type":"item","name":"Cat's Claws.","entry":"Because of your claws, you have a climbing speed of 20 feet. In addition, your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Cat's Talent.","entry":"You have proficiency in the Perception and Stealth skills."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Thri-Kreen (UA)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Chameleon Carapace","Darkvision","Secondary Arms","Sleepless Revitalization","Thri-kreen Telepathy","Languages"],"entries":[{"type":"text","content":"<i>**//Although thri-kreen don’t sleep, they do require periods of inactivity to revitalize themselves. During these periods, they are fully conscious and aware of what’s happening around them.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Increase one ability score by 2, and increase a different one by 1, or increase three different scores by 1."},{"type":"item","name":"Creature Type.","entry":"You are a Monstrosity."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Chameleon Carapace.","entry":"While you aren’t wearing armor, your carapace gives you a base Armor Class of 13 + your Dexterity modifier. As an action, you can change the color of your carapace to match the color and texture of your surroundings, giving you advantage on Dexterity (Stealth) checks made to hide in those surroundings."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Secondary Arms.","entry":"You have two slightly smaller secondary arms below your primary pair of arms. The secondary arms function like your primary arms, with the following exceptions: * You can use a secondary arm to wield a weapon that has the light property, but you can’t use a secondary arm to wield other kinds of weapons. * You can’t wield a shield with a secondary arm"},{"type":"item","name":"Sleepless Revitalization.","entry":"You do not require sleep and can choose to remain conscious during a long rest, though you must still refrain from strenuous activity to gain the benefit of the rest."},{"type":"item","name":"Thri-kreen Telepathy.","entry":"You have the magical ability to communicate mentally with any number of willing creatures you can see within 120 feet of you. A contacted creature doesn’t need to share a language with you, but it must be able to understand at least one language. Your telepathic link to a creature is broken if you and the creature move more than 120 feet apart, if either of you is incapacitated, or if either of you mentally breaks the contact (no action required)."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Abyssal Tiefling (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[{"abyssal":true}],"traits":["Ability Score Increase","Abyssal Arcana","Abyssal Fortitude","Languages"],"entries":[{"type":"text","content":"<i>**//All abyssal tieflings trace their bloodline to the demons of the Abyss. These tieflings have the following additional features.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Abyssal Arcana.","entry":"Each time you finish a long rest, you gain the ability to cast cantrips and spells randomly determined from a short list. At 1st level, you can cast a cantrip. When you reach 3rd level, you can also cast a 1st-level spell. At 5th level, you can cast a 2nd-level spell. * You can cast a spell gained from this trait only once until you complete your next long rest. You can cast a cantrip gained from this trait at will, as normal. For 1st-level spells whose effect changes if cast using a spell slot of 2nd level or higher, you cast the spell as if using a 2nd-level slot. Spells of 2nd level are cast as if using a 2nd-level slot. * At the end of each long rest, you lose the cantrips and spells previously granted by this feature, even if you did not cast them. You replace those cantrips and spells by rolling for new ones on the Abyssal Arcana Spells table. Roll separately for each cantrip and spell. If you roll the same spell or cantrip you gained at the end of your previous long rest, roll again until you get a different result."},{"type":"item","name":"Abyssal Fortitude.","entry":"Your hit point maximum increases by half your level (minimum 1)."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Abyssal. ||||||||~ Abyssal Arcana Spells|| ||~ d6||~ 1st Level||~ 3rd Level||~ 5th Level|| ||1||<i>Dancing Lights</i>||<i>Burning Hands</i>||<i>Alter Self</i>|| ||2||<i>True Strike</i>||<i>Charm Person</i>||<i>Darkness</i>|| ||3||<i>Light</i>||<i>Magic Missile</i>||<i>Invisibility</i>|| ||4||<i>Message</i>||<i>Cure Wounds</i>||<i>Levitate</i>|| ||5||<i>Spare the Dying</i>||<i>Tasha's Hideous Laughter</i>||<i>Mirror Image</i>|| ||6||<i>Prestidigitation</i>||<i>Thunderwave</i>||<i>Spider Climb</i>||"}]}],"skillProficiencies":null,"homebrew":true},{"name":"Asmodeus Tiefling (PHB)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Infernal Legacy"],"entries":[{"type":"text","content":"<i>**//The tieflings connected to Nessus command the power of fire and darkness, guided by a keener than normal intellect, as befits those linked to Asmodeus himself.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Infernal Legacy.","entry":"You know the Thaumaturgy cantrip. Once you reach 3rd level, you can cast the Hellish Rebuke spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Darkness spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Baalzebul Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Maladomini"],"entries":[{"type":"text","content":"<i>**//The crumbling realm of Maladomini is ruled by Baalzebul, who excels at corrupting those whose minor sins can be transformed into acts of damnation. Tieflings linked to this archdevil can corrupt others both physically and psychically.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Legacy of Maladomini.","entry":"You know the Thaumaturgy cantrip. Once you reach 3rd level, you can cast the Ray of Sickness spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Crown of Madness spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Dispater Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Dis"],"entries":[{"type":"text","content":"<i>**//The great city of Dis occupies most of Hell's second layer. It is a place where secrets are uncovered and shared with the highest bidder, making tieflings tied to Dispater excellent spies and infiltrators.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Legacy of Dis.","entry":"You know the Thaumaturgy cantrip. Once you reach 3rd level, you can cast the Disguise Self spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Detect Thoughts spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Fierna Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Phlegethos"],"entries":[{"type":"text","content":"<i>**//A master manipulator, Fierna grants tieflings tied to her forceful personalities.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Wisdom score increases by 1."},{"type":"item","name":"Legacy of Phlegethos.","entry":"You know the Friends cantrip. Once you reach 3rd level, you can cast the Charm Person spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Suggestion spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Glasya Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Malbolge"],"entries":[{"type":"text","content":"<i>**//Glasya, Hell's criminal mastermind, grants her tiefiings magic that is useful for committing heists.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 1."},{"type":"item","name":"Legacy of Malbolge.","entry":"You know the Minor Illusion cantrip. Once you reach 3rd level, you can cast the Disguise Self spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Invisibility spell once as a 2nd-level spell. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Levistus Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Stygia"],"entries":[{"type":"text","content":"<i>**//Frozen Stygia is ruled by Levistus, an archdevil known for offering bargains to those who face an inescapable doom.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Legacy of Stygia.","entry":"You know the Ray of Frost cantrip. Once you reach 3rd level, you can cast the Armor of Agathys spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Darkness spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Mammon Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Minauros"],"entries":[{"type":"text","content":"<i>**//The great miser Mammon loves coins above all else. Tieflings tied to him excel at gathering and safeguarding wealth.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Legacy of Minauros.","entry":"You know the Mage Hand cantrip. Once you reach 3rd level, you can cast the Tenser's Floating Disk spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Arcane Lock spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Mephistopheles Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Cania"],"entries":[{"type":"text","content":"<i>**//In the frozen realm of Cania, Mephistopheles offers arcane power to those who entreat with him. Tieflings linked to him master some arcane magic.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1."},{"type":"item","name":"Legacy of Cania.","entry":"You know the Mage Hand cantrip. Once you reach 3rd level, you can cast the Burning Hands spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Flame Blade spell once as a 3rd-level spell. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tiefling (PHB)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"infernal":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Hellish Resistance","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2."},{"type":"item","name":"Age.","entry":"Tieflings mature at the same rate as humans but live a few years longer."},{"type":"item","name":"Alignment.","entry":"Tieflings might not have an innate tendency toward evil, but many of them end up there. Evil or not, an independent nature inclines many tieflings toward a chaotic alignment."},{"type":"item","name":"Size.","entry":"Tieflings are about the same size and build as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Thanks to your infernal heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can’t discern color in darkness, only shades of gray."},{"type":"item","name":"Hellish Resistance.","entry":"You have resistance to fire damage."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Infernal."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Variant Tiefling (SCAG)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Appearance","Feral","Devil's Tongue","Hellfire","Winged"],"entries":[{"type":"text","content":"<i>**//Since not all tieflings are of the blood of Asmodeus, some have traits that differ from those in the// Player's Handbook. //The Dungeon Master may permit the following variants for your tiefling character, although Devil's Tongue, Hellfire, and Winged are mutually exclusive.//**</i>"},{"type":"list","items":[{"type":"item","name":"Appearance.","entry":"Your tiefling might not look like other tieflings. Rather than having the physical characteristics described in the <i>Player's Handbook</i>, choose 1d4 + 1 of the following features: small horns; fangs or sharp teeth; a forked tongue; catlike eyes; six fingers on each hand; goat-like legs; cloven hoofs; a forked tail; leathery or scaly skin; red or dark blue skin; cast no shadow or reflection; exude a smell of brimstone."},{"type":"item","name":"Feral.","entry":"Your Intelligence score increases by 1, and your Dexterity score increases by 2. This trait replaces the Ability Score Increase trait"},{"type":"item","name":"Devil's Tongue.","entry":"You know the Vicious Mockery cantrip. Once you reach 3rd level, you can cast the Charm Person spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Enthrall spell once. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells. This trait replaces the Infernal Legacy trait"},{"type":"item","name":"Hellfire.","entry":"Once you reach 3rd level, you can cast the Burning Hands spell once as a 2nd-level spell. This trait replaces the Hellish Rebuke spell of the Infernal Legacy trait."},{"type":"item","name":"Winged.","entry":"You have bat-like wings sprouting from your shoulders. You have a flying speed of 30 feet while you aren’t wearing heavy armor. This trait replaces the Infernal Legacy trait."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Zariel Tiefling (MTF)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Legacy of Avernus"],"entries":[{"type":"text","content":"<i>**//Tieflings with a blood tie to Zariel are stronger than the typical tiefling and receive magical abilities that aid them in battle.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 1."},{"type":"item","name":"Legacy of Avernus.","entry":"You know the Thaumaturgy cantrip. Once you reach 3rd level, you can cast the Searing Smite spell once as a 2nd-level spell. Once you reach 5th level, you can also cast the Branding Smite spell once as a 3rd-level spell. You must finish a long rest to cast these spells again with this trait. Charisma is your spellcasting ability for these spells."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tortle (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Claws","Hold Breath","Natural Armor","Nature's Intuition","Shell Defense","Languages"],"entries":[{"type":"text","content":"<i>**//Tortles have a saying: “We wear our homes on our backs.” These turtle folk live on many worlds, most often journeying up and down coasts, along waterways, and across the sea. Tortles don’t have a unified story of how they were created, but they all have a sense of being mystically connected to the natural world. Carrying their shelter on their backs gives tortles a special feeling of security wherever they go, for even if they visit a far, unknown country, they have a place to lay their heads.//**</i> <i>**//Tortles exhibit the same range of coloration and patterns found among turtles, and many tortles enjoy adorning their shells in distinctive ways.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Claws.","entry":"You have claws that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Hold Breath.","entry":"You can hold your breath for up to 1 hour."},{"type":"item","name":"Natural Armor.","entry":"Your shell provides you a base AC of 17 (your Dexterity modifier doesn’t affect this number). You can’t wear light, medium, or heavy armor, but if you are using a shield, you can apply the shield’s bonus as normal."},{"type":"item","name":"Nature's Intuition.","entry":"Thanks to your mystical connection to nature, you gain proficiency with one of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."},{"type":"item","name":"Shell Defense.","entry":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to your AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are prone, your speed is 0 and can’t increase, you have disadvantage on Dexterity saving throws, you can’t take reactions, and the only action you can take is a bonus action to emerge from your shell."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Tortle (TTP)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"aquan":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Claws","Hold Breath","Natural Armor","Shell Defense","Survival Instinct","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Young tortles crawl for a few weeks after birth before learning to walk on two legs. They reach adulthood by the age of 15 and live an average of 50 years."},{"type":"item","name":"Alignment.","entry":"Tortles tend to lead orderly, ritualistic lives. They develop customs and routines, becoming more set in their ways as they age. Most are lawful good. A few can be selfish and greedy, tending more toward evil, but it's unusual for a tortle to shuck off order in favor of chaos."},{"type":"item","name":"Size.","entry":"Tortle adults stand 5 to 6 feet tall and average 450 pounds. Their shells account for roughly one-third of their weight. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Claws.","entry":"Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Hold Breath.","entry":"You can hold your breath for up to 1 hour at a time. Tortles aren't natural swimmers, but they can remain underwater for some time before needing to come up for air."},{"type":"item","name":"Natural Armor.","entry":"Due to your shell and the shape of your body, you are ill-suited to wearing armor. Your shell provides ample protection, however; it gives you a base AC of 17 (your Dexterity modifier doesn't affect this number). You gain no benefit from wearing armor, but if you are using a shield, you can apply the shield's bonus as normal."},{"type":"item","name":"Shell Defense.","entry":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are prone, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge from your shell."},{"type":"item","name":"Survival Instinct.","entry":"You gain proficiency in the Survival skill. Tortles have finely honed survival instincts."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Aquan."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Triton (MPMM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Amphibious","Control Air and Water","Darkvision","Emissary of the Sea","Guardian of the Depths","Languages"],"entries":[{"type":"text","content":"<i>**//Originally from the Elemental Plane of Water, many tritons entered the Material Plane centuries ago in response to the growing threat of evil elementals. Those tritons spread across the worlds’ oceans, protecting the surface from terrors in the deep. Over time, triton have extended their stewardship over the sea floor to the ocean’s surface.//**</i> <i>**//Tritons have webbed hands and feet, small fins on their calves, and coloration that favors blues and greens.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet, and you have a swimming speed equal to your walking speed."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Control Air and Water.","entry":"You can cast Fog Cloud with this trait. Starting at 3rd level, you can cast the Gust of Wind spell with this trait. Starting at 5th level, you can also cast the Water Walk spell with it. Once you cast any of these spells with this trait, you can’t cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have of the appropriate level. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Emissary of the Sea.","entry":"You can communicate simple ideas to any Beast, Elemental, or Monstrosity that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."},{"type":"item","name":"Guardian of the Depths.","entry":"Adapted to the frigid ocean depths, you have resistance to cold damage."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Triton (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"primordial":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Amphibious","Control Air and Water","Darkvision","Emissary of the Sea","Guardians of the Depths","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength, Constitution, and Charisma scores each increase by 1."},{"type":"item","name":"Age.","entry":"Tritons reach maturity around age 15 and can live up to 200 years."},{"type":"item","name":"Alignment.","entry":"Tritons tend toward lawful good. As guardians of the darkest reaches of the sea, their culture pushes them toward order and benevolence."},{"type":"item","name":"Size.","entry":"Tritons are slightly shorter than humans, averaging about 5 feet tall. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet, and you have a swimming speed of 30 feet."},{"type":"item","name":"Amphibious.","entry":"You can breathe air and water."},{"type":"item","name":"Control Air and Water.","entry":"A child of the sea, you can call on the magic of elemental air and water. You can cast Fog Cloud with this trait. Starting at 3rd level, you can cast Gust of Wind with it, and starting at 5th level, you can also cast Wall of Water with it. Once you cast a spell with this trait, you can’t cast that spell with it again until you finish a long rest. Charisma is your spellcasting ability for these spells."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can’t discern color in darkness, only shades of gray."},{"type":"item","name":"Emissary of the Sea.","entry":"Aquatic beasts have an extraordinary affinity with your people. You can communicate simple ideas with beasts that can breathe water. They can understand the meaning of your words, though you have no special ability to understand them in return."},{"type":"item","name":"Guardians of the Depths.","entry":"Adapted to even the most extreme ocean depths, you have resistance to cold damage."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Primordial."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Vampire Ixalan","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Vampiric Resistance","Bloodthirst","Feast of Blood","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Vampires don’t mature and age in the same way that other races do."},{"type":"item","name":"Alignment.","entry":"Vampires might not have an innate tendency toward evil, but many of them end up there. Evil or not, their strict hierarchies incline them toward a lawful alignment."},{"type":"item","name":"Size.","entry":"Vampires are about the same size and build as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can’t discern color in darkness, only shades of gray."},{"type":"item","name":"Vampiric Resistance.","entry":"You have resistance to necrotic damage."},{"type":"item","name":"Bloodthirst.","entry":"You can drain blood and life energy from a willing creature, or one that is grappled by you, incapacitated, or restrained. Make a melee attack against the target. If you hit, you deal 1 piercing damage and 1d6 necrotic damage. The target’s hit point maximum is reduced by an amount equal to the necrotic damage taken, and you regain hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."},{"type":"item","name":"Feast of Blood.","entry":"When you drain blood with your Bloodthirst ability, you experience a surge of vitality. Your speed increases by 10 feet, and you gain advantage on Strength and Dexterity checks and saving throws for 1 minute."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common (if it exists in your campaign) and Vampire."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Vampire Zendikar","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Vampiric Resistance","Blood Thirst","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 1, and your Charisma score increases by 2."},{"type":"item","name":"Age.","entry":"Vampires don’t mature and age in the same way that other races do. Every living vampire is either a bloodchief, infected by the Eldrazi's influence in the distant reaches of history, or was spawned by a bloodchief from a living human. Most vampires are thus very old, but few have any memory of their earliest years."},{"type":"item","name":"Alignment.","entry":"Vampires have no innate tendency toward evil, but consuming the life energy of other creatures often pushes them to that end. Regardless of their moral bent, the strict hierarchies of their bloodchiefs inclines them toward a lawful alignment."},{"type":"item","name":"Size.","entry":"Vampires are about the same size and build as humans. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can’t discern color in darkness, only shades of gray."},{"type":"item","name":"Vampiric Resistance.","entry":"You have resistance to necrotic damage."},{"type":"item","name":"Blood Thirst.","entry":"You can drain blood and life energy from a willing creature, or one that is grappled by you, incapacitated, or restrained. Make a melee attack against the target, using either Strength or Dexterity for your attack roll. If you hit, you deal 1 piercing damage and 1d6 necrotic damage. The target’s hit point maximum is reduced by an amount equal to the necrotic damage taken, and you regain hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0. A humanoid killed in this way becomes a null."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Vampire."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Vedalken (GGR)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Vedalken Dispassion","Tireless Precision","Partially Amphibious","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Vedalken mature slower than humans do. reaching maturity around age 40. Their life span is typically 350 years, with some living to the age of 500."},{"type":"item","name":"Alignment.","entry":"Vedalken are usually lawful and non-evil."},{"type":"item","name":"Size.","entry":"Tall and slender, Vedalken stand around 6 to 6½ feet tall. They usually weigh around 200Ibs(90kg).They are medium creatures."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Vedalken Dispassion.","entry":"You have advantage on all Intelligence, Wisdom, and Charisma Saving Throws."},{"type":"item","name":"Tireless Precision.","entry":"You are proficient in one of the following skills of your choice: Arcana, History, Investigation, Medicine, Performance, or Sleight of Hand. You are also proficient with one tool of your choice. Whenever you make an ability check with the chosen skill or tool, roll a d4 and add the number rolled to the check's total."},{"type":"item","name":"Partially Amphibious.","entry":"By absorbing oxygen through your skin, you can breathe underwater for up to 1 hour. Once you've reached that limit, you can't use this trait again until you finish a long rest."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Vedalken, and one language of your choice."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Vedalken Kaladesh","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Vedalken Cunning","Aether Lore","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Intelligence score increases by 2, and your Wisdom score increases by 1."},{"type":"item","name":"Age.","entry":"Vedalken mature at the same rate humans do, and most are expected to settle down into an adult life by around age 40. They can live 350 to almost 500 years."},{"type":"item","name":"Alignment.","entry":"Vedalken are most often lawful and rarely evil."},{"type":"item","name":"Size.","entry":"Vedalken are taller than humans but more slender. They average 6 to 6½ feet tall, but usually weigh less than 200 pounds. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Vedalken Cunning.","entry":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic."},{"type":"item","name":"Aether Lore.","entry":"Whenever you make an Intelligence (History) check related to magic items or aether-powered technological devices, you can add twice your proficiency bonus, instead of any proficiency bonus you normally apply."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Vedalken. The Vedalken language is renowned for its technical treatises and its catalogs of knowledge about the natural world and the aether that pervades it."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Verdan (AI)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"goblin":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Black Blood Healing","Limited Telepathy","Persuasive","Telepathic Insight","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"Verdan reach adulthood at around the age 24 and it is thought that they might live to nearly 200 years old. However, because no verdan has died of old age since the race's initial creation, their upper age limits remain speculation."},{"type":"item","name":"Alignment.","entry":"Verdan are generally good, although their absence of racial identity and shared history can sometimes see individual verdan become untethered from any moral or ethical framework."},{"type":"item","name":"Size.","entry":"Verdan start out similar in size to the goblins they were created from, ranging from 3 to 4 feet in height. But at some point after reaching maturity, each verdan undergoes a sudden growth spurt of 2 feet or more. At 1st level, you are a small creature. When you reach 5th level, you become a medium creature."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Black Blood Healing.","entry":"The black blood that is a sign of your people's connection to That-Which-Endures boosts your natural healing. When you roll either 1 or 2 on any Hit Die you spend at the end of a short rest, you can re-roll the die and must use the new roll."},{"type":"item","name":"Limited Telepathy.","entry":"You can telepathically speak to any creature you can see within 30 feet. You don't need to share a language with the creature for it to understand your telepathy, but it must be able to understand at least one language. This process of communication is slow and limited, allowing you to transmit and receive only simple ideas and straightforward concepts."},{"type":"item","name":"Persuasive.","entry":"Your people's lack of history makes you trustworthy and humble. You have proficiency in the Persuasion skill."},{"type":"item","name":"Telepathic Insight.","entry":"Your mind's connection to the world around you strengthens your will. You have advantage on all Wisdom and Charisma saving throws."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Goblin, and one additional language. This language typically has some connection to one of the areas or cultures that has been part of your life."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Viashino (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"draconic":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Bite","Lashing Tail","Wiry Frame","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2, and your Strength score increases by 1."},{"type":"item","name":"Age.","entry":"Viashino mature quickly, reaching adulthood in their early teens. They live violent lives and rarely die of old age, but they would rarely live past 60 anyway."},{"type":"item","name":"Alignment.","entry":"Viashino strongly tend toward chaotic alignments. They have no particular inclination toward good or evil."},{"type":"item","name":"Size.","entry":"Viashino are about as tall as humans, but they have lithe, wiry frames. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Bite.","entry":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to 1d4+ your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Lashing Tail.","entry":"Your semi-prehensile tail is tipped with a bony blade. Immediately after a creature within 5 feet of you deals damage to you with a melee attack, you can use your reaction to make an unarmed strike against that creature with your tail. If you hit, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"type":"item","name":"Wiry Frame.","entry":"You gain proficiency in the Acrobatics or the Stealth skill (your choice)."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common and Draconic."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Warforged Envoy (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Specialized Design","Integrated Tool"],"entries":[{"type":"text","content":"<i>**//As an envoy, you were designed with a certain specialized function in mind. You might be an assassin, a healer, or an entertainer, to name a few possibilities. Envoys are the rarest of the warforged subraces, and yours could be a unique design.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Two different ability scores of your choice increase by 1."},{"type":"item","name":"Specialized Design.","entry":"You gain one skill proficiency of your choice, one tool proficiency of your choice, and fluency in one language of your choice."},{"type":"item","name":"Integrated Tool.","entry":"Choose one tool you’re proficient with. This tool is integrated into your body, and you double your proficiency bonus for any ability checks you make with it. You must have your hands free to use this integrated tool."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Warforged Features (UA)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Warforged Resilience","Sentry's Rest","Integrated Protection","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Constitution score increases by 1."},{"type":"item","name":"Age.","entry":"A typical warforged is between two and thirty years old. The maximum lifespan of the warforged remains a mystery; so far, warforged have shown no signs of deterioration due to age."},{"type":"item","name":"Alignment.","entry":"Most warforged take comfort in order and discipline, tending toward law and neutrality. But some have absorbed the morality – or lack thereof – of the beings with which they served."},{"type":"item","name":"Size.","entry":"Your size is Medium. Most warforged stand between 5 and 6 1/2 feet tall. Weight and build are affected by subrace."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Warforged Resilience.","entry":"You were created to have remarkable fortitude, represented by the following benefits. * You have advantage on saving throws against being poisoned, and you have resistance to poison damage. * You are immune to disease. * You don’t need to eat, drink, or breathe. * You don't need to sleep and don't suffer the effects of exhaustion due to lack of rest, and magic can’t put you to sleep."},{"type":"item","name":"Sentry's Rest.","entry":"When you take a long rest, you must spend at least six hours in an inactive, motionless state, rather than sleeping. In this state, you appear inert, but it doesn’t render you unconscious, and you can see and hear as normal."},{"type":"item","name":"Integrated Protection.","entry":"Your body has built-in defensive layers, which determine your armor class. You gain no benefit from wearing armor,\\u0014 but if you are using a shield, you apply its bonus as normal. * You can alter your body to enter different defensive modes; each time you finish a long rest, choose one mode to adopt from the Integrated Protection table, provided you meet the mode’s prerequisite. ||||||~ Integrated Protection || ||~ Mode ||~ Prerequisite ||~ Effect || || Darkwood Core (unarmored) || None || AC = 11 + your Dexterity modifier (add proficiency bonus if proficient with light armor).|| || Composite Plating (armored) || Medium armor proficiency || AC = 13 + your Dexterity modifier (maximum of 2) + your proficiency bonus. || || Heavy Plating (armored) || Heavy armor proficiency || AC = 16 + your proficiency bonus; disadvantage on Dexterity (Stealth) checks. ||"},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Warforged Juggernaut (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Iron Fists","Powerful Build"],"entries":[{"type":"text","content":"<i>**//You’re an imposing war machine built for close combat and raw might. You tower over your comrades; juggernaut warforged stand between 6 and 7 feet in height and can weigh up to 450 pounds.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Strength score increases by 2."},{"type":"item","name":"Iron Fists.","entry":"When you make an unarmed strike, you can deal 1d4 + your Strength modifier bludgeoning damage instead of the normal damage."},{"type":"item","name":"Powerful Build.","entry":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Warforged Skirmisher (UA)","source":"HB","edition":"classic","size":[],"speed":{"walk":30},"ability":[],"languages":[],"traits":["Ability Score Increase","Swift","Light Step"],"entries":[{"type":"text","content":"<i>**//You were built to scout the edges of battle and outmaneuver your enemies. You are lean and designed for speed.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Dexterity score increases by 2."},{"type":"item","name":"Swift.","entry":"Your walking speed is increased by 5 feet."},{"type":"item","name":"Light Step.","entry":"When you are traveling alone for an extended period of time (one hour or more), you can move stealthily at a normal pace."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Yuan-Ti (MPMM)","source":"HB","edition":"classic","size":["M","S"],"speed":{"walk":30},"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":2}}],"languages":[{"common":true}],"traits":["Ability Score Increase","Creature Type","Size","Speed","Darkvision","Magic Resistance","Poison Resilience","Serpentine Spellcasting","Languages"],"entries":[{"type":"text","content":"<i>**//Yuan-ti were originally humans who transformed themselves into serpent folk through ancient rituals. Most yuan-ti were corrupted into monsters by those rites, but some yuan-ti instead became a new people who mix characteristics of humans and snakes.//**</i> <i>**//Blessed with resistance to magical and poisonous effects by the rituals that created them, each of these yuan-ti manifests their serpentine heritage in a variety of ways: a forked tongue, snake eyes, a snakelike nose, or some other ophidian characteristic. However a yuan-ti looks, they have the power to pursue great good or evil in the multiverse.//**</i>"},{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"When determining your character’s ability scores, increase one score by 2 and increase a different score by 1, or increase three different scores by 1. You can't raise any of your scores above 20."},{"type":"item","name":"Creature Type.","entry":"You are a Humanoid."},{"type":"item","name":"Size.","entry":"You are Medium or Small. You choose the size when you select this race."},{"type":"item","name":"Speed.","entry":"Your walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"type":"item","name":"Magic Resistance.","entry":"You have advantage on saving throws against spells."},{"type":"item","name":"Poison Resilience.","entry":"You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."},{"type":"item","name":"Serpentine Spellcasting.","entry":"You know the Poison Spray cantrip. You can cast Animal Friendship an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast Suggestion with this trait. Once you cast it, you can’t do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher. * Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"type":"item","name":"Languages.","entry":"Your character can speak, read, and write Common and one other language that you and your DM agree is appropriate for the character. The <i>Player’s Handbook</i> offers a list of languages to choose from. The DM is free to modify that list for a campaign."}]}],"skillProficiencies":null,"homebrew":true},{"name":"Yuan-Ti (VGM)","source":"HB","edition":"classic","size":["M"],"speed":{"walk":30},"ability":[],"languages":[{"common":true},{"draconic":true},{"abyssal":true}],"traits":["Ability Score Increase","Age","Alignment","Size","Speed","Darkvision","Innate Spellcasting","Magic Resistance","Poison Immunity","Languages"],"entries":[{"type":"list","items":[{"type":"item","name":"Ability Score Increase.","entry":"Your Charisma score increases by 2, and your Intelligence score increases by 1."},{"type":"item","name":"Age.","entry":"Purebloods mature at the same rate as humans and have lifespans similar in length to theirs."},{"type":"item","name":"Alignment.","entry":"Purebloods are devoid of emotion and see others as tools to manipulate. They care little for law or chaos and are typically neutral evil."},{"type":"item","name":"Size.","entry":"Purebloods match humans in average size and weight. Your size is Medium."},{"type":"item","name":"Speed.","entry":"Your base walking speed is 30 feet."},{"type":"item","name":"Darkvision.","entry":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"type":"item","name":"Innate Spellcasting.","entry":"You know the Poison Spray cantrip. You can cast Animal Friendship an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast Suggestion with this trait. Once you cast it, you can't do so again until you finish a long rest. Charisma is your spellcasting ability for these spells."},{"type":"item","name":"Magic Resistance.","entry":"You have advantage on saving throws against spells and other magical effects."},{"type":"item","name":"Poison Immunity.","entry":"You are immune to poison damage and the poisoned condition."},{"type":"item","name":"Languages.","entry":"You can speak, read, and write Common, Abyssal, and Draconic."}]}],"skillProficiencies":null,"homebrew":true}]`);export{e as t};